select ac_cargar_unidad($ac${"slug":"agua-1","rama":"agua","orden":1,"nivel":1,"titulo_es":"El agua que usamos","bajada_es":"Cuánta agua dulce hay de verdad, cómo llega hasta tu canilla, cuánta usa una casa y a dónde va la que se va.","objetivos_es":["Explicar por qué el agua dulce disponible es una fracción muy chica del agua del planeta","Describir el camino del agua desde el río o la napa hasta la canilla","Estimar cuánta agua usa una casa y en qué se va la mayor parte","Distinguir el desagüe cloacal del pluvial y saber qué no tirar por ninguno","Explicar por qué el agua segura es un tema de salud y un derecho humano"],"repasa":["tronco-1"],"requiere_tronco":1,"fuentes":["usgs-ciclo-agua","unep","aysa","oms-agua-potable","un-water","acumar","acuifero-puelche"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"agua-1.s1","orden":1,"tipo":"leccion","titulo_es":"Mucha agua, poca para usar","bajada_es":"La Tierra está cubierta de agua, pero casi toda es salada o está congelada.","minutos":11,"pasos":[{"slug":"agua-1.s1.p1","orden":1,"grupo":"agua-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El planeta azul, pero salado","cuerpo":["Más de dos tercios de la superficie de la Tierra están cubiertos de agua, y sin embargo el agua que se puede tomar es escasa. Alrededor del 97 % de toda el agua del planeta está en los océanos y es salada.","Del 3 % que es dulce, cerca de dos tercios está congelada en glaciares y casquetes polares, y casi todo el resto está bajo tierra, en acuíferos. Los ríos, lagos y humedales, que es donde la vemos, son menos del 1 % del agua dulce."],"destacado":{"valor":"≈ 3 %","texto":"del agua del planeta es dulce, y la mayor parte de ese 3 % está congelada o bajo tierra."}},"solucion":{}},{"slug":"agua-1.s1.p2","orden":2,"grupo":"agua-1.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si toda el agua del planeta entrara en un bidón de 100 litros, ¿cuánta sería agua dulce?","opciones":[{"id":"o1","texto":"Unos 3 litros"},{"id":"o2","texto":"Unos 50 litros"},{"id":"o3","texto":"Unos 30 litros"},{"id":"o4","texto":"Unos 97 litros"}]},"solucion":{"clave":["o1"],"explicacion":"Unos 97 litros serían salados y solo 3 dulces. Y de esos 3, unos 2 estarían congelados. Lo que corre por ríos y lagos cabría en un vaso chico.","por_opcion":{"o3":"Es un error común pensar que el agua dulce es mucha: es alrededor del 3 %, no del 30 %."}}},{"slug":"agua-1.s1.p3","orden":3,"grupo":"agua-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dónde está el agua dulce","cuerpo":["Los glaciares y hielos guardan la mayor parte del agua dulce del planeta. En Argentina, los glaciares de la cordillera alimentan ríos de los que dependen ciudades y cultivos, y están protegidos por una ley nacional.","Bajo nuestros pies hay acuíferos: capas de arena o roca porosa empapadas de agua, como una esponja. En gran parte de la provincia de Buenos Aires se usa el acuífero Puelche. Muchas ciudades y pueblos del país toman agua de napas subterráneas."],"datos":{"tipo":"barras","titulo":"Dónde está el agua dulce del planeta","unidad":"% del agua dulce","filas":[{"etiqueta":"Glaciares y hielos","valor":69},{"etiqueta":"Agua subterránea","valor":30},{"etiqueta":"Ríos, lagos y humedad","valor":1}],"nota":"Valores aproximados, redondeados."}},"solucion":{}},{"slug":"agua-1.s1.p4","orden":4,"grupo":"agua-1.s1.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená dónde hay más agua dulce en el planeta, de más a menos.","items":[{"id":"i1","texto":"Glaciares y casquetes polares"},{"id":"i2","texto":"Acuíferos subterráneos"},{"id":"i3","texto":"Ríos, lagos y humedad del aire"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Lo que más vemos es lo que menos hay. Por eso cuidar las napas y los glaciares es cuidar la mayor parte del agua dulce.","valores":{"i1":"≈ 69 % del agua dulce","i2":"≈ 30 %","i3":"≈ 1 %"}}},{"slug":"agua-1.s1.p5","orden":5,"grupo":"agua-1.s1.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada lugar con el tipo de agua que guarda.","izquierda":[{"id":"a1","texto":"Océano Atlántico"},{"id":"a2","texto":"Glaciar Perito Moreno"},{"id":"a3","texto":"Acuífero Puelche"},{"id":"a4","texto":"Río Paraná"}],"derecha":[{"id":"b1","texto":"Agua salada"},{"id":"b2","texto":"Agua dulce congelada"},{"id":"b3","texto":"Agua dulce subterránea"},{"id":"b4","texto":"Agua dulce superficial"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro depósitos distintos. El ciclo del agua los conecta a todos, pero a ritmos muy diferentes."}},{"slug":"agua-1.s1.p6","orden":6,"grupo":"agua-1.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el ciclo del agua nunca se detiene, el agua dulce disponible es ilimitada.","razones":[{"id":"r1","texto":"Porque lo que importa es si se usa más rápido de lo que se repone"},{"id":"r2","texto":"Porque el ciclo del agua se detiene en invierno"},{"id":"r3","texto":"Porque el agua dulce se fabrica en las nubes cada día"}]},"solucion":{"valor":false,"explicacion":"El agua da vueltas, pero la cantidad disponible en un lugar y un momento es limitada. Si se saca de una napa más rápido de lo que la lluvia la repone, baja. Es la idea de ritmo de uso que viste en el tronco.","clave":["r1"]}},{"slug":"agua-1.s1.p7","orden":7,"grupo":"agua-1.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No todo el mundo tiene la misma agua","cuerpo":["El agua dulce no está repartida en forma pareja. Hay regiones con ríos enormes y otras áridas, donde cada litro cuenta. En Argentina conviven las dos cosas: el Litoral con algunos de los ríos más caudalosos del mundo y zonas de Cuyo o la Patagonia extraandina con muy poca lluvia.","Cuando una región usa casi toda el agua que se renueva por año, se habla de estrés hídrico. Ahí cualquier sequía o contaminación se siente enseguida."]},"solucion":{}},{"slug":"agua-1.s1.p8","orden":8,"grupo":"agua-1.s1.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Estas zonas tienen mucha agua dulce disponible o poca?","grupos":[{"id":"g1","nombre":"Mucha agua disponible"},{"id":"g2","nombre":"Poca agua disponible"}],"items":[{"id":"i1","texto":"Delta del Paraná"},{"id":"i2","texto":"Llanos de La Rioja"},{"id":"i3","texto":"Esteros del Iberá"},{"id":"i4","texto":"Meseta patagónica"},{"id":"i5","texto":"Selva misionera"},{"id":"i6","texto":"Monte de San Juan"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La misma acción de cuidado vale en todos lados, pero en las zonas secas la diferencia se nota mucho antes."}},{"slug":"agua-1.s1.p9","orden":9,"grupo":"agua-1.s1.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una región llega al estrés hídrico.","items":[{"id":"i1","texto":"La población y los cultivos de una región crecen"},{"id":"i2","texto":"Se saca cada vez más agua de ríos y napas"},{"id":"i3","texto":"El uso se acerca a toda el agua que se renueva por año"},{"id":"i4","texto":"Queda poco margen para una sequía o una contaminación"},{"id":"i5","texto":"Cualquier problema se convierte en falta de agua"},{"id":"i6","texto":"El estrés hídrico aparece solo en regiones con mucha lluvia"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El estrés hídrico no depende solo de cuánta lluvia hay, sino de cuánto se usa frente a lo que se renueva."}},{"slug":"agua-1.s1.p10","orden":10,"grupo":"agua-1.s1.p10","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Casi toda el agua del planeta es {{0}}. De la poca agua dulce, la mayor parte está {{1}} o bajo {{2}}.","banco":[{"id":"w1","texto":"salada"},{"id":"w2","texto":"congelada"},{"id":"w3","texto":"tierra"},{"id":"w4","texto":"caliente"},{"id":"w5","texto":"evaporada"},{"id":"w6","texto":"contaminada"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Salada, congelada o subterránea: por eso el agua de ríos y lagos, la más fácil de usar, es una fracción mínima."}},{"slug":"agua-1.s1.p11","orden":11,"grupo":"agua-1.s1.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del agua dulce del planeta está en ríos, lagos y humedad del aire.","min":0.1,"max":100,"paso":1,"unidad":"%","escala":"log"},"solucion":{"valor":1,"banda":"log","explicacion":"Alrededor del 1 % o menos. El agua que vemos correr es una parte mínima del agua dulce total."}},{"slug":"agua-1.s1.p12","orden":12,"grupo":"agua-1.s1.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué proteger los glaciares importa aunque estén lejos de las ciudades?","opciones":[{"id":"o1","texto":"Porque guardan agua que alimenta ríos de ciudades y cultivos"},{"id":"o2","texto":"Porque el hielo se puede vender como agua embotellada"},{"id":"o3","texto":"Porque son lindos y atraen turismo a la cordillera"},{"id":"o4","texto":"Porque en los glaciares viven la mayoría de los animales"}]},"solucion":{"clave":["o1"],"explicacion":"En épocas secas, los ríos de cordillera dependen en buena parte del deshielo. Un glaciar es una reserva de agua que se libera de a poco.","por_opcion":{"o3":"Son hermosos, pero su valor principal es el agua que aportan a los ríos."}}},{"slug":"agua-1.s1.p13","orden":13,"grupo":"agua-1.s1.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este texto de un folleto y marcá las afirmaciones falsas.","segmentos":[{"id":"s1","texto":"La mayor parte del agua del planeta está en los océanos."},{"id":"s2","texto":"Como hay tanta agua, el agua dulce nunca va a faltar en ningún lugar."},{"id":"s3","texto":"Los acuíferos guardan agua dulce bajo tierra, como una esponja."},{"id":"s4","texto":"Los ríos y lagos tienen la mayor parte del agua dulce del mundo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo que se ve (ríos, lagos) es la parte más chica. Lo que más hay está congelado o bajo tierra, y lo que se usa depende de cada región.","por_opcion":{"s2":"Hay regiones con estrés hídrico: usan casi toda el agua que se renueva por año.","s4":"Tienen menos del 1 %: la mayoría está en hielos y bajo tierra."}}}]},{"slug":"agua-1.s2","orden":2,"tipo":"leccion","titulo_es":"Del río a tu canilla","bajada_es":"Qué le pasa al agua antes de llegar a tu vaso: captación, potabilización y red.","minutos":11,"pasos":[{"slug":"agua-1.s2.p1","orden":1,"grupo":"agua-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Primero hay que tomarla de algún lado","cuerpo":["El agua de red se toma de dos tipos de fuente: superficial (un río, un lago, un embalse) o subterránea (una napa, con perforaciones). En el Área Metropolitana de Buenos Aires, la mayor parte sale del Río de la Plata; en muchas ciudades del interior, de napas o de ríos cercanos.","Ese paso se llama captación. El agua cruda nunca es apta para tomar tal como viene: puede tener barro, restos vegetales, microorganismos o sustancias disueltas."]},"solucion":{}},{"slug":"agua-1.s2.p2","orden":2,"grupo":"agua-1.s2.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿La fuente de agua es superficial o subterránea?","grupos":[{"id":"g1","nombre":"Superficial"},{"id":"g2","nombre":"Subterránea"}],"items":[{"id":"i1","texto":"El Río de la Plata"},{"id":"i2","texto":"El acuífero Puelche"},{"id":"i3","texto":"Un embalse de montaña"},{"id":"i4","texto":"Una perforación en un campo"},{"id":"i5","texto":"El río Paraná"},{"id":"i6","texto":"Un pozo de agua de un pueblo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Superficial es lo que corre o se junta a cielo abierto; subterránea, lo que está en los poros del suelo y se saca con bombas."}},{"slug":"agua-1.s2.p3","orden":3,"grupo":"agua-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La potabilización, paso a paso","cuerpo":["En una planta potabilizadora, primero se le agregan al agua sustancias que hacen que las partículas chiquitas se peguen entre sí (coagulación) y formen grumos más grandes (floculación). Esos grumos, más pesados, se van al fondo en grandes piletas (sedimentación o decantación).","Después el agua pasa por filtros de arena y otros materiales que retienen lo que quedó. Al final se desinfecta, en general con cloro, para eliminar microorganismos y para que siga protegida mientras viaja por los caños hasta tu casa."],"lista":["Captación: se toma del río o la napa","Coagulación y floculación: las partículas forman grumos","Sedimentación: los grumos se van al fondo","Filtración: filtros retienen lo que queda","Desinfección: el cloro elimina microorganismos"]},"solucion":{}},{"slug":"agua-1.s2.p4","orden":4,"grupo":"agua-1.s2.p4","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas de la potabilización.","items":[{"id":"i1","texto":"Captación del agua del río"},{"id":"i2","texto":"Coagulación y floculación"},{"id":"i3","texto":"Sedimentación"},{"id":"i4","texto":"Filtración"},{"id":"i5","texto":"Desinfección con cloro"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada etapa saca algo distinto: primero lo grande, después lo fino y al final lo invisible. Saltearse una deja pasar lo que la siguiente no puede sacar."}},{"slug":"agua-1.s2.p5","orden":5,"grupo":"agua-1.s2.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada etapa con lo que logra.","izquierda":[{"id":"a1","texto":"Floculación"},{"id":"a2","texto":"Sedimentación"},{"id":"a3","texto":"Filtración"},{"id":"a4","texto":"Desinfección"}],"derecha":[{"id":"b1","texto":"Que las partículas chiquitas se junten en grumos"},{"id":"b2","texto":"Que los grumos se vayan al fondo"},{"id":"b3","texto":"Retener las partículas que quedaron flotando"},{"id":"b4","texto":"Eliminar microorganismos que causan enfermedades"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Es un sistema en serie: cada paso deja el agua lista para el siguiente."}},{"slug":"agua-1.s2.p6","orden":6,"grupo":"agua-1.s2.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El cloro se agrega al agua solamente para que tenga buen gusto.","razones":[{"id":"r1","texto":"Porque desinfecta y protege el agua en la red"},{"id":"r2","texto":"Porque el cloro le agrega minerales necesarios"},{"id":"r3","texto":"Porque el cloro hace que el agua pese menos"}]},"solucion":{"valor":false,"explicacion":"El cloro desinfecta: elimina bacterias y virus, y además deja un resto que protege el agua mientras recorre kilómetros de caños. El gusto a cloro es un efecto, no el objetivo.","clave":["r1"]}},{"slug":"agua-1.s2.p7","orden":7,"grupo":"agua-1.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Del caño a tu vaso","cuerpo":["Una vez potabilizada, el agua se bombea por una red de caños que recorre la ciudad. En muchos edificios y casas sube a un tanque, y desde ahí baja a las canillas.","El tanque también es parte del cuidado: si está sucio o destapado, el agua puede contaminarse después de haber salido perfecta de la planta. Por eso se recomienda limpiarlo con regularidad, en general cada seis meses."]},"solucion":{}},{"slug":"agua-1.s2.p8","orden":8,"grupo":"agua-1.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido del agua hasta tu vaso.","items":[{"id":"i1","texto":"Se capta agua del río"},{"id":"i2","texto":"Se potabiliza en una planta"},{"id":"i3","texto":"Viaja por la red de caños"},{"id":"i4","texto":"Sube al tanque de la casa"},{"id":"i5","texto":"Sale por la canilla"},{"id":"i6","texto":"Se evapora y vuelve como lluvia a la canilla"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La evaporación es parte del ciclo natural, pero no del camino por la red. En la red el agua viaja por caños, empujada por bombas."}},{"slug":"agua-1.s2.p9","orden":9,"grupo":"agua-1.s2.p9","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué puede contaminar el agua después de que sale limpia de la planta? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"Un tanque de la casa sucio o sin tapa"},{"id":"o2","texto":"Una rotura en un caño por donde entra suciedad"},{"id":"o3","texto":"Una conexión mal hecha entre la red y otra instalación"},{"id":"o4","texto":"El cloro que le agregó la planta"},{"id":"o5","texto":"Que el agua esté fría"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La planta entrega agua segura, pero el último tramo —la red y la instalación de cada casa— también tiene que estar en condiciones."}},{"slug":"agua-1.s2.p10","orden":10,"grupo":"agua-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un tanque de 1.000 litros abastece a una casa que usa 1.000 litros por día. Si se corta el agua de red, ¿cuántos días dura el tanque lleno?","unidad":"días","decimales":0,"contexto":"Tanque de 1000 litros; consumo de 1000 litros por día."},"solucion":{"valor":1,"tolerancia":0.5,"explicacion":"1.000 ÷ 1.000 = 1 día. El tanque es una reserva: por eso conviene cuidarlo limpio y tapado."}},{"slug":"agua-1.s2.p10.v2","orden":10,"grupo":"agua-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un tanque de 500 litros abastece a una casa que usa 250 litros por día. Si se corta el agua de red, ¿cuántos días dura el tanque lleno?","unidad":"días","decimales":0,"contexto":"Tanque de 500 litros; consumo de 250 litros por día."},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"500 ÷ 250 = 2 días. El tanque es una reserva: por eso conviene cuidarlo limpio y tapado."}},{"slug":"agua-1.s2.p10.v3","orden":10,"grupo":"agua-1.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un tanque de 2.000 litros abastece a una casa que usa 500 litros por día. Si se corta el agua de red, ¿cuántos días dura el tanque lleno?","unidad":"días","decimales":0,"contexto":"Tanque de 2000 litros; consumo de 500 litros por día."},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"2.000 ÷ 500 = 4 días. El tanque es una reserva: por eso conviene cuidarlo limpio y tapado."}},{"slug":"agua-1.s2.p11","orden":11,"grupo":"agua-1.s2.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un pueblo que toma agua de una napa, el agua sale limpia y transparente del pozo. ¿Se puede tomar sin tratarla?","opciones":[{"id":"o1","texto":"No siempre: puede tener microbios o sustancias que no se ven"},{"id":"o2","texto":"Sí, si sale transparente del pozo ya es segura para tomar"},{"id":"o3","texto":"Sí, porque el agua subterránea nunca se contamina"},{"id":"o4","texto":"No, porque el agua de las napas siempre es salada y dura"}]},"solucion":{"clave":["o1"],"explicacion":"Transparente no es lo mismo que segura. Por eso el agua de red se analiza y se desinfecta aunque venga de una napa.","por_opcion":{"o3":"Las napas se pueden contaminar, por ejemplo con nitratos de fertilizantes o con pozos ciegos cercanos."}}},{"slug":"agua-1.s2.p12","orden":12,"grupo":"agua-1.s2.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá el proceso.","texto":"En la planta, las partículas se juntan en {{0}}, que se van al {{1}}, y al final el agua se {{2}}.","banco":[{"id":"w1","texto":"grumos"},{"id":"w2","texto":"fondo"},{"id":"w3","texto":"desinfecta"},{"id":"w4","texto":"congela"},{"id":"w5","texto":"evapora"},{"id":"w6","texto":"sala"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Juntar, dejar caer, filtrar y desinfectar: la receta de casi todas las plantas potabilizadoras del mundo."}},{"slug":"agua-1.s2.p13","orden":13,"grupo":"agua-1.s2.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cada cuánto se recomienda limpiar el tanque de agua de una casa?","opciones":[{"id":"o1","texto":"En general, cada seis meses"},{"id":"o2","texto":"Una vez cada diez años"},{"id":"o3","texto":"Nunca, porque el cloro lo mantiene limpio solo"},{"id":"o4","texto":"Solamente cuando el agua sale de color"}]},"solucion":{"clave":["o1"],"explicacion":"La recomendación habitual es cada seis meses. Esperar a que el agua salga turbia es esperar a que el problema ya sea visible.","por_opcion":{"o3":"El cloro ayuda, pero no evita que se acumulen sedimentos y suciedad en el tanque."}}}]},{"slug":"agua-1.s3","orden":3,"tipo":"leccion","titulo_es":"Cuánta agua usa una casa","bajada_es":"Ducha, inodoro, lavarropas: en qué se va el agua de todos los días, con números.","minutos":12,"pasos":[{"slug":"agua-1.s3.p1","orden":1,"grupo":"agua-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que cubre las necesidades básicas","cuerpo":["Naciones Unidas considera que entre 50 y 100 litros por persona por día alcanzan para cubrir las necesidades básicas: tomar, cocinar, higienizarse y limpiar. Muchas casas usan bastante más que eso.","Para saber cuánto usa tu casa, podés mirar la factura (si tiene medidor, marca metros cúbicos) o hacer la cuenta por usos: cuántos minutos de ducha, cuántas descargas del inodoro, cuántos lavados."],"destacado":{"valor":"50–100 L","texto":"por persona por día cubren las necesidades básicas, según Naciones Unidas."}},"solucion":{}},{"slug":"agua-1.s3.p2","orden":2,"grupo":"agua-1.s3.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"En qué se va el agua","cuerpo":["En una casa típica, los usos que más pesan son la ducha y el inodoro. Una ducha común entrega unos 10 litros por minuto (varía entre 6 y 15 según la flor y la presión). Un inodoro viejo usa 10 a 15 litros por descarga; uno de doble descarga, 3 o 6.","El lavarropas automático usa decenas de litros por lavado, y una canilla abierta entrega unos 6 a 10 litros por minuto. Lavar los platos con la canilla corriendo puede gastar más que un lavado con la pileta llena."],"datos":{"tipo":"tabla","titulo":"Consumos típicos de una casa (aproximados)","columnas":["Uso","Cantidad"],"filas":[["Ducha","≈ 10 litros por minuto"],["Inodoro común","10 a 15 litros por descarga"],["Inodoro de doble descarga","3 o 6 litros"],["Canilla abierta","6 a 10 litros por minuto"],["Lavarropas automático","decenas de litros por lavado"]],"nota":"Los valores cambian según el aparato y la presión del agua."}},"solucion":{}},{"slug":"agua-1.s3.p3","orden":3,"grupo":"agua-1.s3.p3","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"La ducha de una familia","planteo":"En una casa viven 4 personas y cada una se ducha 10 minutos por día. La ducha entrega 10 litros por minuto. ¿Cuánta agua usan en duchas por día?","pasos":["Por persona: 10 minutos × 10 litros por minuto = 100 litros.","Toda la familia: 100 litros × 4 personas = 400 litros por día."],"resultado":"Solo en duchas, 400 litros por día: 12.000 litros en un mes. Cada minuto que se acorta la ducha, por persona, ahorra 10 litros diarios."},"solucion":{}},{"slug":"agua-1.s3.p4","orden":4,"grupo":"agua-1.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ducha entrega 10 litros por minuto y dura 8 minutos. ¿Cuántos litros usa?","unidad":"litros","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"Litros por minuto por minutos de ducha: 10 × 8 = 80 litros. Es la cuenta que conviene hacer con tu propia ducha."}},{"slug":"agua-1.s3.p4.v2","orden":4,"grupo":"agua-1.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ducha entrega 12 litros por minuto y dura 12 minutos. ¿Cuántos litros usa?","unidad":"litros","decimales":0},"solucion":{"valor":144,"tolerancia":2.88,"explicacion":"Litros por minuto por minutos de ducha: 12 × 12 = 144 litros. Es la cuenta que conviene hacer con tu propia ducha."}},{"slug":"agua-1.s3.p4.v3","orden":4,"grupo":"agua-1.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ducha entrega 10 litros por minuto y dura 15 minutos. ¿Cuántos litros usa?","unidad":"litros","decimales":0},"solucion":{"valor":150,"tolerancia":3,"explicacion":"Litros por minuto por minutos de ducha: 10 × 15 = 150 litros. Es la cuenta que conviene hacer con tu propia ducha."}},{"slug":"agua-1.s3.p4.v4","orden":4,"grupo":"agua-1.s3.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ducha entrega 9 litros por minuto y dura 6 minutos. ¿Cuántos litros usa?","unidad":"litros","decimales":0},"solucion":{"valor":54,"tolerancia":1.08,"explicacion":"Litros por minuto por minutos de ducha: 9 × 6 = 54 litros. Es la cuenta que conviene hacer con tu propia ducha."}},{"slug":"agua-1.s3.p5","orden":5,"grupo":"agua-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 3 personas, cada una usa el inodoro 6 veces por día, y cada descarga gasta 12 litros. ¿Cuántos litros por día se van por el inodoro?","unidad":"litros","decimales":0},"solucion":{"valor":216,"tolerancia":4.32,"explicacion":"Descargas por día: 6 × 3 personas = 18. Por 12 litros cada una: 18 × 12 = 216 litros por día."}},{"slug":"agua-1.s3.p5.v2","orden":5,"grupo":"agua-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 4 personas, cada una usa el inodoro 5 veces por día, y cada descarga gasta 12 litros. ¿Cuántos litros por día se van por el inodoro?","unidad":"litros","decimales":0},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"Descargas por día: 5 × 4 personas = 20. Por 12 litros cada una: 20 × 12 = 240 litros por día."}},{"slug":"agua-1.s3.p5.v3","orden":5,"grupo":"agua-1.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 2 personas, cada una usa el inodoro 8 veces por día, y cada descarga gasta 10 litros. ¿Cuántos litros por día se van por el inodoro?","unidad":"litros","decimales":0},"solucion":{"valor":160,"tolerancia":3.2,"explicacion":"Descargas por día: 8 × 2 personas = 16. Por 10 litros cada una: 16 × 10 = 160 litros por día."}},{"slug":"agua-1.s3.p6","orden":6,"grupo":"agua-1.s3.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos usos de un día por los litros que gastan, de más a menos.","items":[{"id":"i1","texto":"Una ducha de 15 minutos"},{"id":"i2","texto":"Seis descargas de un inodoro común"},{"id":"i3","texto":"Lavar los platos 10 minutos con la canilla abierta"},{"id":"i4","texto":"Cepillarse los dientes 2 minutos con la canilla abierta"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La ducha larga encabeza. Fijate que lavar platos con la canilla corriendo puede superar al inodoro: por eso \"llenar la pileta\" es un consejo que rinde.","valores":{"i1":"≈ 150 litros","i2":"≈ 70 litros","i3":"≈ 80 litros","i4":"≈ 16 litros"}}},{"slug":"agua-1.s3.p7","orden":7,"grupo":"agua-1.s3.p7","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este uso del agua está entre los básicos o es un uso que se puede reducir mucho?","grupos":[{"id":"g1","nombre":"Básico"},{"id":"g2","nombre":"Se puede reducir mucho"}],"items":[{"id":"i1","texto":"Tomar agua"},{"id":"i2","texto":"Duchas de 20 minutos"},{"id":"i3","texto":"Cocinar"},{"id":"i4","texto":"Lavar la vereda con manguera"},{"id":"i5","texto":"Higienizarse"},{"id":"i6","texto":"Lavarropas con media carga"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los usos básicos entran en los 50 a 100 litros por persona; los grandes ahorros están en el resto."}},{"slug":"agua-1.s3.p8","orden":8,"grupo":"agua-1.s3.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cerrar la canilla mientras te cepillás los dientes no ahorra casi nada.","razones":[{"id":"r1","texto":"Porque son varios litros por vez que se multiplican por personas y días"},{"id":"r2","texto":"Porque la canilla no gasta agua mientras no se usa el vaso"},{"id":"r3","texto":"Porque el agua de la canilla vuelve sola al tanque"}]},"solucion":{"valor":false,"explicacion":"Con una canilla que entrega unos 8 litros por minuto, dos minutos abierta son 16 litros. Dos veces por día, en una casa de cuatro personas, son más de 100 litros diarios.","clave":["r1"]}},{"slug":"agua-1.s3.p9","orden":9,"grupo":"agua-1.s3.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 4 personas cada una deja la canilla abierta 2 minutos al cepillarse, dos veces por día. Si la canilla entrega 8 litros por minuto, ¿cuántos litros podrían ahorrar por día cerrándola?","unidad":"litros","decimales":0},"solucion":{"valor":128,"tolerancia":2.56,"explicacion":"Por persona: 2 minutos × 2 veces × 8 litros = 32 litros por día. Para 4 personas: 32 × 4 = 128 litros por día."}},{"slug":"agua-1.s3.p9.v2","orden":9,"grupo":"agua-1.s3.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 3 personas cada una deja la canilla abierta 2 minutos al cepillarse, dos veces por día. Si la canilla entrega 8 litros por minuto, ¿cuántos litros podrían ahorrar por día cerrándola?","unidad":"litros","decimales":0},"solucion":{"valor":96,"tolerancia":1.92,"explicacion":"Por persona: 2 minutos × 2 veces × 8 litros = 32 litros por día. Para 3 personas: 32 × 3 = 96 litros por día."}},{"slug":"agua-1.s3.p9.v3","orden":9,"grupo":"agua-1.s3.p9","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 5 personas cada una deja la canilla abierta 2 minutos al cepillarse, dos veces por día. Si la canilla entrega 8 litros por minuto, ¿cuántos litros podrían ahorrar por día cerrándola?","unidad":"litros","decimales":0},"solucion":{"valor":160,"tolerancia":3.2,"explicacion":"Por persona: 2 minutos × 2 veces × 8 litros = 32 litros por día. Para 5 personas: 32 × 5 = 160 litros por día."}},{"slug":"agua-1.s3.p10","orden":10,"grupo":"agua-1.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos cambios bajan el consumo de agua de una casa sin perder comodidad? Marcá todos.","opciones":[{"id":"o1","texto":"Un aireador en la canilla, que mezcla aire con el agua"},{"id":"o2","texto":"Una flor de ducha de bajo caudal"},{"id":"o3","texto":"Usar la descarga corta del inodoro cuando alcanza"},{"id":"o4","texto":"Poner el lavarropas solo con carga completa"},{"id":"o5","texto":"Dejar la canilla abierta para que el agua \"salga fresca\""}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Aireadores, flores eficientes, doble descarga y cargas completas ahorran mucho sin cambiar la rutina. Son los primeros pasos que verás en la próxima unidad."}},{"slug":"agua-1.s3.p11","orden":11,"grupo":"agua-1.s3.p11","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Medir lo propio","cuerpo":["La mejor forma de saber dónde conviene ahorrar es medir tu casa. Un truco simple: poné un balde debajo de la ducha y contá cuántos segundos tarda en llenar 10 litros. Si tarda 60 segundos, tu ducha entrega 10 litros por minuto; si tarda 40, entrega 15.","Con ese número y los minutos de ducha, sabés cuánto usás. Es la misma idea de la unidad de medir: primero el dato propio, después la decisión."]},"solucion":{}},{"slug":"agua-1.s3.p12","orden":12,"grupo":"agua-1.s3.p12","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un balde de 10 litros se llena en 40 segundos debajo de tu ducha. ¿Cuántos litros por minuto entrega?","unidad":"litros por minuto","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"En 40 segundos salen 10 litros. En 60 segundos salen 10 × 60 ÷ 40 = 15 litros por minuto."}},{"slug":"agua-1.s3.p12.v2","orden":12,"grupo":"agua-1.s3.p12","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un balde de 10 litros se llena en 60 segundos debajo de tu ducha. ¿Cuántos litros por minuto entrega?","unidad":"litros por minuto","decimales":1},"solucion":{"valor":10,"tolerancia":0.2,"explicacion":"En 60 segundos salen 10 litros. En 60 segundos salen 10 × 60 ÷ 60 = 10 litros por minuto."}},{"slug":"agua-1.s3.p12.v3","orden":12,"grupo":"agua-1.s3.p12","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un balde de 10 litros se llena en 75 segundos debajo de tu ducha. ¿Cuántos litros por minuto entrega?","unidad":"litros por minuto","decimales":1},"solucion":{"valor":8,"tolerancia":0.16,"explicacion":"En 75 segundos salen 10 litros. En 60 segundos salen 10 × 60 ÷ 75 = 8 litros por minuto."}},{"slug":"agua-1.s3.p13","orden":13,"grupo":"agua-1.s3.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá la regla para medir tu ducha.","texto":"Se cuenta cuántos {{0}} tarda en llenarse un balde de {{1}}, y con eso se calculan los litros por {{2}}.","banco":[{"id":"w1","texto":"segundos"},{"id":"w2","texto":"10 litros"},{"id":"w3","texto":"minuto"},{"id":"w4","texto":"metros"},{"id":"w5","texto":"kilos"},{"id":"w6","texto":"días"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Un balde, un reloj y una división: con eso sabés cuánto entrega tu ducha, que es el primer dato para ahorrar."}},{"slug":"agua-1.s3.p14","orden":14,"grupo":"agua-1.s3.p14","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una familia de 4 usa 800 litros de agua por día. ¿Está dentro del rango que Naciones Unidas considera suficiente para necesidades básicas (50 a 100 litros por persona)?","opciones":[{"id":"o1","texto":"No: son 200 litros por persona, el doble del máximo del rango"},{"id":"o2","texto":"Sí: 800 litros está dentro de 50 a 100"},{"id":"o3","texto":"Sí: 200 por persona es poco para una casa"},{"id":"o4","texto":"No se puede saber sin conocer la marca de la ducha"}]},"solucion":{"clave":["o1"],"explicacion":"800 ÷ 4 = 200 litros por persona por día. Hay que comparar en la misma unidad: por persona y por día.","por_opcion":{"o3":"El rango de necesidades básicas es de 50 a 100 litros por persona: 200 lo supera."}}}]},{"slug":"agua-1.s4","orden":4,"tipo":"leccion","titulo_es":"El agua que se va","bajada_es":"Dos redes debajo de la calle: la cloaca y el pluvial. Qué va por cada una y qué no va por ninguna.","minutos":12,"pasos":[{"slug":"agua-1.s4.p1","orden":1,"grupo":"agua-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Aguas grises y aguas negras","cuerpo":["El agua que usamos no desaparece: se va por el desagüe. La de la ducha, las piletas y el lavarropas se llama agua gris: tiene jabón y restos, pero no desechos del inodoro. La del inodoro es agua negra.","Las dos, en una ciudad con cloacas, viajan juntas por la red cloacal hasta una planta de tratamiento, que les saca buena parte de la contaminación antes de devolverlas a un río."]},"solucion":{}},{"slug":"agua-1.s4.p2","orden":2,"grupo":"agua-1.s4.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es agua gris o agua negra?","grupos":[{"id":"g1","nombre":"Agua gris"},{"id":"g2","nombre":"Agua negra"}],"items":[{"id":"i1","texto":"El agua de la ducha"},{"id":"i2","texto":"El agua del inodoro"},{"id":"i3","texto":"El agua del lavarropas"},{"id":"i4","texto":"El agua de un pozo ciego"},{"id":"i5","texto":"El agua de lavar los platos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"La diferencia importa porque el agua gris, con cuidado, se puede reutilizar (por ejemplo, para el inodoro), y la negra no."}},{"slug":"agua-1.s4.p3","orden":3,"grupo":"agua-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Dos redes distintas","cuerpo":["Debajo de muchas calles hay dos sistemas separados. La red cloacal lleva lo que sale de las casas hacia una planta de tratamiento. La red pluvial junta el agua de lluvia de las calles, por las rejillas y los sumideros de las esquinas, y la lleva directo a un arroyo o al río, sin tratar.","Por eso lo que tirás en la vereda o en la rejilla de la esquina termina en el río tal cual: una colilla, una bolsa o el aceite del auto."],"destacado":{"valor":"Rejilla = río","texto":"lo que entra por la rejilla de la esquina llega al arroyo sin ningún tratamiento."}},"solucion":{}},{"slug":"agua-1.s4.p4","orden":4,"grupo":"agua-1.s4.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el camino de una colilla tirada en la vereda.","items":[{"id":"i1","texto":"Una colilla queda en la vereda"},{"id":"i2","texto":"La lluvia la arrastra hasta la rejilla de la esquina"},{"id":"i3","texto":"Viaja por la red pluvial"},{"id":"i4","texto":"Sale sin tratar a un arroyo"},{"id":"i5","texto":"El arroyo la lleva al río"},{"id":"i6","texto":"Pasa por la planta de tratamiento de la cloaca"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La red pluvial no pasa por ninguna planta: por eso \"tirar a la calle\" es tirar al río."}},{"slug":"agua-1.s4.p5","orden":5,"grupo":"agua-1.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Todo lo que entra por las rejillas de la calle pasa por una planta de tratamiento antes de llegar al río.","razones":[{"id":"r1","texto":"Porque la red pluvial desemboca directo en arroyos y ríos"},{"id":"r2","texto":"Porque la lluvia limpia todo lo que arrastra"},{"id":"r3","texto":"Porque las rejillas están conectadas al tanque de agua potable"}]},"solucion":{"valor":false,"explicacion":"Las rejillas son parte de la red pluvial, que en general desemboca directo en arroyos y ríos. Solo la red cloacal lleva el agua a plantas de tratamiento.","clave":["r1"]}},{"slug":"agua-1.s4.p6","orden":6,"grupo":"agua-1.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que nunca va por el desagüe","cuerpo":["Algunas cosas tapan caños o dañan las plantas de tratamiento: toallitas húmedas (aunque digan \"biodegradables\", no se deshacen a tiempo), pañales, hilo dental, algodones y restos de comida grandes. Otras contaminan el agua y son muy difíciles de sacar: el aceite de cocina, los medicamentos, las pinturas y los solventes.","Un litro de aceite usado puede contaminar muchísima agua y forma tapones de grasa en los caños. Se junta en una botella y se lleva a un punto de recolección, donde se puede convertir en biodiésel."]},"solucion":{}},{"slug":"agua-1.s4.p7","orden":7,"grupo":"agua-1.s4.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué va por el inodoro y qué no?","grupos":[{"id":"g1","nombre":"Puede ir por el inodoro"},{"id":"g2","nombre":"No va por el inodoro"}],"items":[{"id":"i1","texto":"Papel higiénico"},{"id":"i2","texto":"Toallitas húmedas"},{"id":"i3","texto":"Desechos del cuerpo"},{"id":"i4","texto":"Aceite de cocina usado"},{"id":"i5","texto":"Medicamentos vencidos"},{"id":"i6","texto":"Algodones y cotonetes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2","i6":"g2"},"explicacion":"El inodoro solo está pensado para dos cosas. Todo lo demás tapa caños, daña la planta o termina contaminando el río."}},{"slug":"agua-1.s4.p8","orden":8,"grupo":"agua-1.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que cada litro de aceite usado puede contaminar 1.000 litros de agua. Si un comercio tira 1 litro por semana a la pileta, ¿cuántos litros de agua puede contaminar por semana?","unidad":"litros","decimales":0,"contexto":"1 litros de aceite por semana; factor de 1000."},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"1 × 1.000 = 1.000 litros por semana. Valores de ejemplo: el punto es que poco aceite afecta muchísima agua, por eso se junta y se recicla."}},{"slug":"agua-1.s4.p8.v2","orden":8,"grupo":"agua-1.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que cada litro de aceite usado puede contaminar 1.000 litros de agua. Si un comercio tira 2 litros por semana a la pileta, ¿cuántos litros de agua puede contaminar por semana?","unidad":"litros","decimales":0,"contexto":"2 litros de aceite por semana; factor de 1000."},"solucion":{"valor":2000,"tolerancia":40,"explicacion":"2 × 1.000 = 2.000 litros por semana. Valores de ejemplo: el punto es que poco aceite afecta muchísima agua, por eso se junta y se recicla."}},{"slug":"agua-1.s4.p8.v3","orden":8,"grupo":"agua-1.s4.p8","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que cada litro de aceite usado puede contaminar 1.000 litros de agua. Si un comercio tira 5 litros por semana a la pileta, ¿cuántos litros de agua puede contaminar por semana?","unidad":"litros","decimales":0,"contexto":"5 litros de aceite por semana; factor de 1000."},"solucion":{"valor":5000,"tolerancia":100,"explicacion":"5 × 1.000 = 5.000 litros por semana. Valores de ejemplo: el punto es que poco aceite afecta muchísima agua, por eso se junta y se recicla."}},{"slug":"agua-1.s4.p9","orden":9,"grupo":"agua-1.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conviene hacer con el aceite usado de freír?","opciones":[{"id":"o1","texto":"Guardarlo frío en una botella y llevarlo a un punto limpio"},{"id":"o2","texto":"Tirarlo por la pileta con agua caliente para que no tape"},{"id":"o3","texto":"Tirarlo por el inodoro, que tiene más caudal y no se tapa"},{"id":"o4","texto":"Tirarlo en la rejilla de la calle cuando llueve mucho"}]},"solucion":{"clave":["o1"],"explicacion":"El aceite nunca va por ningún desagüe. Juntado en botellas, se recicla y puede convertirse en biodiésel.","por_opcion":{"o3":"El caudal no ayuda: la grasa se enfría en los caños, forma tapones y contamina el agua."}}},{"slug":"agua-1.s4.p10","orden":10,"grupo":"agua-1.s4.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Donde no hay cloacas","cuerpo":["No todas las casas están conectadas a una red cloacal. En muchas zonas se usan pozos ciegos o cámaras sépticas: el agua negra se infiltra en el suelo. Si el pozo está cerca de una perforación de agua o de la napa, la puede contaminar.","Por eso ampliar las redes de cloacas es una de las obras con más impacto en la salud y en el agua de un barrio, y por eso los pozos de agua y los pozos ciegos tienen que estar bien separados."]},"solucion":{}},{"slug":"agua-1.s4.p11","orden":11,"grupo":"agua-1.s4.p11","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un pozo ciego mal ubicado puede enfermar a una familia.","items":[{"id":"i1","texto":"El pozo ciego está muy cerca del pozo de agua"},{"id":"i2","texto":"El agua negra se infiltra en el suelo"},{"id":"i3","texto":"Llega a la napa de donde se toma el agua"},{"id":"i4","texto":"La familia toma agua con microorganismos"},{"id":"i5","texto":"El cloro de la red limpia el pozo ciego"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuando la casa toma agua de su propio pozo, no pasa por ninguna planta ni recibe cloro de la red. Por eso la distancia entre pozos es clave."}},{"slug":"agua-1.s4.p12","orden":12,"grupo":"agua-1.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos que circulan en un grupo del barrio y marcá los equivocados.","segmentos":[{"id":"s1","texto":"Juntá el aceite usado en una botella y llevalo al punto limpio."},{"id":"s2","texto":"Las toallitas húmedas biodegradables se pueden tirar al inodoro sin problema."},{"id":"s3","texto":"No barras las hojas y la tierra a la rejilla de la esquina."},{"id":"s4","texto":"Los medicamentos vencidos se tiran por la pileta con mucha agua."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La etiqueta \"biodegradable\" no significa que se deshaga en el tiempo que tarda en recorrer un caño. Y diluir no es eliminar.","por_opcion":{"s2":"Tardan mucho en deshacerse y tapan caños y bombas.","s4":"Contaminan el agua: se llevan a farmacias o puntos de recolección."}}},{"slug":"agua-1.s4.p13","orden":13,"grupo":"agua-1.s4.p13","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada red o sistema con lo que transporta.","izquierda":[{"id":"a1","texto":"Red cloacal"},{"id":"a2","texto":"Red pluvial"},{"id":"a3","texto":"Red de agua potable"},{"id":"a4","texto":"Pozo ciego"}],"derecha":[{"id":"b1","texto":"Aguas grises y negras de las casas"},{"id":"b2","texto":"Agua de lluvia de calles y veredas"},{"id":"b3","texto":"Agua tratada para las canillas"},{"id":"b4","texto":"Aguas negras que se infiltran en el suelo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro sistemas de agua conviven en un barrio. Confundirlos es la razón de muchas malas costumbres, como barrer basura a la rejilla."}},{"slug":"agua-1.s4.p14","orden":14,"grupo":"agua-1.s4.p14","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hábitos cuidan el agua que se va de tu casa? Marcá todos.","opciones":[{"id":"o1","texto":"Tirar las toallitas y los algodones al tacho, no al inodoro"},{"id":"o2","texto":"Juntar el aceite usado en una botella"},{"id":"o3","texto":"Llevar los medicamentos vencidos a una farmacia que los reciba"},{"id":"o4","texto":"Tirar la pintura sobrante por la pileta del patio"},{"id":"o5","texto":"Barrer la basura de la vereda hacia la rejilla"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Todo lo que no va por el desagüe tiene otro destino: tacho, botella de aceite o punto de recolección."}}]},{"slug":"agua-1.s5","orden":5,"tipo":"leccion","titulo_es":"Agua segura: salud y derecho","bajada_es":"Por qué el agua potable es una de las mayores conquistas de la salud pública, y un derecho de todos.","minutos":12,"pasos":[{"slug":"agua-1.s5.p1","orden":1,"grupo":"agua-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El agua y las enfermedades","cuerpo":["El agua contaminada con microorganismos puede transmitir enfermedades como diarreas, cólera o hepatitis A. Durante siglos fueron de las principales causas de muerte en las ciudades, sobre todo de niños.","Las plantas potabilizadoras y las cloacas cambiaron eso. Junto con las vacunas, son de las mayores mejoras de salud de la historia. Por eso, cuando se habla de agua, se habla también de salud."]},"solucion":{}},{"slug":"agua-1.s5.p2","orden":2,"grupo":"agua-1.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las cloacas son tan importantes para la salud de un barrio?","opciones":[{"id":"o1","texto":"Porque alejan las aguas negras de la gente y del agua potable"},{"id":"o2","texto":"Porque hacen que el agua de la canilla sea más fría"},{"id":"o3","texto":"Porque evitan que se inunden las calles cuando llueve"},{"id":"o4","texto":"Porque aumentan la presión del agua potable en las casas"}]},"solucion":{"clave":["o1"],"explicacion":"Separar el agua usada del agua para tomar es la base de la salud urbana. Sin cloacas, esa separación depende de pozos que pueden filtrarse.","por_opcion":{"o3":"Las cloacas no tienen relación con la lluvia; esa es la red pluvial."}}},{"slug":"agua-1.s5.p3","orden":3,"grupo":"agua-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién tiene agua segura","cuerpo":["Según la Organización Mundial de la Salud, en 2022 unas 2.200 millones de personas en el mundo todavía no tenían agua potable gestionada de forma segura: agua disponible en casa, cuando se necesita y libre de contaminación.","En Argentina la gran mayoría de la población urbana tiene agua de red, pero todavía hay barrios, zonas rurales y comunidades que no. Y en algunas regiones las napas tienen naturalmente arsénico en niveles que requieren tratamiento."],"destacado":{"valor":"2.200 millones","texto":"de personas en el mundo no tenían agua segura en casa en 2022, según la OMS."}},"solucion":{}},{"slug":"agua-1.s5.p4","orden":4,"grupo":"agua-1.s5.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace falta para que el agua de una casa se considere segura? Marcá todas.","opciones":[{"id":"o1","texto":"Que esté disponible en la casa o muy cerca"},{"id":"o2","texto":"Que esté disponible cuando se necesita"},{"id":"o3","texto":"Que esté libre de contaminación"},{"id":"o4","texto":"Que sea embotellada"},{"id":"o5","texto":"Que tenga gusto a cloro"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Disponible, cuando hace falta y sin contaminación: esas tres condiciones definen el agua gestionada de forma segura."}},{"slug":"agua-1.s5.p5","orden":5,"grupo":"agua-1.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un derecho humano","cuerpo":["En 2010, la Asamblea General de Naciones Unidas reconoció el acceso al agua potable y al saneamiento como un derecho humano. Quiere decir que los Estados tienen la obligación de trabajar para que toda la población tenga agua suficiente, segura y a un precio accesible.","Que sea un derecho no quiere decir que el agua sea infinita ni gratis de producir: quiere decir que nadie debería quedarse sin la cantidad básica para vivir con dignidad."]},"solucion":{}},{"slug":"agua-1.s5.p6","orden":6,"grupo":"agua-1.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Que el agua sea un derecho humano quiere decir que se puede usar sin ningún límite.","razones":[{"id":"r1","texto":"Porque el derecho es a lo suficiente y seguro, no a un uso sin límite"},{"id":"r2","texto":"Porque los derechos humanos no incluyen al agua"},{"id":"r3","texto":"Porque el agua potable no cuesta nada producirla"}]},"solucion":{"valor":false,"explicacion":"El derecho garantiza el acceso a una cantidad suficiente y segura para vivir con dignidad. No elimina la necesidad de cuidarla: justamente porque es de todos, el uso de cada uno afecta a los demás.","clave":["r1"]}},{"slug":"agua-1.s5.p7","orden":7,"grupo":"agua-1.s5.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con una respuesta posible.","izquierda":[{"id":"a1","texto":"Un barrio sin red cloacal"},{"id":"a2","texto":"Una napa con arsénico"},{"id":"a3","texto":"Un tanque domiciliario sucio"},{"id":"a4","texto":"Un caño roto en la vereda"}],"derecha":[{"id":"b1","texto":"Obras de conexión a la cloaca"},{"id":"b2","texto":"Plantas de tratamiento que lo remueven"},{"id":"b3","texto":"Limpieza periódica del tanque"},{"id":"b4","texto":"Reclamo a la empresa de agua"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada problema tiene responsables distintos: la persona, la familia, la empresa o el Estado. Saber quién puede resolverlo es la mitad de la solución."}},{"slug":"agua-1.s5.p8","orden":8,"grupo":"agua-1.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una red de cloacas mejora la salud de un barrio.","items":[{"id":"i1","texto":"Se conecta el barrio a la red cloacal"},{"id":"i2","texto":"Las aguas negras dejan de ir a pozos ciegos"},{"id":"i3","texto":"Deja de contaminarse la napa de la que se toma agua"},{"id":"i4","texto":"Bajan las diarreas y otras enfermedades"},{"id":"i5","texto":"Mejora la salud, sobre todo de niñas y niños"},{"id":"i6","texto":"Las cloacas agregan cloro al agua de la canilla"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Separar el agua usada del agua para tomar es una de las obras de salud con más impacto."}},{"slug":"agua-1.s5.p9","orden":9,"grupo":"agua-1.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El agua embotellada no es la solución","cuerpo":["En lugares donde el agua de red es segura, el agua embotellada no es más sana, cuesta cientos de veces más por litro y genera toneladas de envases plásticos. Además necesita energía para envasarse y transportarse.","Donde el agua de red no es segura, la solución de fondo es mejorar el servicio, no que cada familia compre bidones para siempre."]},"solucion":{}},{"slug":"agua-1.s5.p10","orden":10,"grupo":"agua-1.s5.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una ciudad donde el agua de red es segura, ¿qué opción es mejor para el ambiente y el bolsillo?","opciones":[{"id":"o1","texto":"Tomar agua de la canilla, en jarra o con un filtro"},{"id":"o2","texto":"Comprar botellitas de agua mineral todos los días"},{"id":"o3","texto":"Comprar bidones grandes aunque el agua de red sea segura"},{"id":"o4","texto":"Tomar solo gaseosas para no tomar agua de red"}]},"solucion":{"clave":["o1"],"explicacion":"El agua de red segura es mucho más barata y no genera residuos plásticos. Un filtro o una jarra resuelven el gusto a cloro.","por_opcion":{"o3":"Los bidones retornables son mejores que las botellitas, pero si el agua de red es segura, la canilla sigue ganando."}}},{"slug":"agua-1.s5.p11","orden":11,"grupo":"agua-1.s5.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones por cuántos residuos plásticos generan en un año, de más a menos.","items":[{"id":"i1","texto":"Una botellita descartable de agua por día"},{"id":"i2","texto":"Un bidón descartable de 5 litros por semana"},{"id":"i3","texto":"Un bidón retornable de 20 litros que se reutiliza"},{"id":"i4","texto":"Agua de la canilla en una botella reutilizable"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuantos más envases de un solo uso, más plástico. El retornable y la canilla están al final porque no generan residuos cada vez.","valores":{"i1":"365 botellas por año","i2":"52 bidones por año","i3":"casi nada: vuelve a la planta","i4":"ninguno"}}},{"slug":"agua-1.s5.p12","orden":12,"grupo":"agua-1.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este mensaje y marcá las afirmaciones falsas.","segmentos":[{"id":"s1","texto":"El agua potable redujo muchísimo las enfermedades en las ciudades."},{"id":"s2","texto":"El agua embotellada siempre es más sana que la de red."},{"id":"s3","texto":"El acceso al agua y al saneamiento es un derecho humano reconocido por la ONU."},{"id":"s4","texto":"Como es un derecho, cuidarla no hace falta."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Salud, derecho y cuidado van juntos: el agua es de todos porque la necesitamos todos.","por_opcion":{"s2":"Donde el agua de red es segura, no hay evidencia de que la embotellada sea más sana.","s4":"Es un derecho de todos justamente porque es un recurso compartido que hay que cuidar."}}},{"slug":"agua-1.s5.p13","orden":13,"grupo":"agua-1.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El agua gestionada de forma segura está {{0}} en casa, cuando se {{1}} y libre de {{2}}.","banco":[{"id":"w1","texto":"disponible"},{"id":"w2","texto":"necesita"},{"id":"w3","texto":"contaminación"},{"id":"w4","texto":"embotellada"},{"id":"w5","texto":"caliente"},{"id":"w6","texto":"gratis"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres condiciones juntas. Si falta una, el agua no es segura aunque salga de una canilla."}},{"slug":"agua-1.s5.p14","orden":14,"grupo":"agua-1.s5.p14","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En un lugar donde el agua de red es segura, tomar agua de la canilla es más barato y genera menos residuos que comprar agua embotellada.","razones":[{"id":"r1","texto":"Porque cuesta mucho menos por litro y no deja envases"},{"id":"r2","texto":"Porque el agua embotellada no tiene costo de transporte"},{"id":"r3","texto":"Porque los envases plásticos desaparecen solos"}]},"solucion":{"valor":true,"explicacion":"El agua de red cuesta una fracción mínima por litro y no genera envases. Donde es segura, es la opción más barata y con menos residuos.","clave":["r1"]}}]},{"slug":"agua-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el agua que usamos","bajada_es":"De dónde viene, cuánta usamos y a dónde va, mezclado.","minutos":8,"pasos":[{"slug":"agua-1.s6.p1","orden":1,"grupo":"agua-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El agua que usamos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"agua-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el agua del club","bajada_es":"Revisá el uso del agua de un club de barrio. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"agua-1.s7.p1","orden":1,"grupo":"agua-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["El club del barrio tiene un vestuario con 6 duchas, sanitarios, una cantina y una cancha de fútbol que se riega en verano. Toma agua de red y está conectado a la cloaca. La comisión directiva está preocupada porque la factura de agua subió mucho y porque en la última lluvia salió agua sucia por la rejilla del estacionamiento.","Te piden ayuda para entender qué pasa y qué conviene hacer primero. Usá todo lo de la unidad."]},"solucion":{}},{"slug":"agua-1.s7.p2","orden":2,"grupo":"agua-1.s7.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un sábado, 60 jugadores se duchan 8 minutos cada uno, con duchas de 12 litros por minuto. ¿Cuántos litros se usan en duchas ese día?","unidad":"litros","decimales":0,"contexto":"Club de barrio: 6 duchas de 12 litros por minuto, sanitarios, cantina y cancha regada en verano. Agua de red y cloaca."},"solucion":{"valor":5760,"tolerancia":115.2,"explicacion":"8 minutos × 12 litros = 96 litros por persona. × 60 jugadores = 5.760 litros en un solo día de partidos."}},{"slug":"agua-1.s7.p3","orden":3,"grupo":"agua-1.s7.p3","tipo":"opcion","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si cambian las flores de ducha por unas de 8 litros por minuto, ¿cuántos litros ahorran ese sábado (60 duchas de 8 minutos)?","opciones":[{"id":"o1","texto":"1.920 litros"},{"id":"o2","texto":"480 litros"},{"id":"o3","texto":"5.760 litros"},{"id":"o4","texto":"3.840 litros"}],"contexto":"Club de barrio: 60 duchas de 8 minutos en un sábado. Duchas actuales: 12 litros por minuto."},"solucion":{"clave":["o1"],"explicacion":"Ahorro por minuto: 12 − 8 = 4 litros. × 8 minutos × 60 personas = 1.920 litros. 3.840 sería el total con las duchas nuevas.","por_opcion":{"o3":"Ese es el total con las duchas viejas: el ahorro es la diferencia entre 12 y 8 litros por minuto."}}},{"slug":"agua-1.s7.p4","orden":4,"grupo":"agua-1.s7.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"La rejilla del estacionamiento largó agua sucia en la lluvia. Armá la explicación más probable.","items":[{"id":"i1","texto":"En el estacionamiento hay manchas de aceite y basura"},{"id":"i2","texto":"La lluvia las arrastra hasta la rejilla"},{"id":"i3","texto":"La rejilla es parte de la red pluvial"},{"id":"i4","texto":"El agua sucia sale sin tratar al arroyo"},{"id":"i5","texto":"La planta potabilizadora devolvió el agua sucia"},{"id":"i6","texto":"La cloaca del vestuario se vació en la cancha"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La rejilla es pluvial: lo que se junta en el piso termina en el arroyo. La solución es limpiar el piso en seco y no dejar aceite ni basura ahí."}},{"slug":"agua-1.s7.p5","orden":5,"grupo":"agua-1.s7.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"La comisión propone medidas. ¿Cuáles atacan el uso de agua y cuáles la contaminación de la rejilla?","grupos":[{"id":"g1","nombre":"Bajan el uso de agua"},{"id":"g2","nombre":"Evitan contaminar la rejilla"}],"items":[{"id":"i1","texto":"Duchas de bajo caudal"},{"id":"i2","texto":"Barrer el estacionamiento en seco"},{"id":"i3","texto":"Regar la cancha de noche y no al mediodía"},{"id":"i4","texto":"Poner cestos en el estacionamiento"},{"id":"i5","texto":"Arreglar la canilla del vestuario que gotea"},{"id":"i6","texto":"Juntar el aceite de la cantina en bidones"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Son dos problemas distintos con soluciones distintas: uno es de cantidad, el otro de calidad del agua que llega al arroyo."}},{"slug":"agua-1.s7.p6","orden":6,"grupo":"agua-1.s7.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Regar la cancha al mediodía de verano es igual de eficiente que regarla de noche.","razones":[{"id":"r1","texto":"Porque con calor y sol se evapora más agua antes de infiltrarse"},{"id":"r2","texto":"Porque de noche el pasto no absorbe agua"},{"id":"r3","texto":"Porque el agua de riego es salada"}]},"solucion":{"valor":false,"explicacion":"Al mediodía, con sol y calor, una parte grande del agua se evapora antes de llegar a las raíces. De noche o temprano se pierde mucho menos.","clave":["r1"]}},{"slug":"agua-1.s7.p7","orden":7,"grupo":"agua-1.s7.p7","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La canilla del vestuario gotea 2 gotas por segundo. Si una gota son unos 0,05 ml, ¿cuántos litros pierde por día? (Redondeá a un decimal.)","unidad":"litros por día","decimales":1},"solucion":{"valor":8.6,"tolerancia":0.3,"explicacion":"2 gota(s) × 0,05 ml = 0,1 ml por segundo. × 86.400 segundos en un día = 8.640 ml, o sea unos 8,6 litros por día."}},{"slug":"agua-1.s7.p7.v2","orden":7,"grupo":"agua-1.s7.p7","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La canilla del vestuario gotea 1 gota por segundo. Si una gota son unos 0,05 ml, ¿cuántos litros pierde por día? (Redondeá a un decimal.)","unidad":"litros por día","decimales":1},"solucion":{"valor":4.3,"tolerancia":0.3,"explicacion":"1 gota(s) × 0,05 ml = 0,05 ml por segundo. × 86.400 segundos en un día = 4.320 ml, o sea unos 4,3 litros por día."}},{"slug":"agua-1.s7.p7.v3","orden":7,"grupo":"agua-1.s7.p7","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La canilla del vestuario gotea 3 gotas por segundo. Si una gota son unos 0,05 ml, ¿cuántos litros pierde por día? (Redondeá a un decimal.)","unidad":"litros por día","decimales":1},"solucion":{"valor":13,"tolerancia":0.3,"explicacion":"3 gota(s) × 0,05 ml = 0,15 ml por segundo. × 86.400 segundos en un día = 12.960 ml, o sea unos 13 litros por día."}},{"slug":"agua-1.s7.p8","orden":8,"grupo":"agua-1.s7.p8","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La cantina tira el aceite de las frituras por la pileta \"con mucha agua caliente\". ¿Qué le dirías?","opciones":[{"id":"o1","texto":"Que lo junte en bidones cuando se enfría y lo lleve a un punto de recolección"},{"id":"o2","texto":"Que está bien si usa agua bien caliente"},{"id":"o3","texto":"Que lo tire en la rejilla del estacionamiento, que es más ancha"},{"id":"o4","texto":"Que lo mezcle con detergente antes de tirarlo"}]},"solucion":{"clave":["o1"],"explicacion":"El agua caliente solo lo lleva más lejos antes de que se enfríe y tape. El aceite se junta y se recicla.","por_opcion":{"o3":"Eso lo mandaría directo al arroyo sin tratar."}}},{"slug":"agua-1.s7.p9","orden":9,"grupo":"agua-1.s7.p9","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas por cuánta agua ahorran en un año de uso típico del club, de más a menos.","items":[{"id":"i1","texto":"Duchas de bajo caudal en el vestuario"},{"id":"i2","texto":"Regar la cancha de noche en lugar del mediodía"},{"id":"i3","texto":"Arreglar la canilla que gotea"},{"id":"i4","texto":"Poner un cartel de \"cerrá la canilla\""}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Con cientos de duchas por semana, la ducha gana por orden de magnitud. La canilla que gotea igual conviene arreglarla: es barato y es agua perdida.","valores":{"i1":"cientos de miles de litros","i2":"decenas de miles de litros","i3":"unos miles de litros","i4":"poco, y depende de que se lea"}}},{"slug":"agua-1.s7.p10","orden":10,"grupo":"agua-1.s7.p10","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La comisión escribe un informe para los socios. Marcá los errores.","segmentos":[{"id":"s1","texto":"El mayor uso de agua del club son las duchas del vestuario."},{"id":"s2","texto":"El agua sucia de la rejilla pasó por la planta de tratamiento, así que no hay problema."},{"id":"s3","texto":"Vamos a cambiar las flores de ducha y barrer el estacionamiento en seco."},{"id":"s4","texto":"El aceite de la cantina lo seguiremos tirando por la pileta con agua caliente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen informe separa los dos problemas y propone soluciones que atacan la causa de cada uno.","por_opcion":{"s2":"La rejilla es pluvial: el agua sale sin tratar al arroyo.","s4":"El aceite se junta y se recicla; por la pileta tapa caños y contamina."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"agua-2","rama":"agua","orden":2,"nivel":1,"titulo_es":"Cuidar el agua en casa","bajada_es":"Pérdidas, ducha, cocina, lavado y riego: cómo gastar mucho menos agua sin vivir peor, y cómo comprobarlo en el medidor.","objetivos_es":["Detectar pérdidas de agua en casa usando el medidor y pruebas simples","Calcular cuánto ahorra cada cambio en el baño, la cocina y el lavado","Regar de forma eficiente según el horario, el método y las plantas","Leer el consumo en la factura y compararlo mes a mes","Relacionar el agua caliente con el gasto de energía"],"repasa":["agua-1","tronco-2"],"requiere_tronco":1,"fuentes":["aysa","un-water","epa","iea-eficiencia","plantas-nativas"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"agua-2.s1","orden":1,"tipo":"leccion","titulo_es":"Las pérdidas que no se ven","bajada_es":"Una canilla que gotea o un inodoro que pierde pueden gastar más que toda una familia. Cómo encontrarlos.","minutos":12,"pasos":[{"slug":"agua-2.s1.p1","orden":1,"grupo":"agua-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Gota a gota","cuerpo":["Una canilla que gotea parece una pérdida insignificante, pero trabaja las 24 horas. Una gota es alrededor de 0,05 mililitros: una gota por segundo son 4,3 litros por día y más de 1.500 litros por año.","Un inodoro que pierde es peor todavía, porque muchas veces el agua corre por dentro del artefacto sin hacer ruido. Según el tamaño de la falla, puede perder desde decenas hasta cientos de litros por día."],"destacado":{"valor":"1 gota/s","texto":"son unos 4 litros por día y más de 1.500 litros por año, de una sola canilla."}},"solucion":{}},{"slug":"agua-2.s1.p2","orden":2,"grupo":"agua-2.s1.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Cuánto pierde una canilla","planteo":"Una canilla deja caer 3 gotas por segundo. Cada gota son 0,05 ml. ¿Cuánto pierde por día?","pasos":["Por segundo: 3 × 0,05 ml = 0,15 ml.","Por día hay 86.400 segundos: 0,15 × 86.400 = 12.960 ml.","Pasado a litros: 12.960 ÷ 1.000 ≈ 13 litros por día."],"resultado":"Unos 13 litros por día, casi 4.700 litros por año, de una sola canilla. Cambiar un cuerito cuesta muy poco."},"solucion":{}},{"slug":"agua-2.s1.p3","orden":3,"grupo":"agua-2.s1.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una canilla deja caer 2 gotas por segundo (0,05 ml cada una). ¿Cuántos litros pierde por día? Redondeá a un decimal.","unidad":"litros por día","decimales":1},"solucion":{"valor":8.6,"tolerancia":0.2,"explicacion":"2 × 0,05 ml = 0,1 ml por segundo; × 86.400 segundos = 8.640 ml, o sea 8,6 litros por día."}},{"slug":"agua-2.s1.p3.v2","orden":3,"grupo":"agua-2.s1.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una canilla deja caer 1 gota por segundo (0,05 ml cada una). ¿Cuántos litros pierde por día? Redondeá a un decimal.","unidad":"litros por día","decimales":1},"solucion":{"valor":4.3,"tolerancia":0.2,"explicacion":"1 × 0,05 ml = 0,05 ml por segundo; × 86.400 segundos = 4.320 ml, o sea 4,3 litros por día."}},{"slug":"agua-2.s1.p3.v3","orden":3,"grupo":"agua-2.s1.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una canilla deja caer 4 gotas por segundo (0,05 ml cada una). ¿Cuántos litros pierde por día? Redondeá a un decimal.","unidad":"litros por día","decimales":1},"solucion":{"valor":17.3,"tolerancia":0.2,"explicacion":"4 × 0,05 ml = 0,2 ml por segundo; × 86.400 segundos = 17.280 ml, o sea 17,3 litros por día."}},{"slug":"agua-2.s1.p3.v4","orden":3,"grupo":"agua-2.s1.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una canilla deja caer 5 gotas por segundo (0,05 ml cada una). ¿Cuántos litros pierde por día? Redondeá a un decimal.","unidad":"litros por día","decimales":1},"solucion":{"valor":21.6,"tolerancia":0.2,"explicacion":"5 × 0,05 ml = 0,25 ml por segundo; × 86.400 segundos = 21.600 ml, o sea 21,6 litros por día."}},{"slug":"agua-2.s1.p4","orden":4,"grupo":"agua-2.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El medidor delata todo","cuerpo":["Si tu casa tiene medidor de agua, podés usarlo para cazar pérdidas. Cerrá todas las canillas, asegurate de que nadie use agua ni esté funcionando el lavarropas, anotá el número del medidor y volvé a mirar una o dos horas después sin usar agua.","Si el número cambió, hay una pérdida en algún lugar de la instalación. Muchos medidores tienen además una ruedita o estrella que gira con cualquier consumo: si gira con todo cerrado, algo pierde."],"lista":["1. Cerrar todo lo que usa agua","2. Anotar el número del medidor","3. Esperar una o dos horas sin usar agua","4. Si el número subió, hay una pérdida"]},"solucion":{}},{"slug":"agua-2.s1.p5","orden":5,"grupo":"agua-2.s1.p5","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená la prueba del medidor para encontrar una pérdida.","items":[{"id":"i1","texto":"Cerrar todas las canillas y apagar lo que usa agua"},{"id":"i2","texto":"Anotar el número que marca el medidor"},{"id":"i3","texto":"Esperar una o dos horas sin usar agua"},{"id":"i4","texto":"Volver a leer el medidor y comparar"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Si el número se movió sin que nadie usara agua, el agua se está yendo por algún lado. El paso siguiente es buscar dónde."}},{"slug":"agua-2.s1.p6","orden":6,"grupo":"agua-2.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La prueba del colorante","cuerpo":["Para saber si el inodoro pierde, se ponen unas gotas de colorante (puede ser de repostería) en la mochila, y se espera media hora sin usarlo. Si aparece color en el inodoro, el agua está pasando por dentro aunque no se escuche.","Las causas más comunes son una goma de la descarga gastada o un flotante mal regulado. Son repuestos baratos, y arreglarlo suele pagarse solo en pocos meses de factura."]},"solucion":{}},{"slug":"agua-2.s1.p7","orden":7,"grupo":"agua-2.s1.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Pusiste colorante en la mochila del inodoro y a la media hora el agua del inodoro está teñida. ¿Qué significa?","opciones":[{"id":"o1","texto":"Que la mochila pierde agua hacia el inodoro"},{"id":"o2","texto":"Que el colorante es de mala calidad"},{"id":"o3","texto":"Que el inodoro está funcionando bien"},{"id":"o4","texto":"Que la cloaca del barrio está tapada"}]},"solucion":{"clave":["o1"],"explicacion":"El agua de la mochila solo debería bajar al descargar. Si baja sola, pierde: en general, por una goma gastada o el flotante.","por_opcion":{"o3":"Si todo estuviera bien, el color se quedaría en la mochila hasta la próxima descarga."}}},{"slug":"agua-2.s1.p8","orden":8,"grupo":"agua-2.s1.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Antes de dormir, con todo cerrado, el medidor marcaba 12.345 m³. A la mañana, sin haber usado agua, marca 12.346 m³. ¿Cuántos litros se perdieron en la noche?","unidad":"litros","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"La diferencia es 1 m³, y cada metro cúbico son 1.000 litros: 1.000 litros perdidos en una noche. Hay una pérdida importante que buscar."}},{"slug":"agua-2.s1.p8.v2","orden":8,"grupo":"agua-2.s1.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Antes de dormir, con todo cerrado, el medidor marcaba 5.820 m³. A la mañana, sin haber usado agua, marca 5.821 m³. ¿Cuántos litros se perdieron en la noche?","unidad":"litros","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"La diferencia es 1 m³, y cada metro cúbico son 1.000 litros: 1.000 litros perdidos en una noche. Hay una pérdida importante que buscar."}},{"slug":"agua-2.s1.p8.v3","orden":8,"grupo":"agua-2.s1.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Antes de dormir, con todo cerrado, el medidor marcaba 40.210 m³. A la mañana, sin haber usado agua, marca 40.212 m³. ¿Cuántos litros se perdieron en la noche?","unidad":"litros","decimales":0},"solucion":{"valor":2000,"tolerancia":40,"explicacion":"La diferencia es 2 m³, y cada metro cúbico son 1.000 litros: 2.000 litros perdidos en una noche. Hay una pérdida importante que buscar."}},{"slug":"agua-2.s1.p9","orden":9,"grupo":"agua-2.s1.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué señal indica una pérdida y cuál no?","grupos":[{"id":"g1","nombre":"Señal de pérdida"},{"id":"g2","nombre":"No indica pérdida"}],"items":[{"id":"i1","texto":"El medidor avanza con todo cerrado"},{"id":"i2","texto":"El agua sale fría a la mañana"},{"id":"i3","texto":"Una mancha de humedad que crece en la pared"},{"id":"i4","texto":"La factura sube en verano por el riego"},{"id":"i5","texto":"Se escucha correr agua en el inodoro sin usarlo"},{"id":"i6","texto":"La ducha tarda en calentarse"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Una factura más alta en verano puede ser uso real (riego, más duchas). Las pérdidas se reconocen porque hay consumo sin uso."}},{"slug":"agua-2.s1.p10","orden":10,"grupo":"agua-2.s1.p10","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si no se escucha ningún ruido, el inodoro no puede estar perdiendo agua.","razones":[{"id":"r1","texto":"Porque el agua puede pasar como un hilo silencioso por dentro"},{"id":"r2","texto":"Porque los inodoros nunca pierden"},{"id":"r3","texto":"Porque solo pierden los inodoros nuevos"}]},"solucion":{"valor":false,"explicacion":"Muchas pérdidas del inodoro son silenciosas: el agua pasa por dentro como un hilo. Por eso existe la prueba del colorante.","clave":["r1"]}},{"slug":"agua-2.s1.p11","orden":11,"grupo":"agua-2.s1.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas pérdidas por cuánta agua pueden desperdiciar en un día, de más a menos.","items":[{"id":"i1","texto":"Un inodoro con la descarga trabada abierta"},{"id":"i2","texto":"Un inodoro con una pérdida silenciosa chica"},{"id":"i3","texto":"Una canilla que gotea 2 gotas por segundo"},{"id":"i4","texto":"Una canilla que gotea una gota cada 5 segundos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El inodoro manda: puede perder muchísimo sin que se note. Las canillas suman, y todas conviene arreglarlas.","valores":{"i1":"cientos de litros o más","i2":"decenas de litros","i3":"≈ 9 litros","i4":"menos de 1 litro"}}},{"slug":"agua-2.s1.p12","orden":12,"grupo":"agua-2.s1.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un vecino explica cómo revisa su casa. Marcá los errores.","segmentos":[{"id":"s1","texto":"Cierro todas las canillas y anoto el medidor antes de dormir."},{"id":"s2","texto":"A la noche dejo andando el lavarropas, total no importa para la prueba."},{"id":"s3","texto":"A la mañana comparo el número con lo que anoté."},{"id":"s4","texto":"Si el número subió 1 m³, perdí apenas 1 litro, no vale la pena buscar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La prueba solo sirve si no hay ningún uso de agua. Y la unidad del medidor, el metro cúbico, son mil litros.","por_opcion":{"s2":"El lavarropas usa agua: con él andando, el medidor avanza aunque no haya pérdida.","s4":"Un metro cúbico son 1.000 litros, no uno: es una pérdida grande."}}},{"slug":"agua-2.s1.p13","orden":13,"grupo":"agua-2.s1.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para saber si el inodoro pierde se pone {{0}} en la mochila; si aparece en el inodoro sin usarlo, la {{1}} de descarga o el {{2}} no cierran bien.","banco":[{"id":"w1","texto":"colorante"},{"id":"w2","texto":"goma"},{"id":"w3","texto":"flotante"},{"id":"w4","texto":"cloro"},{"id":"w5","texto":"caño"},{"id":"w6","texto":"medidor"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La prueba del colorante y las dos piezas culpables más comunes. Los repuestos son baratos y el ahorro es enorme."}},{"slug":"agua-2.s1.p14","orden":14,"grupo":"agua-2.s1.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada síntoma con su causa más probable.","izquierda":[{"id":"a1","texto":"Agua teñida en el inodoro tras la prueba del colorante"},{"id":"a2","texto":"La canilla gotea con la manija cerrada"},{"id":"a3","texto":"El medidor avanza con todo cerrado"},{"id":"a4","texto":"Mancha de humedad que crece en la pared"}],"derecha":[{"id":"b1","texto":"Goma de descarga gastada"},{"id":"b2","texto":"Cuerito o cartucho gastado"},{"id":"b3","texto":"Pérdida en algún punto de la instalación"},{"id":"b4","texto":"Caño roto dentro de la pared"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada síntoma apunta a un lugar distinto: saber leerlos ahorra tiempo al buscar la pérdida."}}]},{"slug":"agua-2.s2","orden":2,"tipo":"leccion","titulo_es":"El baño: ducha e inodoro","bajada_es":"Donde más agua usa una casa, y donde más fácil es ahorrar sin perder comodidad.","minutos":12,"pasos":[{"slug":"agua-2.s2.p1","orden":1,"grupo":"agua-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ducha, primera candidata","cuerpo":["Como viste, una ducha común entrega unos 10 litros por minuto. Acortarla dos o tres minutos ya ahorra decenas de litros por persona por día. Otra opción, sin cambiar el tiempo, es instalar una flor de ducha de bajo caudal, que mezcla aire con el agua y entrega 6 u 8 litros por minuto con buena sensación de presión.","Cerrar la ducha mientras te enjabonás o te ponés champú también suma: son uno o dos minutos por ducha en los que el agua corre sin que la uses."]},"solucion":{}},{"slug":"agua-2.s2.p2","orden":2,"grupo":"agua-2.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cambiás una flor de ducha de 12 litros por minuto por una de 7. Si tu ducha dura 8 minutos, ¿cuántos litros ahorrás por ducha?","unidad":"litros","decimales":0},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"Se ahorran 5 litros por cada minuto, durante 8 minutos: 5 × 8 = 40 litros por ducha, sin acortarla."}},{"slug":"agua-2.s2.p2.v2","orden":2,"grupo":"agua-2.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cambiás una flor de ducha de 10 litros por minuto por una de 6. Si tu ducha dura 10 minutos, ¿cuántos litros ahorrás por ducha?","unidad":"litros","decimales":0},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"Se ahorran 4 litros por cada minuto, durante 10 minutos: 4 × 10 = 40 litros por ducha, sin acortarla."}},{"slug":"agua-2.s2.p2.v3","orden":2,"grupo":"agua-2.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cambiás una flor de ducha de 15 litros por minuto por una de 9. Si tu ducha dura 7 minutos, ¿cuántos litros ahorrás por ducha?","unidad":"litros","decimales":0},"solucion":{"valor":42,"tolerancia":0.84,"explicacion":"Se ahorran 6 litros por cada minuto, durante 7 minutos: 6 × 7 = 42 litros por ducha, sin acortarla."}},{"slug":"agua-2.s2.p2.v4","orden":2,"grupo":"agua-2.s2.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cambiás una flor de ducha de 10 litros por minuto por una de 8. Si tu ducha dura 12 minutos, ¿cuántos litros ahorrás por ducha?","unidad":"litros","decimales":0},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"Se ahorran 2 litros por cada minuto, durante 12 minutos: 2 × 12 = 24 litros por ducha, sin acortarla."}},{"slug":"agua-2.s2.p3","orden":3,"grupo":"agua-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El inodoro, el que más descargas hace","cuerpo":["Un inodoro viejo puede usar 10 a 15 litros por descarga. Los de doble descarga tienen un botón corto (unos 3 litros) y uno largo (unos 6): usar el corto cuando alcanza reduce mucho el consumo.","Si tu inodoro es viejo y no querés cambiarlo, una botella llena de agua (o arena) dentro de la mochila ocupa lugar y hace que cada descarga use un litro o dos menos. Hay que ubicarla para que no trabe el mecanismo."]},"solucion":{}},{"slug":"agua-2.s2.p4","orden":4,"grupo":"agua-2.s2.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Doble descarga en una familia","planteo":"Una familia de 4 hace 5 descargas por persona por día. Con el inodoro viejo, cada descarga usa 12 litros. Con uno de doble descarga, 4 de cada 5 descargas son cortas (3 L) y 1 es larga (6 L).","pasos":["Viejo: 4 personas × 5 descargas × 12 L = 240 litros por día.","Nuevo, por persona: 4 cortas × 3 L + 1 larga × 6 L = 18 litros; para 4 personas, 72 litros.","Ahorro: 240 − 72 = 168 litros por día."],"resultado":"La familia ahorra unos 168 litros por día: más de 60.000 litros por año, solo con el inodoro."},"solucion":{}},{"slug":"agua-2.s2.p5","orden":5,"grupo":"agua-2.s2.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa de 3 personas hace 5 descargas por persona por día. Con un inodoro de 12 litros usa 180 litros; con doble descarga (4 cortas de 3 L y 1 larga de 6 L por persona), ¿cuántos litros por día usaría?","unidad":"litros por día","decimales":0},"solucion":{"valor":54,"tolerancia":1.08,"explicacion":"Por persona: 4 × 3 + 1 × 6 = 18 litros. Para 3 personas: 18 × 3 = 54 litros por día, contra 180 del inodoro viejo."}},{"slug":"agua-2.s2.p5.v2","orden":5,"grupo":"agua-2.s2.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa de 5 personas hace 5 descargas por persona por día. Con un inodoro de 12 litros usa 300 litros; con doble descarga (4 cortas de 3 L y 1 larga de 6 L por persona), ¿cuántos litros por día usaría?","unidad":"litros por día","decimales":0},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"Por persona: 4 × 3 + 1 × 6 = 18 litros. Para 5 personas: 18 × 5 = 90 litros por día, contra 300 del inodoro viejo."}},{"slug":"agua-2.s2.p5.v3","orden":5,"grupo":"agua-2.s2.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una casa de 2 personas hace 5 descargas por persona por día. Con un inodoro de 12 litros usa 120 litros; con doble descarga (4 cortas de 3 L y 1 larga de 6 L por persona), ¿cuántos litros por día usaría?","unidad":"litros por día","decimales":0},"solucion":{"valor":36,"tolerancia":0.72,"explicacion":"Por persona: 4 × 3 + 1 × 6 = 18 litros. Para 2 personas: 18 × 2 = 36 litros por día, contra 120 del inodoro viejo."}},{"slug":"agua-2.s2.p6","orden":6,"grupo":"agua-2.s2.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué cambios en el baño bajan el consumo sin molestar a nadie? Marcá todos.","opciones":[{"id":"o1","texto":"Una flor de ducha de bajo caudal"},{"id":"o2","texto":"Usar la descarga corta del inodoro cuando alcanza"},{"id":"o3","texto":"Cerrar la ducha mientras te enjabonás"},{"id":"o4","texto":"Un aireador en la canilla del lavatorio"},{"id":"o5","texto":"Tirar la cadena después de cada uso para \"limpiar los caños\""}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Descargar de más no limpia nada: solo gasta. Los otros cuatro cambios ahorran sin cambiar la comodidad."}},{"slug":"agua-2.s2.p7","orden":7,"grupo":"agua-2.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una flor de ducha de bajo caudal siempre deja una ducha incómoda y sin presión.","razones":[{"id":"r1","texto":"Porque mezclan aire y agua para mantener la sensación de presión"},{"id":"r2","texto":"Porque todas cortan el agua caliente"},{"id":"r3","texto":"Porque reducen el caudal a cero"}]},"solucion":{"valor":false,"explicacion":"Las flores eficientes mezclan aire con el agua o concentran el chorro, y dan buena sensación de presión con 6 a 8 litros por minuto. Hay modelos malos, pero no es una regla.","clave":["r1"]}},{"slug":"agua-2.s2.p8","orden":8,"grupo":"agua-2.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El agua caliente también es energía","cuerpo":["Cada litro de agua caliente de la ducha se calentó con gas o electricidad. Por eso una ducha más corta ahorra dos cosas a la vez: agua y energía. En muchas casas, el calefón o el termotanque son uno de los mayores consumos de energía.","Mientras esperás que salga caliente, el agua fría que corre se puede juntar en un balde y usar para regar o para el inodoro."]},"solucion":{}},{"slug":"agua-2.s2.p9","orden":9,"grupo":"agua-2.s2.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué acortar la ducha ahorra más que solo agua?","opciones":[{"id":"o1","texto":"Porque también ahorra la energía que calentó el agua"},{"id":"o2","texto":"Porque el agua fría gasta más energía que la caliente"},{"id":"o3","texto":"Porque la ducha gasta electricidad en la luz del baño"},{"id":"o4","texto":"Porque el jabón se gasta menos rápido"}]},"solucion":{"clave":["o1"],"explicacion":"Calentar agua requiere mucha energía. Por eso la ducha es a la vez uno de los grandes usos de agua y de energía de una casa.","por_opcion":{"o3":"La luz gasta poco: lo que pesa es calentar decenas de litros de agua."}}},{"slug":"agua-2.s2.p10","orden":10,"grupo":"agua-2.s2.p10","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de efectos de acortar la ducha de 15 a 8 minutos.","items":[{"id":"i1","texto":"La ducha dura 7 minutos menos"},{"id":"i2","texto":"Se usan unos 70 litros menos de agua"},{"id":"i3","texto":"El calefón calienta 70 litros menos"},{"id":"i4","texto":"Baja el consumo de gas o electricidad"},{"id":"i5","texto":"Sube la presión del agua de todo el barrio"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un cambio de hábito, dos ahorros. El señuelo exagera: una ducha no cambia la presión del barrio."}},{"slug":"agua-2.s2.p11","orden":11,"grupo":"agua-2.s2.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una flor de bajo caudal mezcla {{0}} con el agua; la descarga {{1}} del inodoro usa unos 3 litros, y una ducha más corta ahorra agua y {{2}}.","banco":[{"id":"w1","texto":"aire"},{"id":"w2","texto":"corta"},{"id":"w3","texto":"energía"},{"id":"w4","texto":"sal"},{"id":"w5","texto":"larga"},{"id":"w6","texto":"cloro"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres herramientas del baño que suman: tecnología (flor, doble descarga) y hábito (ducha corta)."}},{"slug":"agua-2.s2.p12","orden":12,"grupo":"agua-2.s2.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de una revista y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Una botella llena dentro de la mochila reduce cada descarga."},{"id":"s2","texto":"Conviene poner la botella justo sobre el mecanismo de descarga, así presiona más."},{"id":"s3","texto":"Mientras esperás el agua caliente, juntá la fría en un balde."},{"id":"s4","texto":"Las duchas largas no gastan energía si el calefón es a gas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La botella va donde no moleste, y el gas es energía como la electricidad.","por_opcion":{"s2":"Si traba el mecanismo, el inodoro puede quedar perdiendo: va a un costado.","s4":"El gas también es energía: calentar más agua quema más gas."}}},{"slug":"agua-2.s2.p13","orden":13,"grupo":"agua-2.s2.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 4 personas, cada una cierra la ducha 2 minutos mientras se enjabona (ducha de 10 L/min, una por día). ¿Cuántos litros ahorran en un mes de 30 días?","unidad":"litros","decimales":0},"solucion":{"valor":2400,"tolerancia":48,"explicacion":"Por persona y por día: 2 min × 10 L = 20 litros. × 4 personas × 30 días = 2.400 litros por mes, sin acortar la ducha."}},{"slug":"agua-2.s2.p13.v2","orden":13,"grupo":"agua-2.s2.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 3 personas, cada una cierra la ducha 1,5 minutos mientras se enjabona (ducha de 10 L/min, una por día). ¿Cuántos litros ahorran en un mes de 30 días?","unidad":"litros","decimales":0},"solucion":{"valor":1350,"tolerancia":27,"explicacion":"Por persona y por día: 1,5 min × 10 L = 15 litros. × 3 personas × 30 días = 1.350 litros por mes, sin acortar la ducha."}},{"slug":"agua-2.s2.p13.v3","orden":13,"grupo":"agua-2.s2.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 5 personas, cada una cierra la ducha 2 minutos mientras se enjabona (ducha de 10 L/min, una por día). ¿Cuántos litros ahorran en un mes de 30 días?","unidad":"litros","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"Por persona y por día: 2 min × 10 L = 20 litros. × 5 personas × 30 días = 3.000 litros por mes, sin acortar la ducha."}},{"slug":"agua-2.s2.p14","orden":14,"grupo":"agua-2.s2.p14","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este cambio ahorra solo agua, o agua y energía a la vez?","grupos":[{"id":"g1","nombre":"Agua y energía"},{"id":"g2","nombre":"Solo agua"}],"items":[{"id":"i1","texto":"Acortar la ducha caliente"},{"id":"i2","texto":"Usar la descarga corta del inodoro"},{"id":"i3","texto":"Usar una flor de bajo caudal con agua caliente"},{"id":"i4","texto":"Arreglar la pérdida de la mochila"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Todo lo que reduce agua caliente ahorra dos veces: el agua y la energía para calentarla."}}]},{"slug":"agua-2.s3","orden":3,"tipo":"leccion","titulo_es":"La cocina y el lavado","bajada_es":"Platos, alimentos y ropa: tres lugares donde el hábito pesa más que el aparato.","minutos":11,"pasos":[{"slug":"agua-2.s3.p1","orden":1,"grupo":"agua-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lavar los platos","cuerpo":["Lavar con la canilla abierta todo el tiempo es la forma que más agua usa: con 8 litros por minuto, diez minutos son 80 litros. Llenar la pileta (o un recipiente) con agua y detergente para lavar, y enjuagar con un chorro corto, puede usar menos de la mitad.","Un lavavajillas moderno, usado con la carga completa, suele usar menos agua por lavado que muchas personas lavando a mano con la canilla abierta. Usado medio vacío, pierde esa ventaja."]},"solucion":{}},{"slug":"agua-2.s3.p2","orden":2,"grupo":"agua-2.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Lavar los platos con la canilla abierta 10 minutos (8 litros por minuto) contra llenar la pileta con 30 litros y enjuagar rápido con 10 litros más. ¿Cuántos litros ahorra el método de la pileta?","unidad":"litros","decimales":0},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"Canilla abierta: 10 × 8 = 80 litros. Pileta: 30 + 10 = 40 litros. Ahorro: 80 − 40 = 40 litros por lavado."}},{"slug":"agua-2.s3.p2.v2","orden":2,"grupo":"agua-2.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Lavar los platos con la canilla abierta 15 minutos (8 litros por minuto) contra llenar la pileta con 35 litros y enjuagar rápido con 10 litros más. ¿Cuántos litros ahorra el método de la pileta?","unidad":"litros","decimales":0},"solucion":{"valor":75,"tolerancia":1.5,"explicacion":"Canilla abierta: 15 × 8 = 120 litros. Pileta: 35 + 10 = 45 litros. Ahorro: 120 − 45 = 75 litros por lavado."}},{"slug":"agua-2.s3.p2.v3","orden":2,"grupo":"agua-2.s3.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Lavar los platos con la canilla abierta 8 minutos (8 litros por minuto) contra llenar la pileta con 25 litros y enjuagar rápido con 10 litros más. ¿Cuántos litros ahorra el método de la pileta?","unidad":"litros","decimales":0},"solucion":{"valor":29,"tolerancia":0.58,"explicacion":"Canilla abierta: 8 × 8 = 64 litros. Pileta: 25 + 10 = 35 litros. Ahorro: 64 − 35 = 29 litros por lavado."}},{"slug":"agua-2.s3.p3","orden":3,"grupo":"agua-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Pequeños usos que se repiten","cuerpo":["Descongelar un alimento bajo el chorro de la canilla puede gastar decenas de litros. Si se pasa la noche anterior del freezer a la heladera, se descongela solo y de forma más segura.","Lavar frutas y verduras en un recipiente, en lugar de bajo el chorro, gasta mucho menos, y esa agua sirve después para regar. Lo mismo el agua de hervir fideos o verduras, una vez fría, para las plantas."],"lista":["Descongelar en la heladera, no bajo la canilla","Lavar verduras en un recipiente","Reusar el agua de lavar verduras para regar","Tener una jarra de agua fría en la heladera en vez de dejar correr la canilla"]},"solucion":{}},{"slug":"agua-2.s3.p4","orden":4,"grupo":"agua-2.s3.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hábitos de la cocina ahorran agua? Marcá todos.","opciones":[{"id":"o1","texto":"Pasar la carne del freezer a la heladera la noche anterior"},{"id":"o2","texto":"Lavar las verduras en un recipiente"},{"id":"o3","texto":"Tener agua fría en una jarra en la heladera"},{"id":"o4","texto":"Dejar correr la canilla hasta que el agua salga bien fría para tomar"},{"id":"o5","texto":"Enjuagar cada plato bajo el chorro antes de meterlo al lavavajillas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Prever y usar recipientes: esas son las dos claves de la cocina. Prelavar bajo el chorro anula buena parte del ahorro del lavavajillas."}},{"slug":"agua-2.s3.p5","orden":5,"grupo":"agua-2.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ropa","cuerpo":["El lavarropas usa una cantidad de agua parecida por ciclo esté lleno o no, así que lavar con carga completa reduce el agua por prenda. Muchos lavarropas tienen además programas de carga media o económicos.","Lavar con agua fría ahorra la energía de calentarla, y para la mayoría de la ropa de uso diario limpia igual con los jabones actuales. Y no toda prenda necesita lavarse después de cada uso."]},"solucion":{}},{"slug":"agua-2.s3.p6","orden":6,"grupo":"agua-2.s3.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un lavarropas usa 60 litros por ciclo. ¿Qué conviene más?","opciones":[{"id":"o1","texto":"Esperar a juntar una carga completa"},{"id":"o2","texto":"Lavar un poco todos los días para no acumular"},{"id":"o3","texto":"Lavar cada prenda apenas se usa, en ciclos cortos"},{"id":"o4","texto":"Usar siempre el programa de agua caliente"}]},"solucion":{"clave":["o1"],"explicacion":"Con la misma agua por ciclo, más ropa por lavado es menos agua por prenda. El agua caliente, además, suma gasto de energía.","por_opcion":{"o3":"Cada ciclo usa agua parecida aunque tenga poca ropa: más ciclos, más agua por prenda."}}},{"slug":"agua-2.s3.p7","orden":7,"grupo":"agua-2.s3.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia hace 7 lavados por semana a medio llenar. Si juntando cargas completas los baja a 4, con 60 litros por ciclo, ¿cuántos litros ahorra por semana?","unidad":"litros","decimales":0},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"Son 3 ciclos menos por semana × 60 litros = 180 litros semanales, unos 9.360 litros por año."}},{"slug":"agua-2.s3.p7.v2","orden":7,"grupo":"agua-2.s3.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia hace 5 lavados por semana a medio llenar. Si juntando cargas completas los baja a 3, con 60 litros por ciclo, ¿cuántos litros ahorra por semana?","unidad":"litros","decimales":0},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"Son 2 ciclos menos por semana × 60 litros = 120 litros semanales, unos 6.240 litros por año."}},{"slug":"agua-2.s3.p7.v3","orden":7,"grupo":"agua-2.s3.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia hace 6 lavados por semana a medio llenar. Si juntando cargas completas los baja a 3, con 60 litros por ciclo, ¿cuántos litros ahorra por semana?","unidad":"litros","decimales":0},"solucion":{"valor":180,"tolerancia":3.6,"explicacion":"Son 3 ciclos menos por semana × 60 litros = 180 litros semanales, unos 9.360 litros por año."}},{"slug":"agua-2.s3.p8","orden":8,"grupo":"agua-2.s3.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El lavavajillas siempre gasta más agua que lavar a mano.","razones":[{"id":"r1","texto":"Porque depende del método a mano y de llenar el lavavajillas"},{"id":"r2","texto":"Porque los lavavajillas no usan agua"},{"id":"r3","texto":"Porque lavar a mano nunca gasta agua"}]},"solucion":{"valor":false,"explicacion":"Depende de cómo se lave a mano y de si el lavavajillas va lleno. Un lavavajillas eficiente con carga completa suele usar menos agua que lavar a mano con la canilla abierta.","clave":["r1"]}},{"slug":"agua-2.s3.p9","orden":9,"grupo":"agua-2.s3.p9","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas formas de lavar los platos de una cena familiar por litros usados, de más a menos.","items":[{"id":"i1","texto":"A mano, con la canilla abierta 15 minutos"},{"id":"i2","texto":"A mano, con la pileta llena y enjuague rápido"},{"id":"i3","texto":"Lavavajillas eficiente con carga completa"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Los valores son aproximados y cambian según el aparato, pero el orden se repite: el chorro continuo es lo que más gasta.","valores":{"i1":"≈ 120 litros","i2":"≈ 40 litros","i3":"≈ 12 litros"}}},{"slug":"agua-2.s3.p10","orden":10,"grupo":"agua-2.s3.p10","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Estos hábitos ahorran agua, energía o las dos cosas?","grupos":[{"id":"g1","nombre":"Sobre todo agua"},{"id":"g2","nombre":"Agua y energía"}],"items":[{"id":"i1","texto":"Descongelar en la heladera"},{"id":"i2","texto":"Lavar la ropa con agua fría y carga completa"},{"id":"i3","texto":"Lavar verduras en un recipiente"},{"id":"i4","texto":"Acortar la ducha"},{"id":"i5","texto":"Usar la descarga corta del inodoro"},{"id":"i6","texto":"Llenar el lavavajillas antes de usarlo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Todo lo que involucra agua caliente o un aparato eléctrico ahorra también energía. Es la conexión entre esta rama y la de Energía."}},{"slug":"agua-2.s3.p11","orden":11,"grupo":"agua-2.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta rutina de lavado y marcá lo que desperdicia.","segmentos":[{"id":"s1","texto":"Junto la ropa hasta tener una carga completa."},{"id":"s2","texto":"Lavo todo con el programa de agua a 60 grados por las dudas."},{"id":"s3","texto":"Tiendo al sol en vez de usar el secarropas."},{"id":"s4","texto":"Enjuago cada plato con el chorro antes de meterlo al lavavajillas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los dos desperdicios son hábitos \"por las dudas\" que duplican lo que el aparato ya hace.","por_opcion":{"s2":"Para la ropa de todos los días, el agua fría limpia bien y ahorra la energía de calentarla.","s4":"El prelavado con chorro usa tanta agua que se pierde la ventaja del lavavajillas."}}},{"slug":"agua-2.s3.p12","orden":12,"grupo":"agua-2.s3.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada situación de la cocina con la forma de ahorrar agua.","izquierda":[{"id":"a1","texto":"Hay que descongelar pollo para la cena"},{"id":"a2","texto":"Querés tomar agua fría"},{"id":"a3","texto":"Lavaste la lechuga en un bol"},{"id":"a4","texto":"Hervís fideos"}],"derecha":[{"id":"b1","texto":"Pasarlo a la heladera la noche anterior"},{"id":"b2","texto":"Tener una jarra en la heladera"},{"id":"b3","texto":"Usar esa agua para regar las plantas"},{"id":"b4","texto":"Dejar enfriar el agua y regar con ella"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"En la cocina el ahorro viene de prever y de darle un segundo uso al agua, no de privarse de nada."}},{"slug":"agua-2.s3.p13","orden":13,"grupo":"agua-2.s3.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un lavarropas usa 60 litros por ciclo, esté lleno o a media carga. Si en vez de dos lavados a media carga se hace uno con carga completa, 4 veces por mes, ¿cuántos litros se ahorran por mes?","unidad":"litros","decimales":0,"contexto":"60 litros por ciclo; 4 veces por mes."},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"Cada vez se evita un ciclo de 60 litros; × 4 = 240 litros por mes, además de la energía de ese ciclo."}},{"slug":"agua-2.s3.p13.v2","orden":13,"grupo":"agua-2.s3.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un lavarropas usa 50 litros por ciclo, esté lleno o a media carga. Si en vez de dos lavados a media carga se hace uno con carga completa, 4 veces por mes, ¿cuántos litros se ahorran por mes?","unidad":"litros","decimales":0,"contexto":"50 litros por ciclo; 4 veces por mes."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"Cada vez se evita un ciclo de 50 litros; × 4 = 200 litros por mes, además de la energía de ese ciclo."}},{"slug":"agua-2.s3.p13.v3","orden":13,"grupo":"agua-2.s3.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un lavarropas usa 70 litros por ciclo, esté lleno o a media carga. Si en vez de dos lavados a media carga se hace uno con carga completa, 8 veces por mes, ¿cuántos litros se ahorran por mes?","unidad":"litros","decimales":0,"contexto":"70 litros por ciclo; 8 veces por mes."},"solucion":{"valor":560,"tolerancia":11.200000000000001,"explicacion":"Cada vez se evita un ciclo de 70 litros; × 8 = 560 litros por mes, además de la energía de ese ciclo."}}]},{"slug":"agua-2.s4","orden":4,"tipo":"leccion","titulo_es":"Regar con cabeza","bajada_es":"El jardín y la vereda pueden ser el mayor consumo de una casa en verano. Cuándo, cómo y qué regar.","minutos":13,"pasos":[{"slug":"agua-2.s4.p1","orden":1,"grupo":"agua-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El horario lo cambia todo","cuerpo":["Regar al mediodía de verano es regar al aire: con sol fuerte, calor y viento, una buena parte del agua se evapora antes de llegar a las raíces. Temprano a la mañana o al atardecer, la evaporación es mucho menor y el suelo tiene horas para absorber el agua.","También conviene regar menos veces pero más profundo: mojar bien el suelo cada dos o tres días hace que las raíces crezcan hacia abajo, mientras que un riego superficial diario las deja arriba, donde el suelo se seca rápido."]},"solucion":{}},{"slug":"agua-2.s4.p2","orden":2,"grupo":"agua-2.s4.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el mejor momento para regar un jardín en verano?","opciones":[{"id":"o1","texto":"Temprano a la mañana o al atardecer"},{"id":"o2","texto":"Al mediodía, cuando más calor hace"},{"id":"o3","texto":"A la siesta, para refrescar las plantas"},{"id":"o4","texto":"Da igual el horario, el agua es la misma"}]},"solucion":{"clave":["o1"],"explicacion":"Menos sol y menos calor significa menos evaporación: más agua llega a las raíces con el mismo riego.","por_opcion":{"o3":"A la siesta todavía hace mucho calor: gran parte del agua se evapora."}}},{"slug":"agua-2.s4.p3","orden":3,"grupo":"agua-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo llega el agua","cuerpo":["La manguera abierta moja todo, incluso veredas y caminos, y mucho escurre sin infiltrarse. El riego por goteo lleva el agua gota a gota justo al pie de cada planta, y puede usar una fracción del agua de una manguera para el mismo resultado.","Cubrir el suelo con hojas secas, pasto cortado o chips de madera (mulch) reduce la evaporación, mantiene la humedad y protege la vida del suelo. Un suelo cubierto necesita regarse mucho menos que uno desnudo."],"lista":["Goteo: agua justo en la raíz","Mulch o cobertura: menos evaporación","Riego profundo y espaciado: raíces más profundas","Regadera o balde en macetas: nada se desperdicia en el piso"]},"solucion":{}},{"slug":"agua-2.s4.p4","orden":4,"grupo":"agua-2.s4.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada técnica con lo que logra.","izquierda":[{"id":"a1","texto":"Riego por goteo"},{"id":"a2","texto":"Mulch o cobertura del suelo"},{"id":"a3","texto":"Regar al atardecer"},{"id":"a4","texto":"Riego profundo y espaciado"}],"derecha":[{"id":"b1","texto":"Llevar el agua solo a la raíz"},{"id":"b2","texto":"Reducir la evaporación del suelo"},{"id":"b3","texto":"Que se evapore menos agua"},{"id":"b4","texto":"Que las raíces crezcan hacia abajo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro técnicas que se combinan. Juntas pueden bajar el riego a una fracción de lo que se usa con manguera al mediodía."}},{"slug":"agua-2.s4.p5","orden":5,"grupo":"agua-2.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Plantas que no piden tanto","cuerpo":["Un césped siempre verde necesita mucha agua en verano. Las plantas nativas de tu región, en cambio, están adaptadas al clima local: una vez establecidas, muchas sobreviven con la lluvia o con riegos ocasionales.","Elegir nativas no es solo ahorrar agua: también alimenta a las mariposas, abejas y pájaros de la zona. Lo vas a ver en detalle en la rama de Plantas."]},"solucion":{}},{"slug":"agua-2.s4.p6","orden":6,"grupo":"agua-2.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un jardín de plantas nativas bien establecido suele necesitar menos riego que un césped siempre verde.","razones":[{"id":"r1","texto":"Porque están adaptadas al clima y las lluvias de la región"},{"id":"r2","texto":"Porque las plantas nativas no toman agua"},{"id":"r3","texto":"Porque el césped no necesita agua en verano"}]},"solucion":{"valor":true,"explicacion":"Las nativas están adaptadas a las lluvias y temperaturas de su región. El césped ornamental, en cambio, necesita riegos frecuentes en verano para mantenerse verde.","clave":["r1"]}},{"slug":"agua-2.s4.p7","orden":7,"grupo":"agua-2.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La vereda y el auto","cuerpo":["Baldear la vereda con manguera puede gastar cientos de litros en pocos minutos, y lo que arrastra termina en la rejilla y en el arroyo. Barrer en seco y, si hace falta, pasar un trapo o un balde con poca agua resuelve lo mismo.","Para lavar el auto pasa algo parecido: un balde y una esponja pueden usar una fracción del agua de una manguera abierta todo el lavado."]},"solucion":{}},{"slug":"agua-2.s4.p8","orden":8,"grupo":"agua-2.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Lavar la vereda con manguera durante 15 minutos (15 litros por minuto) contra barrer en seco y usar 3 baldes de 10 litros. ¿Cuántos litros se ahorran?","unidad":"litros","decimales":0},"solucion":{"valor":195,"tolerancia":3.9,"explicacion":"Manguera: 15 × 15 = 225 litros. Baldes: 3 × 10 = 30 litros. Ahorro: 195 litros por limpieza, y menos suciedad yendo a la rejilla."}},{"slug":"agua-2.s4.p8.v2","orden":8,"grupo":"agua-2.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Lavar la vereda con manguera durante 20 minutos (15 litros por minuto) contra barrer en seco y usar 4 baldes de 10 litros. ¿Cuántos litros se ahorran?","unidad":"litros","decimales":0},"solucion":{"valor":260,"tolerancia":5.2,"explicacion":"Manguera: 20 × 15 = 300 litros. Baldes: 4 × 10 = 40 litros. Ahorro: 260 litros por limpieza, y menos suciedad yendo a la rejilla."}},{"slug":"agua-2.s4.p8.v3","orden":8,"grupo":"agua-2.s4.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Lavar la vereda con manguera durante 10 minutos (15 litros por minuto) contra barrer en seco y usar 2 baldes de 10 litros. ¿Cuántos litros se ahorran?","unidad":"litros","decimales":0},"solucion":{"valor":130,"tolerancia":2.6,"explicacion":"Manguera: 10 × 15 = 150 litros. Baldes: 2 × 10 = 20 litros. Ahorro: 130 litros por limpieza, y menos suciedad yendo a la rejilla."}},{"slug":"agua-2.s4.p9","orden":9,"grupo":"agua-2.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Juntar la lluvia","cuerpo":["El agua de lluvia que cae en un techo se puede juntar en un tanque o un barril conectado a la canaleta, y usar después para regar. Es agua gratis y blanda, ideal para las plantas.","La cuenta es simple: cada milímetro de lluvia sobre un metro cuadrado de techo es un litro de agua. Un techo de 50 m² con una lluvia de 20 mm junta hasta 1.000 litros."],"destacado":{"valor":"1 mm × 1 m²","texto":"= 1 litro. Así se calcula cuánta lluvia puede juntar un techo."}},"solucion":{}},{"slug":"agua-2.s4.p10","orden":10,"grupo":"agua-2.s4.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un techo de 40 m² recibe una lluvia de 15 mm. ¿Cuántos litros podría juntar como máximo?","unidad":"litros","decimales":0},"solucion":{"valor":600,"tolerancia":12,"explicacion":"Cada milímetro sobre cada metro cuadrado es un litro: 40 m² × 15 mm = 600 litros. En la práctica se junta algo menos por salpicaduras y pérdidas."}},{"slug":"agua-2.s4.p10.v2","orden":10,"grupo":"agua-2.s4.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un techo de 60 m² recibe una lluvia de 10 mm. ¿Cuántos litros podría juntar como máximo?","unidad":"litros","decimales":0},"solucion":{"valor":600,"tolerancia":12,"explicacion":"Cada milímetro sobre cada metro cuadrado es un litro: 60 m² × 10 mm = 600 litros. En la práctica se junta algo menos por salpicaduras y pérdidas."}},{"slug":"agua-2.s4.p10.v3","orden":10,"grupo":"agua-2.s4.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un techo de 25 m² recibe una lluvia de 30 mm. ¿Cuántos litros podría juntar como máximo?","unidad":"litros","decimales":0},"solucion":{"valor":750,"tolerancia":15,"explicacion":"Cada milímetro sobre cada metro cuadrado es un litro: 25 m² × 30 mm = 750 litros. En la práctica se junta algo menos por salpicaduras y pérdidas."}},{"slug":"agua-2.s4.p10.v4","orden":10,"grupo":"agua-2.s4.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un techo de 80 m² recibe una lluvia de 12 mm. ¿Cuántos litros podría juntar como máximo?","unidad":"litros","decimales":0},"solucion":{"valor":960,"tolerancia":19.2,"explicacion":"Cada milímetro sobre cada metro cuadrado es un litro: 80 m² × 12 mm = 960 litros. En la práctica se junta algo menos por salpicaduras y pérdidas."}},{"slug":"agua-2.s4.p11","orden":11,"grupo":"agua-2.s4.p11","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué prácticas de riego ahorran agua y cuáles la desperdician?","grupos":[{"id":"g1","nombre":"Ahorran"},{"id":"g2","nombre":"Desperdician"}],"items":[{"id":"i1","texto":"Regar con goteo al atardecer"},{"id":"i2","texto":"Manguera al mediodía de verano"},{"id":"i3","texto":"Cubrir el suelo con hojas secas"},{"id":"i4","texto":"Aspersor que moja la vereda"},{"id":"i5","texto":"Regar las macetas con regadera"},{"id":"i6","texto":"Riego superficial todos los días"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las que desperdician tienen algo en común: el agua se evapora o cae donde no hay raíces."}},{"slug":"agua-2.s4.p12","orden":12,"grupo":"agua-2.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé la rutina de riego de un vecino y marcá los errores.","segmentos":[{"id":"s1","texto":"Riego el pasto todos los días al mediodía, un ratito."},{"id":"s2","texto":"En los canteros puse hojas secas del otoño."},{"id":"s3","texto":"El aspersor tira la mitad del agua a la vereda, pero así queda limpia."},{"id":"s4","texto":"Junto el agua de lluvia en un barril para las macetas."}]},"solucion":{"clave":["s1","s3"],"explicacion":"Horario, profundidad y puntería: los tres errores clásicos del riego.","por_opcion":{"s1":"Mediodía y riego superficial diario: la peor combinación de evaporación y raíces cortas.","s3":"El agua en la vereda no riega nada y arrastra suciedad a la rejilla."}}},{"slug":"agua-2.s4.p13","orden":13,"grupo":"agua-2.s4.p13","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué el mulch hace que haga falta regar menos.","items":[{"id":"i1","texto":"Se cubre el suelo con hojas secas"},{"id":"i2","texto":"El sol no pega directo sobre la tierra"},{"id":"i3","texto":"Se evapora menos agua del suelo"},{"id":"i4","texto":"La humedad dura más días"},{"id":"i5","texto":"Hacen falta menos riegos"},{"id":"i6","texto":"Las hojas secas producen agua al descomponerse"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La cobertura no fabrica agua: la protege del sol y del viento. Además, al descomponerse alimenta la vida del suelo."}},{"slug":"agua-2.s4.p14","orden":14,"grupo":"agua-2.s4.p14","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tenés un balcón con macetas. ¿Cuál es la forma de riego que menos agua desperdicia?","opciones":[{"id":"o1","texto":"Regadera o botella, al pie de cada maceta, al atardecer"},{"id":"o2","texto":"Manguera abierta sobre todas las macetas juntas al mediodía"},{"id":"o3","texto":"Un aspersor chico que moje todo el balcón"},{"id":"o4","texto":"Dejar que el agua desborde de los platos para asegurarse"}]},"solucion":{"clave":["o1"],"explicacion":"Poca agua, justo en la raíz y sin sol fuerte: en macetas es fácil hacerlo perfecto.","por_opcion":{"o3":"El aspersor tira agua al piso y a las paredes, donde no hay raíces."}}},{"slug":"agua-2.s4.p15","orden":15,"grupo":"agua-2.s4.p15","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que al regar al mediodía se evapora el 30 % del agua y de noche solo el 10 %. Si se riegan 200 litros, ¿cuántos litros más llegan a las raíces regando de noche?","unidad":"litros","decimales":0,"contexto":"200 litros; 30 % de evaporación al mediodía y 10 % de noche."},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"Al mediodía se pierden 60 litros; de noche, 20. La diferencia es 40 litros que el jardín aprovecha. Valores de ejemplo: el horario cambia cuánto riego hace falta."}},{"slug":"agua-2.s4.p15.v2","orden":15,"grupo":"agua-2.s4.p15","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que al regar al mediodía se evapora el 30 % del agua y de noche solo el 10 %. Si se riegan 500 litros, ¿cuántos litros más llegan a las raíces regando de noche?","unidad":"litros","decimales":0,"contexto":"500 litros; 30 % de evaporación al mediodía y 10 % de noche."},"solucion":{"valor":100,"tolerancia":2,"explicacion":"Al mediodía se pierden 150 litros; de noche, 50. La diferencia es 100 litros que el jardín aprovecha. Valores de ejemplo: el horario cambia cuánto riego hace falta."}},{"slug":"agua-2.s4.p15.v3","orden":15,"grupo":"agua-2.s4.p15","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que al regar al mediodía se evapora el 30 % del agua y de noche solo el 10 %. Si se riegan 300 litros, ¿cuántos litros más llegan a las raíces regando de noche?","unidad":"litros","decimales":0,"contexto":"300 litros; 30 % de evaporación al mediodía y 10 % de noche."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"Al mediodía se pierden 90 litros; de noche, 30. La diferencia es 60 litros que el jardín aprovecha. Valores de ejemplo: el horario cambia cuánto riego hace falta."}}]},{"slug":"agua-2.s5","orden":5,"tipo":"leccion","titulo_es":"Medir y sostener","bajada_es":"Leer la factura, comparar meses y convertir los cambios en costumbre de toda la casa.","minutos":11,"pasos":[{"slug":"agua-2.s5.p1","orden":1,"grupo":"agua-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Leer la factura del agua","cuerpo":["Si tu casa tiene medidor, la factura muestra cuántos metros cúbicos se consumieron en el período (la diferencia entre dos lecturas del medidor). Dividiendo por la cantidad de días y de personas, obtenés litros por persona por día, que se pueden comparar con cualquier otra casa.","Muchas facturas muestran también el consumo de los meses anteriores. Comparar el mismo mes de dos años es mejor que comparar meses seguidos, porque el verano y el invierno cambian mucho el uso."]},"solucion":{}},{"slug":"agua-2.s5.p2","orden":2,"grupo":"agua-2.s5.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"De la factura a litros por persona","planteo":"Una factura bimestral marca 24 m³ en 60 días, para una casa de 4 personas.","pasos":["24 m³ son 24.000 litros.","Por día: 24.000 ÷ 60 = 400 litros.","Por persona: 400 ÷ 4 = 100 litros por persona por día."],"resultado":"Esa casa usa unos 100 litros por persona por día: en el límite superior de lo que Naciones Unidas considera suficiente para necesidades básicas."},"solucion":{}},{"slug":"agua-2.s5.p3","orden":3,"grupo":"agua-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura marca 30 m³ en 60 días para 3 personas. ¿Cuántos litros por persona por día usan? Redondeá a un decimal.","unidad":"litros por persona por día","decimales":1},"solucion":{"valor":166.7,"tolerancia":1,"explicacion":"30 m³ = 30.000 litros. ÷ 60 días = 500 litros por día. ÷ 3 personas ≈ 166,7 litros por persona por día."}},{"slug":"agua-2.s5.p3.v2","orden":3,"grupo":"agua-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura marca 18 m³ en 30 días para 2 personas. ¿Cuántos litros por persona por día usan? Redondeá a un decimal.","unidad":"litros por persona por día","decimales":1},"solucion":{"valor":300,"tolerancia":1,"explicacion":"18 m³ = 18.000 litros. ÷ 30 días = 600 litros por día. ÷ 2 personas ≈ 300 litros por persona por día."}},{"slug":"agua-2.s5.p3.v3","orden":3,"grupo":"agua-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura marca 45 m³ en 60 días para 5 personas. ¿Cuántos litros por persona por día usan? Redondeá a un decimal.","unidad":"litros por persona por día","decimales":1},"solucion":{"valor":150,"tolerancia":1,"explicacion":"45 m³ = 45.000 litros. ÷ 60 días = 750 litros por día. ÷ 5 personas ≈ 150 litros por persona por día."}},{"slug":"agua-2.s5.p3.v4","orden":3,"grupo":"agua-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"La factura marca 24 m³ en 30 días para 4 personas. ¿Cuántos litros por persona por día usan? Redondeá a un decimal.","unidad":"litros por persona por día","decimales":1},"solucion":{"valor":200,"tolerancia":1,"explicacion":"24 m³ = 24.000 litros. ÷ 30 días = 800 litros por día. ÷ 4 personas ≈ 200 litros por persona por día."}},{"slug":"agua-2.s5.p4","orden":4,"grupo":"agua-2.s5.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué comparación dice más sobre si una familia está ahorrando agua?","opciones":[{"id":"o1","texto":"Enero de este año contra enero del año pasado"},{"id":"o2","texto":"Enero contra julio del mismo año"},{"id":"o3","texto":"Este mes contra el mes pasado, siempre"},{"id":"o4","texto":"La factura propia contra la de una empresa del barrio"}]},"solucion":{"clave":["o1"],"explicacion":"Comparar el mismo mes elimina el efecto de la estación. Así, si el consumo bajó, es por los cambios y no por el clima.","por_opcion":{"o3":"Entre meses seguidos puede cambiar la estación, y el uso cambia mucho entre verano e invierno."}}},{"slug":"agua-2.s5.p5","orden":5,"grupo":"agua-2.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Que sea de todos","cuerpo":["Los cambios que hace una sola persona de la casa ayudan, pero los que se vuelven reglas de la casa duran más. Algunas ideas: un reloj o una canción en la ducha, un cartel en el lavadero, anotar la lectura del medidor cada domingo, o un \"desafío del mes\" con una meta de litros.","Ver el número bajar es la recompensa que sostiene el hábito, como viste en el tronco. Sin medir, el esfuerzo es invisible y se abandona."]},"solucion":{}},{"slug":"agua-2.s5.p6","orden":6,"grupo":"agua-2.s5.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ideas ayudan a que el ahorro de agua sea un hábito de toda la casa? Marcá todas.","opciones":[{"id":"o1","texto":"Anotar la lectura del medidor cada semana en la heladera"},{"id":"o2","texto":"Poner una meta del mes y festejar si se cumple"},{"id":"o3","texto":"Acordar juntos qué cambios probar"},{"id":"o4","texto":"Retar a quien se duche mucho delante de todos"},{"id":"o5","texto":"Cambiar todo de golpe sin avisar a nadie"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Medir, acordar y celebrar. Los retos públicos generan resistencia, y los cambios sin acuerdo no se sostienen."}},{"slug":"agua-2.s5.p7","orden":7,"grupo":"agua-2.s5.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El año pasado, en el mismo bimestre, la casa consumió 28 m³. Este año, 22 m³. ¿En qué porcentaje bajó el consumo? Redondeá a entero.","unidad":"%","decimales":0},"solucion":{"valor":21,"tolerancia":1,"explicacion":"Bajó 6 m³ sobre 28: 6 ÷ 28 × 100 ≈ 21 %. Siempre se divide por el valor de partida."}},{"slug":"agua-2.s5.p7.v2","orden":7,"grupo":"agua-2.s5.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El año pasado, en el mismo bimestre, la casa consumió 36 m³. Este año, 27 m³. ¿En qué porcentaje bajó el consumo? Redondeá a entero.","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":1,"explicacion":"Bajó 9 m³ sobre 36: 9 ÷ 36 × 100 ≈ 25 %. Siempre se divide por el valor de partida."}},{"slug":"agua-2.s5.p7.v3","orden":7,"grupo":"agua-2.s5.p7","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El año pasado, en el mismo bimestre, la casa consumió 20 m³. Este año, 17 m³. ¿En qué porcentaje bajó el consumo? Redondeá a entero.","unidad":"%","decimales":0},"solucion":{"valor":15,"tolerancia":1,"explicacion":"Bajó 3 m³ sobre 20: 3 ÷ 20 × 100 ≈ 15 %. Siempre se divide por el valor de partida."}},{"slug":"agua-2.s5.p8","orden":8,"grupo":"agua-2.s5.p8","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Una familia puede hacer un solo cambio este mes. Ordená por litros que ahorra por mes, de más a menos (casa de 4 personas).","items":[{"id":"i1","texto":"Cerrar la canilla al cepillarse (2 min, 8 L/min, dos veces por día)"},{"id":"i2","texto":"Acortar cada ducha 3 minutos (10 L/min)"},{"id":"i3","texto":"Arreglar el inodoro que pierde en silencio 100 litros por día"},{"id":"i4","texto":"Arreglar una canilla que gotea 1 gota por segundo"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Ojo: acá el orden no es el intuitivo. Cepillarse con la canilla abierta, multiplicado por 4 personas, dos veces por día, 30 días, suma 3.840 litros. Hacer la cuenta evita adivinar.","valores":{"i1":"≈ 3.840 litros","i2":"≈ 3.600 litros","i3":"≈ 3.000 litros","i4":"≈ 130 litros"}}},{"slug":"agua-2.s5.p9","orden":9,"grupo":"agua-2.s5.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si la factura de agua es fija y no depende del consumo, ahorrar agua no tiene sentido.","razones":[{"id":"r1","texto":"Porque el agua ahorrada no se potabiliza, bombea ni trata, y queda para otros"},{"id":"r2","texto":"Porque el agua solo importa si se paga por litro"},{"id":"r3","texto":"Porque las facturas fijas incluyen agua ilimitada sin costo para nadie"}]},"solucion":{"valor":false,"explicacion":"Aunque la factura no cambie, el agua que no se usa no hay que potabilizarla, bombearla ni tratarla después, y queda disponible para otros. El ahorro es real aunque no se vea en la factura.","clave":["r1"]}},{"slug":"agua-2.s5.p10","orden":10,"grupo":"agua-2.s5.p10","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá la receta para sostener el ahorro.","texto":"Primero {{0}}, después {{1}} en casa qué cambiar, y cada tanto {{2}} con el mismo mes del año anterior.","banco":[{"id":"w1","texto":"medir"},{"id":"w2","texto":"acordar"},{"id":"w3","texto":"comparar"},{"id":"w4","texto":"adivinar"},{"id":"w5","texto":"imponer"},{"id":"w6","texto":"olvidar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Medir, acordar, comparar: es el ciclo de hábito del tronco aplicado al agua."}},{"slug":"agua-2.s5.p11","orden":11,"grupo":"agua-2.s5.p11","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Una familia escribe su balance del mes. Marcá los errores.","segmentos":[{"id":"s1","texto":"Bajamos de 30 m³ a 24 m³ en el mismo bimestre que el año pasado."},{"id":"s2","texto":"O sea que ahorramos 6 litros en dos meses."},{"id":"s3","texto":"El cambio que más rindió fue arreglar el inodoro que perdía."},{"id":"s4","texto":"Como bajamos un 50 %, ya no hace falta seguir midiendo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Unidades y porcentajes bien hechos, y la medición como costumbre: las dos lecciones del tronco aplicadas a la casa.","por_opcion":{"s2":"Son 6 m³: 6.000 litros.","s4":"De 30 a 24 es un 20 %, no un 50 %. Y medir es lo que sostiene el hábito."}}},{"slug":"agua-2.s5.p12","orden":12,"grupo":"agua-2.s5.p12","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá: una casa de 4 personas que usa 150 litros por persona por día, ¿cuántos metros cúbicos consume en un bimestre de 60 días?","min":5,"max":100,"paso":1,"unidad":"m³","escala":"lineal"},"solucion":{"valor":36,"banda":"lineal","explicacion":"150 × 4 = 600 litros por día; × 60 días = 36.000 litros, que son 36 m³. Es la cuenta inversa a la de la factura."}},{"slug":"agua-2.s5.p13","orden":13,"grupo":"agua-2.s5.p13","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená un plan de ahorro de agua para la casa.","items":[{"id":"i1","texto":"Leer la factura o el medidor para tener el punto de partida"},{"id":"i2","texto":"Buscar y arreglar las pérdidas"},{"id":"i3","texto":"Acordar en familia dos o tres cambios de hábito"},{"id":"i4","texto":"Medir de nuevo al mes siguiente"},{"id":"i5","texto":"Comparar con el mismo mes del año anterior y ajustar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Medir, arreglar, acordar y volver a medir: el ciclo que convierte un propósito en un hábito."}}]},{"slug":"agua-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: cuidar el agua en casa","bajada_es":"Pérdidas, baño, cocina, riego y medición, mezclados.","minutos":8,"pasos":[{"slug":"agua-2.s6.p1","orden":1,"grupo":"agua-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Cuidar el agua en casa». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"agua-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la casa de los Pereyra","bajada_es":"Una casa real, su medidor y sus hábitos. Encontrá dónde se va el agua y armá el plan.","minutos":10,"pasos":[{"slug":"agua-2.s7.p1","orden":1,"grupo":"agua-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["Los Pereyra son 4 y la factura de agua se les duplicó en el último bimestre. Viven en una casa con jardín. Juntaron datos: ducha de 12 litros por minuto y duchas de unos 12 minutos; inodoro viejo de 12 litros por descarga; riegan el pasto con manguera todos los días al mediodía; lavan la vereda con manguera los sábados.","Una noche hicieron la prueba del medidor: a las 23 marcaba 520,300 m³ y a las 7, sin usar agua, 520,580 m³."]},"solucion":{}},{"slug":"agua-2.s7.p2","orden":2,"grupo":"agua-2.s7.p2","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la prueba nocturna, ¿cuántos litros por hora pierde la instalación de los Pereyra? (De 23 a 7 hay 8 horas.)","unidad":"litros por hora","decimales":0,"contexto":"Los Pereyra, 4 personas: ducha de 12 L/min y duchas de 12 minutos; inodoro de 12 L por descarga; riego con manguera al mediodía; vereda con manguera los sábados. Medidor: 520,300 m³ a las 23 y 520,580 m³ a las 7, sin uso."},"solucion":{"valor":35,"tolerancia":0.7000000000000001,"explicacion":"La diferencia es 520,580 − 520,300 = 0,280 m³ = 280 litros en 8 horas. 280 ÷ 8 = 35 litros por hora, unos 840 litros por día: explica buena parte de la factura duplicada."}},{"slug":"agua-2.s7.p3","orden":3,"grupo":"agua-2.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué deberían hacer primero los Pereyra?","opciones":[{"id":"o1","texto":"Buscar y arreglar la pérdida que muestra el medidor"},{"id":"o2","texto":"Cambiar las plantas del jardín por otras más lindas"},{"id":"o3","texto":"Comprar un lavavajillas nuevo para la cocina"},{"id":"o4","texto":"Dejar de lavar la vereda los sábados y nada más"}],"contexto":"La prueba del medidor de los Pereyra muestra una pérdida de 280 litros en 8 horas sin uso."},"solucion":{"clave":["o1"],"explicacion":"Una pérdida de unos 840 litros por día es agua que se va sin ningún beneficio. Es lo más urgente y lo primero que hay que resolver.","por_opcion":{"o3":"Puede ayudar a futuro, pero hoy la pérdida detectada es lo más urgente y lo más barato."}}},{"slug":"agua-2.s7.p4","orden":4,"grupo":"agua-2.s7.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el orden más razonable para encontrar la pérdida.","items":[{"id":"i1","texto":"Hacer la prueba del colorante en el inodoro"},{"id":"i2","texto":"Revisar canillas y la válvula del tanque"},{"id":"i3","texto":"Buscar manchas de humedad en paredes y pisos"},{"id":"i4","texto":"Si no aparece, llamar a un plomero para revisar caños"},{"id":"i5","texto":"Cortar el agua de la casa para siempre"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"De lo más probable y fácil a lo más difícil. El inodoro es el sospechoso número uno en pérdidas silenciosas."}},{"slug":"agua-2.s7.p5","orden":5,"grupo":"agua-2.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si acortan las duchas de 12 a 7 minutos (4 personas, una ducha por día, 12 L/min), ¿cuántos litros ahorran por día?","unidad":"litros por día","decimales":0,"contexto":"Los Pereyra, 4 personas: ducha de 12 L/min, duchas de 12 minutos."},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"5 minutos menos × 12 litros por minuto = 60 litros por persona. × 4 personas = 240 litros por día, más la energía de calentarlos."}},{"slug":"agua-2.s7.p6","orden":6,"grupo":"agua-2.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los cambios del plan de los Pereyra.","grupos":[{"id":"g1","nombre":"Cambio de hábito, gratis"},{"id":"g2","nombre":"Cambio de equipo, con algún costo"}],"items":[{"id":"i1","texto":"Regar al atardecer y no al mediodía"},{"id":"i2","texto":"Flor de ducha de bajo caudal"},{"id":"i3","texto":"Barrer la vereda en seco"},{"id":"i4","texto":"Mochila de doble descarga"},{"id":"i5","texto":"Duchas de 7 minutos"},{"id":"i6","texto":"Riego por goteo en los canteros"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Conviene empezar por los gratis, que ahorran mucho enseguida, y sumar los de equipo, que ahorran para siempre sin depender de acordarse."}},{"slug":"agua-2.s7.p7","orden":7,"grupo":"agua-2.s7.p7","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas del plan por litros ahorrados por día, de más a menos (sin contar la pérdida, que ya arreglaron).","items":[{"id":"i1","texto":"Dejar de regar el pasto al mediodía con manguera (30 min, 15 L/min) y regar dos veces por semana al atardecer"},{"id":"i2","texto":"Duchas de 12 a 7 minutos"},{"id":"i3","texto":"Inodoro de doble descarga"},{"id":"i4","texto":"Barrer la vereda en seco los sábados"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El riego diario al mediodía gana: son 450 litros cada día, y pasando a dos riegos semanales la baja es enorme. Por eso el jardín es el primer lugar para mirar en verano.","valores":{"i1":"≈ 300 litros por día en promedio","i2":"≈ 240 litros por día","i3":"≈ 170 litros por día","i4":"≈ 40 litros por día en promedio"}}},{"slug":"agua-2.s7.p8","orden":8,"grupo":"agua-2.s7.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si arreglan la pérdida, ya no hace falta cambiar ningún hábito porque la factura va a volver a lo normal.","razones":[{"id":"r1","texto":"Porque \"normal\" ya era un consumo alto que se puede bajar"},{"id":"r2","texto":"Porque las pérdidas son la única forma de gastar agua"},{"id":"r3","texto":"Porque los hábitos no afectan la factura"}]},"solucion":{"valor":false,"explicacion":"La factura \"normal\" ya incluía riego al mediodía, duchas largas e inodoro viejo. Arreglar la pérdida es lo primero, pero los hábitos y equipos pueden bajar el consumo mucho más allá de ese normal.","clave":["r1"]}},{"slug":"agua-2.s7.p9","orden":9,"grupo":"agua-2.s7.p9","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El hijo mayor escribe el plan en la heladera. Marcá los errores.","segmentos":[{"id":"s1","texto":"1. Arreglar la pérdida del inodoro esta semana."},{"id":"s2","texto":"2. Regar el pasto todos los días al mediodía pero con la manguera más cerrada."},{"id":"s3","texto":"3. Duchas de 7 minutos con una canción."},{"id":"s4","texto":"4. Medir el agua una vez por año, en diciembre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El plan bien armado ataca la causa (horario del riego) y se apoya en medir seguido.","por_opcion":{"s2":"El problema principal es el horario y la frecuencia: al mediodía se evapora mucho.","s4":"Para sostener el hábito conviene medir seguido: por ejemplo, cada semana."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"agua-3","rama":"agua","orden":3,"nivel":2,"titulo_es":"Del desagüe al río","bajada_es":"Qué lleva el agua que se va por la cloaca, cómo se limpia en una planta, qué pasa cuando llega sucia a un río y qué se puede hacer.","objetivos_es":["Nombrar qué contaminantes trae el agua usada y de dónde salen","Explicar las etapas del tratamiento de efluentes cloacales","Describir cómo el exceso de materia orgánica y nutrientes deja a un río sin oxígeno","Contar el caso de la cuenca Matanza-Riachuelo y el fallo de la Corte Suprema de 2008","Elegir hábitos de casa que reducen lo que llega al agua"],"repasa":["agua-1","tronco-1","tronco-2"],"requiere_tronco":2,"fuentes":["acumar","aysa","unep","unep-plasticos","oms-agua-potable","ley-25675-ambiente"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"agua-3.s1","orden":1,"tipo":"leccion","titulo_es":"Qué lleva el agua usada","bajada_es":"Materia orgánica, nutrientes, microbios, grasas, químicos y microplásticos: el inventario de lo que se va por el desagüe.","minutos":12,"pasos":[{"slug":"agua-3.s1.p1","orden":1,"grupo":"agua-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un inventario invisible","cuerpo":["El agua que sale de una casa parece solo \"agua sucia\", pero lleva cosas muy distintas. Materia orgánica: restos de comida, desechos del cuerpo, jabón. Nutrientes: nitrógeno y fósforo, que vienen de la orina, los alimentos y algunos detergentes. Microorganismos: bacterias y virus, algunos causantes de enfermedades.","También lleva grasas y aceites, sólidos (arena, pelo, restos), químicos (productos de limpieza, restos de medicamentos, cosméticos) y microplásticos, sobre todo fibras que se sueltan de la ropa sintética al lavarla."],"lista":["Materia orgánica","Nutrientes (nitrógeno y fósforo)","Microorganismos","Grasas y aceites","Sólidos","Químicos y fármacos","Microplásticos"]},"solucion":{}},{"slug":"agua-3.s1.p2","orden":2,"grupo":"agua-3.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada contaminante con de dónde sale en una casa.","izquierda":[{"id":"a1","texto":"Materia orgánica"},{"id":"a2","texto":"Fósforo"},{"id":"a3","texto":"Microfibras plásticas"},{"id":"a4","texto":"Grasas"},{"id":"a5","texto":"Restos de fármacos"}],"derecha":[{"id":"b1","texto":"Restos de comida y desechos del cuerpo"},{"id":"b2","texto":"Algunos detergentes y la orina"},{"id":"b3","texto":"Lavar ropa sintética"},{"id":"b4","texto":"La pileta de la cocina"},{"id":"b5","texto":"Medicamentos que el cuerpo elimina o que se tiran"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Cada contaminante tiene una puerta de entrada distinta en la casa. Conocerlas es la base para reducirlos en el origen."}},{"slug":"agua-3.s1.p3","orden":3,"grupo":"agua-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Medir la suciedad: la DBO","cuerpo":["La materia orgánica, cuando llega al agua, alimenta bacterias que la descomponen consumiendo el oxígeno disuelto. Para medir cuánta materia orgánica hay, se usa la demanda biológica de oxígeno (DBO): cuánto oxígeno necesitarían las bacterias para descomponerla, en miligramos por litro.","Como referencia aproximada, el agua cloacal cruda suele tener cientos de miligramos por litro de DBO, mientras que un río limpio tiene apenas unos pocos. Cuanto más alta la DBO, más oxígeno le va a robar esa agua al río."],"destacado":{"valor":"DBO","texto":"cuánto oxígeno consumirían las bacterias para descomponer la materia orgánica del agua."}},"solucion":{}},{"slug":"agua-3.s1.p4","orden":4,"grupo":"agua-3.s1.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un análisis da una DBO muy alta en un arroyo. ¿Qué indica?","opciones":[{"id":"o1","texto":"Que tiene mucha materia orgánica que va a consumir oxígeno"},{"id":"o2","texto":"Que el agua tiene mucho oxígeno disponible para los peces"},{"id":"o3","texto":"Que el agua está más fría de lo normal para la estación"},{"id":"o4","texto":"Que el arroyo tiene muchos peces sanos y activos"}]},"solucion":{"clave":["o1"],"explicacion":"DBO alta = mucha \"comida\" para bacterias = mucho oxígeno que se va a consumir. Es una señal de contaminación orgánica.","por_opcion":{"o3":"La temperatura influye en el oxígeno, pero la DBO mide materia orgánica que se descompone."}}},{"slug":"agua-3.s1.p5","orden":5,"grupo":"agua-3.s1.p5","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué agua tiene más probablemente la DBO más alta?","opciones":[{"id":"o1","texto":"El agua cloacal cruda que sale de un barrio"},{"id":"o2","texto":"El agua de un arroyo de montaña sin poblaciones cerca"},{"id":"o3","texto":"El agua de lluvia recién caída en un balde limpio"},{"id":"o4","texto":"El agua potable que sale de la canilla de tu casa"}]},"solucion":{"clave":["o1"],"explicacion":"El agua cloacal cruda es la que más materia orgánica lleva: por eso, sin tratar, es la que más oxígeno le roba a un río.","por_opcion":{"o3":"La lluvia recién caída casi no tiene materia orgánica."}}},{"slug":"agua-3.s1.p6","orden":6,"grupo":"agua-3.s1.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Estos contaminantes son biológicos, químicos o físicos?","grupos":[{"id":"g1","nombre":"Biológicos"},{"id":"g2","nombre":"Químicos"},{"id":"g3","nombre":"Físicos"}],"items":[{"id":"i1","texto":"Bacterias"},{"id":"i2","texto":"Fósforo"},{"id":"i3","texto":"Arena"},{"id":"i4","texto":"Virus"},{"id":"i5","texto":"Restos de medicamentos"},{"id":"i6","texto":"Microfibras plásticas"},{"id":"i7","texto":"Huevos de parásitos"},{"id":"i8","texto":"Detergentes"},{"id":"i9","texto":"Pelos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g2","i9":"g3"},"explicacion":"Cada tipo se trata de forma distinta en una planta: los físicos se separan, los biológicos se desactivan y muchos químicos son los más difíciles de sacar."}},{"slug":"agua-3.s1.p7","orden":7,"grupo":"agua-3.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo más difícil de sacar","cuerpo":["Las plantas de tratamiento son muy buenas sacando sólidos y materia orgánica, pero algunos contaminantes pasan con más facilidad: restos de medicamentos, ciertos químicos de productos de limpieza y cosmética, y los microplásticos más finos.","Por eso reducirlos en el origen —no tirar medicamentos por el inodoro, elegir productos más simples, lavar menos la ropa sintética— es más efectivo que confiar en que la planta los saque después."]},"solucion":{}},{"slug":"agua-3.s1.p8","orden":8,"grupo":"agua-3.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una planta de tratamiento saca del agua absolutamente todos los contaminantes.","razones":[{"id":"r1","texto":"Porque algunos químicos, fármacos y microplásticos pasan en parte"},{"id":"r2","texto":"Porque las plantas no sacan ningún contaminante"},{"id":"r3","texto":"Porque el agua tratada vuelve directo a la canilla"}]},"solucion":{"valor":false,"explicacion":"Las plantas sacan muy bien sólidos y materia orgánica, y con etapas avanzadas también nutrientes y microbios. Pero algunos químicos, fármacos y microplásticos finos pasan en parte. Reducirlos en el origen es la mejor defensa.","clave":["r1"]}},{"slug":"agua-3.s1.p9","orden":9,"grupo":"agua-3.s1.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las fibras de la ropa","cuerpo":["Cada vez que se lava ropa sintética (poliéster, nailon, acrílico) se sueltan miles de fibras microscópicas. Distintos estudios estimaron que un solo lavado de una carga puede liberar cientos de miles de ellas. Muchas atraviesan las plantas de tratamiento y terminan en ríos y mares.","Lavar con carga completa y a menor temperatura, usar ciclos más cortos, lavar solo cuando hace falta y elegir fibras naturales cuando se puede reduce la cantidad que se suelta."]},"solucion":{}},{"slug":"agua-3.s1.p10","orden":10,"grupo":"agua-3.s1.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hábitos reducen las microfibras que llegan al agua? Marcá todos.","opciones":[{"id":"o1","texto":"Lavar la ropa sintética solo cuando hace falta"},{"id":"o2","texto":"Usar carga completa y agua fría"},{"id":"o3","texto":"Elegir fibras naturales cuando se puede"},{"id":"o4","texto":"Lavar prendas sintéticas en ciclos largos y calientes para que se limpien mejor"},{"id":"o5","texto":"Usar más suavizante para que no se suelten fibras"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La fricción y el calor sueltan más fibras. Menos lavados, cargas completas y agua fría las reducen."}},{"slug":"agua-3.s1.p11","orden":11,"grupo":"agua-3.s1.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación de una clase y marcá los errores.","segmentos":[{"id":"s1","texto":"El agua que sale de las casas lleva materia orgánica y nutrientes."},{"id":"s2","texto":"La DBO mide la temperatura del agua."},{"id":"s3","texto":"La ropa sintética suelta microfibras al lavarse."},{"id":"s4","texto":"Como las plantas lo sacan todo, no importa lo que tiremos al desagüe."}]},"solucion":{"clave":["s2","s4"],"explicacion":"DBO es oxígeno, no temperatura, y ninguna planta es perfecta.","por_opcion":{"s2":"Mide cuánto oxígeno consumirían las bacterias para descomponer la materia orgánica.","s4":"Hay contaminantes que pasan en parte: lo mejor es no tirarlos."}}},{"slug":"agua-3.s1.p12","orden":12,"grupo":"agua-3.s1.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cuanto más {{0}} tiene el agua, más alta es su {{1}} y más {{2}} le quita al río.","banco":[{"id":"w1","texto":"materia orgánica"},{"id":"w2","texto":"DBO"},{"id":"w3","texto":"oxígeno"},{"id":"w4","texto":"arena"},{"id":"w5","texto":"temperatura"},{"id":"w6","texto":"sal"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Es la cadena básica de la contaminación orgánica, y la vas a usar en toda la unidad."}},{"slug":"agua-3.s1.p13","orden":13,"grupo":"agua-3.s1.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas aguas por su DBO típica, de más alta a más baja.","items":[{"id":"i1","texto":"Efluente sin tratar de un frigorífico"},{"id":"i2","texto":"Agua cloacal cruda de un barrio"},{"id":"i3","texto":"Agua cloacal con buen tratamiento secundario"},{"id":"i4","texto":"Arroyo limpio de montaña"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Valores de referencia aproximados. Los efluentes de industrias alimenticias pueden ser mucho más cargados que las cloacas de un barrio.","valores":{"i1":"miles de mg/L","i2":"cientos de mg/L","i3":"decenas o menos","i4":"unos pocos mg/L"}}},{"slug":"agua-3.s1.p14","orden":14,"grupo":"agua-3.s1.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para dimensionar plantas de tratamiento se usa el \"habitante equivalente\": unos 60 gramos de DBO por persona por día. ¿Cuántos kg de DBO por día genera un barrio de 1.000 habitantes?","unidad":"kg de DBO por día","decimales":0,"contexto":"1000 habitantes; 60 g de DBO por persona por día."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"1.000 × 60 g = 60.000 g = 60 kg por día. Esa es la carga que la planta tiene que sacar para que no le quite oxígeno al río."}},{"slug":"agua-3.s1.p14.v2","orden":14,"grupo":"agua-3.s1.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para dimensionar plantas de tratamiento se usa el \"habitante equivalente\": unos 60 gramos de DBO por persona por día. ¿Cuántos kg de DBO por día genera un barrio de 5.000 habitantes?","unidad":"kg de DBO por día","decimales":0,"contexto":"5000 habitantes; 60 g de DBO por persona por día."},"solucion":{"valor":300,"tolerancia":6,"explicacion":"5.000 × 60 g = 300.000 g = 300 kg por día. Esa es la carga que la planta tiene que sacar para que no le quite oxígeno al río."}},{"slug":"agua-3.s1.p14.v3","orden":14,"grupo":"agua-3.s1.p14","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Para dimensionar plantas de tratamiento se usa el \"habitante equivalente\": unos 60 gramos de DBO por persona por día. ¿Cuántos kg de DBO por día genera un barrio de 20.000 habitantes?","unidad":"kg de DBO por día","decimales":0,"contexto":"20000 habitantes; 60 g de DBO por persona por día."},"solucion":{"valor":1200,"tolerancia":24,"explicacion":"20.000 × 60 g = 1.200.000 g = 1.200 kg por día. Esa es la carga que la planta tiene que sacar para que no le quite oxígeno al río."}}]},{"slug":"agua-3.s2","orden":2,"tipo":"leccion","titulo_es":"Cómo se limpia el agua cloacal","bajada_es":"Rejas, piletas, bacterias y desinfección: las etapas de una planta de tratamiento.","minutos":12,"pasos":[{"slug":"agua-3.s2.p1","orden":1,"grupo":"agua-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Primero, lo grande","cuerpo":["Cuando el agua cloacal llega a una planta, primero pasa por el pretratamiento: rejas que retienen lo grande (trapos, toallitas, plásticos), desarenadores donde se asienta la arena, y separadores donde flotan y se quitan grasas.","Después viene el tratamiento primario: grandes piletas donde el agua se queda quieta un tiempo y los sólidos más pesados se van al fondo. Se forma un barro que se retira. Solo con esto se saca una parte de la materia orgánica, pero no la mayoría."]},"solucion":{}},{"slug":"agua-3.s2.p2","orden":2,"grupo":"agua-3.s2.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las primeras etapas de una planta de tratamiento.","items":[{"id":"i1","texto":"Rejas que retienen objetos grandes"},{"id":"i2","texto":"Desarenador donde se asienta la arena"},{"id":"i3","texto":"Separación de grasas"},{"id":"i4","texto":"Piletas de sedimentación primaria"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero se saca lo que rompería o taparía las etapas siguientes: objetos grandes, arena y grasas. Después se deja decantar."}},{"slug":"agua-3.s2.p3","orden":3,"grupo":"agua-3.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El trabajo de las bacterias","cuerpo":["El tratamiento secundario usa bacterias, las mismas que en un río consumirían el oxígeno. La diferencia es que en la planta se les inyecta aire con sopladores, así pueden comerse la materia orgánica sin dejar al agua sin oxígeno. Este sistema se llama, entre otros nombres, barros activados.","Las bacterias forman flóculos que después se separan en otra pileta. Con el tratamiento secundario se elimina la mayor parte de la materia orgánica: la DBO baja muchísimo."],"destacado":{"valor":"Aire + bacterias","texto":"el corazón del tratamiento secundario: descomponer la materia orgánica dentro de la planta y no en el río."}},"solucion":{}},{"slug":"agua-3.s2.p4","orden":4,"grupo":"agua-3.s2.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué en el tratamiento secundario se inyecta aire al agua?","opciones":[{"id":"o1","texto":"Para que las bacterias coman la materia orgánica"},{"id":"o2","texto":"Para enfriar el agua antes de volcarla al río"},{"id":"o3","texto":"Para que el agua huela a limpio al salir de la planta"},{"id":"o4","texto":"Para separar la arena del agua en el desarenador"}]},"solucion":{"clave":["o1"],"explicacion":"Es controlar dentro de la planta el mismo proceso que en un río sería un problema: la descomposición que consume oxígeno.","por_opcion":{"o3":"El olor mejora, pero el objetivo es que las bacterias trabajen con oxígeno."}}},{"slug":"agua-3.s2.p5","orden":5,"grupo":"agua-3.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Terciario y desinfección","cuerpo":["El tratamiento terciario, cuando existe, saca lo que queda: nutrientes como el nitrógeno y el fósforo (los que alimentan las algas en los ríos), partículas finas y, en algunos casos, contaminantes específicos. Al final suele haber una desinfección para reducir los microorganismos.","No todas las plantas tienen todas las etapas. Una planta solo con pretratamiento y primario deja salir mucha más materia orgánica y nutrientes que una con secundario y terciario."]},"solucion":{}},{"slug":"agua-3.s2.p6","orden":6,"grupo":"agua-3.s2.p6","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada etapa con lo principal que saca.","izquierda":[{"id":"a1","texto":"Pretratamiento"},{"id":"a2","texto":"Primario"},{"id":"a3","texto":"Secundario"},{"id":"a4","texto":"Terciario"}],"derecha":[{"id":"b1","texto":"Objetos grandes, arena y grasas"},{"id":"b2","texto":"Sólidos que se decantan"},{"id":"b3","texto":"La mayor parte de la materia orgánica"},{"id":"b4","texto":"Nutrientes y partículas finas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada etapa suma una limpieza distinta. Cuantas más etapas, más limpia vuelve el agua al río."}},{"slug":"agua-3.s2.p7","orden":7,"grupo":"agua-3.s2.p7","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos niveles de tratamiento según qué tan limpia sale el agua, de más a menos.","items":[{"id":"i1","texto":"Pretratamiento + primario + secundario + terciario"},{"id":"i2","texto":"Pretratamiento + primario + secundario"},{"id":"i3","texto":"Pretratamiento + primario"},{"id":"i4","texto":"Solo pretratamiento"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada etapa que falta deja pasar algo más al río. Por eso ampliar el tratamiento es una de las grandes obras de saneamiento.","valores":{"i1":"saca también nutrientes","i2":"saca la mayor parte de la materia orgánica","i3":"saca sólidos, poca materia orgánica","i4":"saca lo grande, casi nada más"}}},{"slug":"agua-3.s2.p8","orden":8,"grupo":"agua-3.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué pasa con el barro","cuerpo":["Todo lo que se saca del agua queda como barro o lodo, y hay que hacer algo con él. Se puede estabilizar (por ejemplo, en digestores donde otras bacterias sin oxígeno lo descomponen y producen biogás, que se usa como energía), deshidratar y disponer en rellenos o, si cumple los controles, usar como enmienda de suelos.","Es otra vez la idea del tronco: nada desaparece. Limpiar el agua es trasladar la suciedad a un barro que también hay que gestionar."]},"solucion":{}},{"slug":"agua-3.s2.p9","orden":9,"grupo":"agua-3.s2.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido del barro en una planta con digestor.","items":[{"id":"i1","texto":"Se separa el barro en las piletas"},{"id":"i2","texto":"Va a un digestor sin oxígeno"},{"id":"i3","texto":"Las bacterias lo descomponen y producen biogás"},{"id":"i4","texto":"El biogás se usa como energía en la planta"},{"id":"i5","texto":"El barro se evapora y desaparece"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El barro no desaparece: se transforma. Y de paso, parte de su energía se recupera como biogás."}},{"slug":"agua-3.s2.p10","orden":10,"grupo":"agua-3.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una planta recibe agua con DBO de 250 mg/L y la devuelve con 25 mg/L. ¿Qué porcentaje de la DBO sacó?","unidad":"%","decimales":1},"solucion":{"valor":90,"tolerancia":1.8,"explicacion":"Sacó 250 − 25 = 225 mg/L de 250: 225 ÷ 250 × 100 = 90 %. Es un valor típico de un buen tratamiento secundario."}},{"slug":"agua-3.s2.p10.v2","orden":10,"grupo":"agua-3.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una planta recibe agua con DBO de 300 mg/L y la devuelve con 20 mg/L. ¿Qué porcentaje de la DBO sacó?","unidad":"%","decimales":1},"solucion":{"valor":93.33333333333333,"tolerancia":1.8666666666666667,"explicacion":"Sacó 300 − 20 = 280 mg/L de 300: 280 ÷ 300 × 100 = 93,333 %. Es un valor típico de un buen tratamiento secundario."}},{"slug":"agua-3.s2.p10.v3","orden":10,"grupo":"agua-3.s2.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una planta recibe agua con DBO de 200 mg/L y la devuelve con 30 mg/L. ¿Qué porcentaje de la DBO sacó?","unidad":"%","decimales":1},"solucion":{"valor":85,"tolerancia":1.7,"explicacion":"Sacó 200 − 30 = 170 mg/L de 200: 170 ÷ 200 × 100 = 85 %. Es un valor típico de un buen tratamiento secundario."}},{"slug":"agua-3.s2.p11","orden":11,"grupo":"agua-3.s2.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una planta solo tiene rejas y desarenador, el agua que devuelve al río está prácticamente limpia.","razones":[{"id":"r1","texto":"Porque el pretratamiento casi no saca materia orgánica ni nutrientes"},{"id":"r2","texto":"Porque la arena es el principal contaminante del agua cloacal"},{"id":"r3","texto":"Porque las rejas filtran las bacterias"}]},"solucion":{"valor":false,"explicacion":"Rejas y desarenador sacan lo grande y la arena, pero casi nada de la materia orgánica, los nutrientes y los microbios. El agua sigue siendo muy contaminante.","clave":["r1"]}},{"slug":"agua-3.s2.p12","orden":12,"grupo":"agua-3.s2.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este folleto de una planta y marcá los errores.","segmentos":[{"id":"s1","texto":"En el pretratamiento retenemos objetos y arena."},{"id":"s2","texto":"En el tratamiento secundario, bacterias con aire descomponen la materia orgánica."},{"id":"s3","texto":"Por eso no necesitamos ocuparnos del barro: desaparece en el proceso."},{"id":"s4","texto":"El tratamiento primario ya saca todos los nutrientes."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Etapas bien ubicadas y la idea de que nada desaparece: el barro es la otra cara del agua limpia.","por_opcion":{"s3":"El barro queda y hay que estabilizarlo y disponerlo.","s4":"Los nutrientes se sacan, cuando se sacan, en el terciario."}}},{"slug":"agua-3.s2.p13","orden":13,"grupo":"agua-3.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En el tratamiento {{0}} se inyecta {{1}} para que las bacterias descompongan la materia orgánica; el terciario saca {{2}}.","banco":[{"id":"w1","texto":"secundario"},{"id":"w2","texto":"aire"},{"id":"w3","texto":"nutrientes"},{"id":"w4","texto":"primario"},{"id":"w5","texto":"cloro"},{"id":"w6","texto":"arena"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Secundario = bacterias con aire; terciario = nutrientes. Son las dos etapas que más cambian lo que llega al río."}},{"slug":"agua-3.s2.p14","orden":14,"grupo":"agua-3.s2.p14","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué nivel de tratamiento ocurre cada paso?","grupos":[{"id":"g1","nombre":"Primario"},{"id":"g2","nombre":"Secundario"},{"id":"g3","nombre":"Terciario"}],"items":[{"id":"i1","texto":"Dejar que los sólidos se asienten en piletas"},{"id":"i2","texto":"Bacterias que descomponen la materia orgánica con aire"},{"id":"i3","texto":"Quitar nitrógeno y fósforo"},{"id":"i4","texto":"Separar las grasas que flotan"},{"id":"i5","texto":"Piletas de barros activados"},{"id":"i6","texto":"Filtrados y desinfecciones finales más exigentes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada nivel saca algo que el anterior deja pasar: por eso importa hasta dónde llega una planta."}}]},{"slug":"agua-3.s3","orden":3,"tipo":"leccion","titulo_es":"Cuando el agua sucia llega al río","bajada_es":"Oxígeno que se acaba, algas que explotan y peces que mueren: qué le pasa a un río que recibe más de lo que puede limpiar.","minutos":11,"pasos":[{"slug":"agua-3.s3.p1","orden":1,"grupo":"agua-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un río se limpia solo… hasta cierto punto","cuerpo":["Los ríos tienen una capacidad natural de autodepuración: sus bacterias descomponen materia orgánica, el agua toma oxígeno del aire en las corrientes y la luz del sol ayuda a eliminar microbios. Un poco de materia orgánica, un río sano la procesa.","El problema es la cantidad. Cuando lo que llega supera lo que el río puede procesar, el oxígeno baja más rápido de lo que se repone. Es la misma idea de ritmo de uso contra reposición que viste en el tronco."]},"solucion":{}},{"slug":"agua-3.s3.p2","orden":2,"grupo":"agua-3.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá lo que pasa cuando un río recibe demasiada materia orgánica.","items":[{"id":"i1","texto":"Llega agua cloacal sin tratar"},{"id":"i2","texto":"Las bacterias se alimentan de la materia orgánica"},{"id":"i3","texto":"Consumen el oxígeno disuelto del agua"},{"id":"i4","texto":"El oxígeno baja más rápido de lo que se repone"},{"id":"i5","texto":"Los peces y otros animales se asfixian"},{"id":"i6","texto":"El agua se calienta hasta hervir"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es la cadena de la DBO: más materia orgánica, más consumo de oxígeno, menos vida."}},{"slug":"agua-3.s3.p3","orden":3,"grupo":"agua-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El oxígeno disuelto","cuerpo":["Los peces respiran el oxígeno disuelto en el agua, que se mide en miligramos por litro. Un agua bien oxigenada puede tener alrededor de 8 a 10 mg/L; por debajo de unos 4 a 5, muchas especies sufren, y por debajo de 2 casi ninguna sobrevive. Esos valores son de referencia y cambian según la especie y la temperatura.","El agua caliente guarda menos oxígeno que la fría. Por eso las mortandades de peces son más comunes en verano, cuando el agua está más caliente y las bacterias trabajan más rápido."],"datos":{"tipo":"barras","titulo":"Oxígeno disuelto aguas abajo de una descarga (ejemplo)","unidad":"mg/L","filas":[{"etiqueta":"Antes de la descarga","valor":8.5},{"etiqueta":"En la descarga","valor":3.1},{"etiqueta":"1 km aguas abajo","valor":1.8},{"etiqueta":"5 km aguas abajo","valor":4.2},{"etiqueta":"15 km aguas abajo","valor":7.4}],"nota":"Datos ilustrativos de un caso típico: el oxígeno cae, toca fondo y se recupera lejos."}},"solucion":{}},{"slug":"agua-3.s3.p4","orden":4,"grupo":"agua-3.s3.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En el gráfico, ¿dónde es más probable que haya una mortandad de peces?","opciones":[{"id":"o1","texto":"Un kilómetro aguas abajo de la descarga"},{"id":"o2","texto":"Antes de la descarga, río arriba"},{"id":"o3","texto":"Quince kilómetros aguas abajo"},{"id":"o4","texto":"Justo en el punto de medición inicial"}]},"solucion":{"clave":["o1"],"explicacion":"El mínimo de oxígeno no está en la descarga misma sino un poco más abajo, donde las bacterias ya están trabajando a pleno.","por_opcion":{"o3":"Ahí el oxígeno ya se recuperó a valores cercanos a los de antes de la descarga."}}},{"slug":"agua-3.s3.p5","orden":5,"grupo":"agua-3.s3.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según el gráfico, ¿cuántos mg/L de oxígeno se perdieron entre \"antes de la descarga\" y el punto más bajo?","unidad":"mg/L","decimales":1},"solucion":{"valor":6.7,"tolerancia":0.134,"explicacion":"El máximo es 8,5 y el mínimo 1,8 (a 1 km): 8,5 − 1,8 = 6,7 mg/L. Casi el 80 % del oxígeno desapareció."}},{"slug":"agua-3.s3.p6","orden":6,"grupo":"agua-3.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando sobran nutrientes","cuerpo":["El nitrógeno y el fósforo son fertilizantes: en un lago o río lento, alimentan una explosión de algas y cianobacterias. Es la eutrofización. El agua se pone verde, turbia, a veces con una capa como pintura en la superficie.","Cuando esas algas mueren, se descomponen y consumen oxígeno: el mismo problema de antes, pero causado por los nutrientes. Además, algunas cianobacterias producen toxinas: en el Río de la Plata y en muchos embalses del país hay floraciones en verano, y en esos casos no conviene bañarse ni que los perros tomen esa agua."],"destacado":{"valor":"Agua verde","texto":"una capa verde o como pintura puede ser una floración de cianobacterias: mejor no bañarse."}},"solucion":{}},{"slug":"agua-3.s3.p7","orden":7,"grupo":"agua-3.s3.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la eutrofización de una laguna.","items":[{"id":"i1","texto":"Llegan fertilizantes y efluentes con fósforo"},{"id":"i2","texto":"Las algas y cianobacterias crecen sin control"},{"id":"i3","texto":"El agua se vuelve verde y turbia"},{"id":"i4","texto":"Las algas mueren y se descomponen"},{"id":"i5","texto":"Baja el oxígeno y mueren peces"},{"id":"i6","texto":"El fósforo le agrega oxígeno al agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los nutrientes no roban oxígeno directamente: lo hacen a través de las algas que alimentan. Es una cadena de dos pasos."}},{"slug":"agua-3.s3.p8","orden":8,"grupo":"agua-3.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Estas situaciones son señales de un río o laguna con problemas, o de uno sano?","grupos":[{"id":"g1","nombre":"Señal de problemas"},{"id":"g2","nombre":"Señal de agua sana"}],"items":[{"id":"i1","texto":"Espuma y olor a podrido"},{"id":"i2","texto":"Muchas larvas de insectos sensibles en las piedras"},{"id":"i3","texto":"Una capa verde en la superficie"},{"id":"i4","texto":"Agua clara con plantas sumergidas"},{"id":"i5","texto":"Peces boqueando en la superficie"},{"id":"i6","texto":"Aves que pescan todo el año"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los seres vivos son buenos indicadores: algunas larvas de insectos solo viven en agua bien oxigenada. Lo verás en la rama de Ciencia."}},{"slug":"agua-3.s3.p9","orden":9,"grupo":"agua-3.s3.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un río tiene mucho caudal, puede recibir cualquier cantidad de efluentes sin problemas.","razones":[{"id":"r1","texto":"Porque su capacidad de autodepuración también tiene un límite"},{"id":"r2","texto":"Porque el caudal convierte los contaminantes en agua limpia"},{"id":"r3","texto":"Porque los ríos grandes no tienen seres vivos"}]},"solucion":{"valor":false,"explicacion":"Un río grande diluye más y se recupera más rápido, pero su capacidad también tiene límite. Además, diluir no es eliminar: los contaminantes persistentes se acumulan en el fondo o en los seres vivos.","clave":["r1"]}},{"slug":"agua-3.s3.p10","orden":10,"grupo":"agua-3.s3.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Hace mucho calor y en la costa de un embalse el agua está verde y con olor. Tu perro quiere tomar. ¿Qué hacés?","opciones":[{"id":"o1","texto":"No lo dejo: puede ser una floración tóxica"},{"id":"o2","texto":"Lo dejo, el agua verde es solo pasto flotando"},{"id":"o3","texto":"Lo dejo tomar un poco, que el calor le hace mal"},{"id":"o4","texto":"Lo baño en esa agua para refrescarlo un rato"}]},"solucion":{"clave":["o1"],"explicacion":"Las floraciones de cianobacterias pueden tener toxinas. Ante agua verde o con capa, lo prudente es no bañarse ni dejar tomar a los animales.","por_opcion":{"o3":"Mejor darle agua que hayas llevado: algunas cianobacterias producen toxinas peligrosas para los animales."}}},{"slug":"agua-3.s3.p11","orden":11,"grupo":"agua-3.s3.p11","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un vecino explica en una radio lo que pasa en la laguna. Marcá los errores.","segmentos":[{"id":"s1","texto":"En verano la laguna se pone verde por exceso de nutrientes."},{"id":"s2","texto":"El fósforo le da oxígeno al agua, así que los peces respiran mejor."},{"id":"s3","texto":"Con calor el agua guarda menos oxígeno."},{"id":"s4","texto":"Por eso no hay que preocuparse: la laguna es grande y se limpia sola siempre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Nutrientes, algas, descomposición, menos oxígeno: y un límite que no se puede estirar para siempre.","por_opcion":{"s2":"El fósforo alimenta algas; al descomponerse, consumen oxígeno.","s4":"La autodepuración tiene un límite, y con nutrientes constantes se supera."}}},{"slug":"agua-3.s3.p12","orden":12,"grupo":"agua-3.s3.p12","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema del agua con su causa principal.","izquierda":[{"id":"a1","texto":"Falta de oxígeno aguas abajo de una descarga"},{"id":"a2","texto":"Agua verde con una capa en la superficie"},{"id":"a3","texto":"Mortandad de peces en verano"},{"id":"a4","texto":"Espuma persistente en un arroyo"}],"derecha":[{"id":"b1","texto":"Materia orgánica con DBO alta"},{"id":"b2","texto":"Exceso de nitrógeno y fósforo"},{"id":"b3","texto":"Menos oxígeno por el calor y la descomposición"},{"id":"b4","texto":"Detergentes y efluentes industriales"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada síntoma tiene una causa más probable. Identificarla orienta qué medir y qué reclamar."}},{"slug":"agua-3.s3.p13","orden":13,"grupo":"agua-3.s3.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué situaciones bajan el oxígeno disuelto de un río? Marcá todas.","opciones":[{"id":"o1","texto":"Mucha materia orgánica de cloacas sin tratar"},{"id":"o2","texto":"Agua más caliente en verano"},{"id":"o3","texto":"Poco caudal durante una sequía"},{"id":"o4","texto":"Exceso de nutrientes que dispara algas"},{"id":"o5","texto":"Una cascada que mezcla el agua con el aire"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"El calor, la poca agua y la carga orgánica se suman: por eso las mortandades de peces suelen ocurrir en verano."}}]},{"slug":"agua-3.s4","orden":4,"tipo":"leccion","titulo_es":"El Riachuelo: una cuenca en recuperación","bajada_es":"Historia de uno de los ríos más contaminados del país, el fallo que obligó a limpiarlo y lo que todavía falta.","minutos":12,"pasos":[{"slug":"agua-3.s4.p1","orden":1,"grupo":"agua-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una cuenca, muchas historias","cuerpo":["La cuenca Matanza-Riachuelo recorre unos 60 kilómetros desde el oeste del conurbano hasta el Río de la Plata, en La Boca. En ella viven millones de personas, repartidas entre la Ciudad de Buenos Aires y más de una docena de municipios de la provincia.","Durante más de un siglo recibió efluentes de industrias (curtiembres, frigoríficos, químicas), aguas cloacales sin tratar y basura. Se convirtió en uno de los ríos más contaminados del país, con barrios enteros viviendo sobre sus orillas en condiciones de riesgo."]},"solucion":{}},{"slug":"agua-3.s4.p2","orden":2,"grupo":"agua-3.s4.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué fuentes contaminaron históricamente el Riachuelo? Marcá todas.","opciones":[{"id":"o1","texto":"Efluentes de industrias como curtiembres y frigoríficos"},{"id":"o2","texto":"Aguas cloacales sin tratar"},{"id":"o3","texto":"Basurales a cielo abierto en las orillas"},{"id":"o4","texto":"El agua de lluvia de las montañas"},{"id":"o5","texto":"Los barcos de pasajeros del Delta"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Industria, cloacas y basura: tres fuentes que se sumaron durante décadas en una cuenca muy poblada."}},{"slug":"agua-3.s4.p3","orden":3,"grupo":"agua-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El fallo Mendoza","cuerpo":["En 2004, un grupo de vecinos y profesionales encabezado por Beatriz Mendoza demandó al Estado y a empresas por los daños causados por la contaminación de la cuenca. En 2008, la Corte Suprema de Justicia dictó un fallo histórico: ordenó recomponer el ambiente de la cuenca, mejorar la calidad de vida de sus habitantes y prevenir daños futuros.","Para cumplirlo, el fallo se apoyó en la Autoridad de Cuenca Matanza Riachuelo (ACUMAR), un organismo creado por ley en 2006 que coordina a la Nación, la Provincia de Buenos Aires y la Ciudad. Es un ejemplo de gestión por cuenca: el agua no respeta los límites de los municipios."],"destacado":{"valor":"2008","texto":"la Corte Suprema ordenó recomponer la cuenca Matanza-Riachuelo en el fallo Mendoza."}},"solucion":{}},{"slug":"agua-3.s4.p4","orden":4,"grupo":"agua-3.s4.p4","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los hechos del caso Riachuelo.","items":[{"id":"i1","texto":"Durante décadas se vuelcan efluentes y basura a la cuenca"},{"id":"i2","texto":"Vecinos demandan al Estado y a empresas"},{"id":"i3","texto":"Se crea por ley la ACUMAR"},{"id":"i4","texto":"La Corte Suprema dicta el fallo Mendoza"},{"id":"i5","texto":"Se ejecutan obras y controles bajo supervisión judicial"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"De la contaminación acumulada a la demanda, y de ahí a una obligación judicial con un organismo que la coordina."}},{"slug":"agua-3.s4.p5","orden":5,"grupo":"agua-3.s4.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la cuenca se gestiona con un organismo que junta a Nación, Provincia y Ciudad?","opciones":[{"id":"o1","texto":"Porque el río cruza varias jurisdicciones"},{"id":"o2","texto":"Porque la Ciudad no tiene ríos propios para cuidar"},{"id":"o3","texto":"Porque así se pueden cobrar más impuestos por el agua"},{"id":"o4","texto":"Porque la Corte Suprema administra los ríos del país"}]},"solucion":{"clave":["o1"],"explicacion":"Lo que un municipio tira río arriba lo recibe otro río abajo. Por eso la unidad de gestión del agua es la cuenca, no el límite político.","por_opcion":{"o3":"El motivo es de gestión: un río compartido necesita decisiones compartidas."}}},{"slug":"agua-3.s4.p6","orden":6,"grupo":"agua-3.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué cambió y qué falta","cuerpo":["Desde el fallo se limpiaron márgenes y se sacaron cascos de barcos hundidos, se relocalizaron familias que vivían sobre el borde del río, se controlaron industrias (muchas tuvieron que tratar sus efluentes o cerraron), se cerraron basurales y se hicieron grandes obras de cloacas.","Aun así, la recuperación es lenta: la calidad del agua mejoró en algunos tramos y sigue siendo mala en otros, y el sedimento del fondo guarda contaminación de décadas. Es un ejemplo de algo que viste en el tronco: los retrasos. Lo que tardó un siglo en ensuciarse no se limpia en pocos años."]},"solucion":{}},{"slug":"agua-3.s4.p7","orden":7,"grupo":"agua-3.s4.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué acciones atacan la causa de la contaminación y cuáles alivian sus efectos?","grupos":[{"id":"g1","nombre":"Atacan la causa"},{"id":"g2","nombre":"Alivian los efectos"}],"items":[{"id":"i1","texto":"Obligar a las industrias a tratar sus efluentes"},{"id":"i2","texto":"Sacar basura flotante del río"},{"id":"i3","texto":"Conectar barrios a la red cloacal"},{"id":"i4","texto":"Relocalizar familias en zonas de riesgo"},{"id":"i5","texto":"Cerrar basurales en las orillas"},{"id":"i6","texto":"Atender la salud de quienes viven cerca"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos columnas hacen falta: una evita que siga entrando contaminación y la otra protege a la gente mientras tanto."}},{"slug":"agua-3.s4.p8","orden":8,"grupo":"agua-3.s4.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si desde mañana nadie tirara nada más al Riachuelo, al día siguiente el río estaría limpio.","razones":[{"id":"r1","texto":"Porque los sedimentos y el ecosistema tardan años en recuperarse"},{"id":"r2","texto":"Porque el río nunca se puede recuperar"},{"id":"r3","texto":"Porque la contaminación no tiene nada que ver con las descargas"}]},"solucion":{"valor":false,"explicacion":"El fondo del río acumula sedimentos contaminados de décadas, y el ecosistema tarda en recuperarse. Cortar las descargas es imprescindible, pero la recuperación lleva años.","clave":["r1"]}},{"slug":"agua-3.s4.p9","orden":9,"grupo":"agua-3.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Justicia ambiental","cuerpo":["La contaminación de la cuenca no afectó a todos por igual: la sufrieron sobre todo los barrios más pobres, que viven más cerca del río y tienen menos acceso a agua segura y cloacas. Cuando los daños ambientales recaen más sobre quienes menos tienen, se habla de injusticia ambiental.","Por eso el fallo no habló solo de agua limpia sino de calidad de vida de los habitantes. Lo vas a ver en profundidad en la rama de Comunidad."]},"solucion":{}},{"slug":"agua-3.s4.p10","orden":10,"grupo":"agua-3.s4.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué el caso Riachuelo es también un caso de justicia ambiental?","opciones":[{"id":"o1","texto":"Porque los más afectados fueron los barrios pobres cercanos al río"},{"id":"o2","texto":"Porque la Justicia intervino en un tema ambiental"},{"id":"o3","texto":"Porque todos los habitantes del país sufrieron igual la contaminación"},{"id":"o4","texto":"Porque el río tiene derechos propios reconocidos por ley"}]},"solucion":{"clave":["o1"],"explicacion":"La justicia ambiental mira quién sufre los daños y quién recibe los beneficios. En la cuenca, el daño se concentró en quienes menos tenían.","por_opcion":{"o3":"La contaminación afectó mucho más a quienes viven cerca del río y con menos servicios."}}},{"slug":"agua-3.s4.p11","orden":11,"grupo":"agua-3.s4.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen escolar sobre el Riachuelo y marcá los errores.","segmentos":[{"id":"s1","texto":"La cuenca atraviesa la Ciudad y varios municipios del conurbano."},{"id":"s2","texto":"En 2008 la Corte Suprema ordenó recomponerla en el fallo Mendoza."},{"id":"s3","texto":"Como el fallo ya salió, el problema está resuelto y el agua es apta para bañarse."},{"id":"s4","texto":"ACUMAR es una empresa privada que vende el agua del río."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Un fallo es el comienzo de una obligación, no el final del problema. Y ACUMAR es un organismo público.","por_opcion":{"s3":"El fallo obligó a actuar, pero la recuperación es lenta y el agua sigue sin ser apta en muchos tramos.","s4":"ACUMAR es un organismo público interjurisdiccional creado por ley."}}},{"slug":"agua-3.s4.p12","orden":12,"grupo":"agua-3.s4.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El agua se gestiona por {{0}} porque lo que se tira río {{1}} lo recibe quien vive río {{2}}.","banco":[{"id":"w1","texto":"cuenca"},{"id":"w2","texto":"arriba"},{"id":"w3","texto":"abajo"},{"id":"w4","texto":"provincia"},{"id":"w5","texto":"adentro"},{"id":"w6","texto":"afuera"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Es la idea que justifica organismos como ACUMAR: el agua no respeta los límites de los mapas políticos."}},{"slug":"agua-3.s4.p13","orden":13,"grupo":"agua-3.s4.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El fallo Mendoza solo ordenó limpiar el agua del río, sin mencionar a las personas que viven en la cuenca.","razones":[{"id":"r1","texto":"Porque también ordenó mejorar la calidad de vida de sus habitantes"},{"id":"r2","texto":"Porque el fallo no mencionó el río"},{"id":"r3","texto":"Porque la Corte Suprema no puede ordenar nada sobre el ambiente"}]},"solucion":{"valor":false,"explicacion":"El fallo ordenó recomponer el ambiente, mejorar la calidad de vida de los habitantes de la cuenca y prevenir daños futuros. Las personas estaban en el centro de la decisión.","clave":["r1"]}},{"slug":"agua-3.s4.p14","orden":14,"grupo":"agua-3.s4.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada actor con su papel en el saneamiento de la cuenca.","izquierda":[{"id":"a1","texto":"Corte Suprema"},{"id":"a2","texto":"ACUMAR"},{"id":"a3","texto":"Industrias de la cuenca"},{"id":"a4","texto":"Vecinos y organizaciones"}],"derecha":[{"id":"b1","texto":"Dictó el fallo y controla que se cumpla"},{"id":"b2","texto":"Coordina el plan entre Nación, Provincia y Ciudad"},{"id":"b3","texto":"Deben tratar sus efluentes antes de volcarlos"},{"id":"b4","texto":"Participan y controlan los avances"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El saneamiento de una cuenca necesita a todos los actores, cada uno con su parte."}}]},{"slug":"agua-3.s5","orden":5,"tipo":"leccion","titulo_es":"Lo que se puede hacer desde casa","bajada_es":"Qué hábitos reducen lo que llega al río, y cómo participar cuando el problema es más grande que una casa.","minutos":11,"pasos":[{"slug":"agua-3.s5.p1","orden":1,"grupo":"agua-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reducir en el origen","cuerpo":["Todo lo que no entra al agua no hay que sacarlo después. En casa, las acciones más efectivas son las que evitan que ciertas cosas lleguen al desagüe: el aceite en botellas, los medicamentos a la farmacia, las toallitas y los algodones al tacho, las pinturas y solventes a puntos de recolección.","También se pueden elegir productos de limpieza con menos fosfatos y usar la cantidad justa: más detergente no limpia más, pero sí agrega más químicos al agua."]},"solucion":{}},{"slug":"agua-3.s5.p2","orden":2,"grupo":"agua-3.s5.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Adónde va cada cosa?","grupos":[{"id":"g1","nombre":"Al tacho de residuos"},{"id":"g2","nombre":"A un punto de recolección"},{"id":"g3","nombre":"Puede ir por el desagüe"}],"items":[{"id":"i1","texto":"Toallitas húmedas"},{"id":"i2","texto":"Aceite usado en botella"},{"id":"i3","texto":"Agua con jabón de lavar platos"},{"id":"i4","texto":"Algodones y cotonetes"},{"id":"i5","texto":"Medicamentos vencidos"},{"id":"i6","texto":"Agua del lavarropas"},{"id":"i7","texto":"Hilo dental"},{"id":"i8","texto":"Restos de pintura"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3","i7":"g1","i8":"g2"},"explicacion":"Tres destinos distintos. El desagüe es solo para el agua usada, no para residuos."}},{"slug":"agua-3.s5.p3","orden":3,"grupo":"agua-3.s5.p3","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Te sobraron dos litros de pintura al agua. ¿Qué conviene hacer?","opciones":[{"id":"o1","texto":"Guardarla, donarla o llevarla a un punto limpio"},{"id":"o2","texto":"Tirarla por la pileta del lavadero con mucha agua"},{"id":"o3","texto":"Tirarla en la rejilla de la calle cuando llueve"},{"id":"o4","texto":"Enterrarla en el jardín en un pozo profundo"}]},"solucion":{"clave":["o1"],"explicacion":"La pintura sirve a otro, se guarda o se lleva a un punto de recolección. Nunca por el desagüe ni la tierra.","por_opcion":{"o3":"La rejilla lleva directo al arroyo, sin ningún tratamiento."}}},{"slug":"agua-3.s5.p4","orden":4,"grupo":"agua-3.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La casa conectada","cuerpo":["Si en tu barrio hay red cloacal pero tu casa todavía usa pozo ciego, conectarse es de las acciones con más impacto: saca las aguas negras del suelo y de la napa. En barrios sin red, el mantenimiento correcto de las cámaras sépticas y la distancia entre pozos son claves.","Otra conexión que importa: que las canaletas del techo vayan al pluvial y no a la cloaca. Si la lluvia entra a la cloaca, en las tormentas la red se satura y puede desbordar."]},"solucion":{}},{"slug":"agua-3.s5.p5","orden":5,"grupo":"agua-3.s5.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Conectar las canaletas del techo a la cloaca ayuda a que la red funcione mejor.","razones":[{"id":"r1","texto":"Porque la lluvia satura la cloaca y la hace desbordar"},{"id":"r2","texto":"Porque la lluvia limpia los caños de la cloaca"},{"id":"r3","texto":"Porque el pluvial y la cloaca son el mismo caño"}]},"solucion":{"valor":false,"explicacion":"La cloaca no está pensada para recibir la lluvia: en una tormenta se satura y puede desbordar aguas negras. Las canaletas van al pluvial.","clave":["r1"]}},{"slug":"agua-3.s5.p6","orden":6,"grupo":"agua-3.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando el problema es más grande que tu casa","cuerpo":["Si ves un caño que vuelca agua de color o con olor a un arroyo, basura acumulada en una orilla o una mortandad de peces, se puede reportar a la autoridad ambiental local o de la cuenca. En la cuenca Matanza-Riachuelo, ACUMAR recibe denuncias; en otras zonas, el municipio o el organismo provincial de ambiente.","Un reporte útil tiene lugar exacto, fecha y hora, qué se ve o se huele, y si es posible una foto. Así la autoridad puede ir a medir y encontrar la fuente."],"lista":["Dónde: lugar exacto o coordenadas","Cuándo: fecha y hora","Qué: color, olor, espuma, peces muertos","Prueba: una foto o un video"]},"solucion":{}},{"slug":"agua-3.s5.p7","orden":7,"grupo":"agua-3.s5.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos hacen útil una denuncia de un vuelco a un arroyo? Marcá todos.","opciones":[{"id":"o1","texto":"El lugar exacto del caño o la mancha"},{"id":"o2","texto":"La fecha y la hora en que lo viste"},{"id":"o3","texto":"Una foto o un video"},{"id":"o4","texto":"Cómo se ve y cómo huele el agua"},{"id":"o5","texto":"Tu opinión sobre el gobierno de turno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Lugar, momento, descripción y prueba: con eso se puede ir a tomar muestras y rastrear la fuente."}},{"slug":"agua-3.s5.p8","orden":8,"grupo":"agua-3.s5.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos si encontrás una mancha extraña en el arroyo del barrio.","items":[{"id":"i1","texto":"No tocar el agua ni dejar que la toquen animales"},{"id":"i2","texto":"Sacar fotos y anotar lugar, fecha y hora"},{"id":"i3","texto":"Hacer la denuncia a la autoridad ambiental"},{"id":"i4","texto":"Contarle a los vecinos y hacer seguimiento del reclamo"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero la seguridad, después la evidencia, la denuncia y el seguimiento. Un reclamo que nadie sigue suele quedar en la nada."}},{"slug":"agua-3.s5.p9","orden":9,"grupo":"agua-3.s5.p9","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas acciones por cuánta contaminación evitan que llegue al agua, de más a menos (para una casa con pozo ciego en un barrio con red cloacal nueva).","items":[{"id":"i1","texto":"Conectar la casa a la red cloacal"},{"id":"i2","texto":"Llevar el aceite usado a un punto de recolección"},{"id":"i3","texto":"Usar la cantidad justa de detergente"},{"id":"i4","texto":"Cerrar la canilla al cepillarse"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Ahorrar agua y reducir la contaminación son objetivos distintos: la última acción es muy buena para el primero, pero poco para el segundo.","valores":{"i1":"saca todas las aguas negras del suelo","i2":"evita un contaminante muy potente","i3":"menos químicos por lavado","i4":"ahorra agua, pero casi no cambia la contaminación"}}},{"slug":"agua-3.s5.p10","orden":10,"grupo":"agua-3.s5.p10","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo mejor es reducir la contaminación en el {{0}}: lo que no entra al agua no hay que {{1}} después en una {{2}}.","banco":[{"id":"w1","texto":"origen"},{"id":"w2","texto":"sacarlo"},{"id":"w3","texto":"planta"},{"id":"w4","texto":"destino"},{"id":"w5","texto":"diluirlo"},{"id":"w6","texto":"pileta"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Es la regla de oro de todo el tema: prevenir es más barato y más efectivo que limpiar."}},{"slug":"agua-3.s5.p11","orden":11,"grupo":"agua-3.s5.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este cartel de un club y marcá los consejos equivocados.","segmentos":[{"id":"s1","texto":"Tirá los algodones y las toallitas al tacho, no al inodoro."},{"id":"s2","texto":"Para limpiar mejor, usá el doble de detergente."},{"id":"s3","texto":"Juntá el aceite de la parrilla en una botella."},{"id":"s4","texto":"Conectá las canaletas del techo a la cloaca para que no se tape."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cantidad justa de productos y cada agua por su red: dos reglas simples que cualquiera puede aplicar.","por_opcion":{"s2":"Más detergente no limpia más: agrega químicos al agua.","s4":"Las canaletas van al pluvial; en la cloaca la saturan en las tormentas."}}},{"slug":"agua-3.s5.p12","orden":12,"grupo":"agua-3.s5.p12","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué conectar una casa a la cloaca protege el agua del barrio.","items":[{"id":"i1","texto":"La casa deja de usar el pozo ciego"},{"id":"i2","texto":"Las aguas negras van por la red a una planta"},{"id":"i3","texto":"Dejan de infiltrarse en el suelo"},{"id":"i4","texto":"La napa del barrio se contamina menos"},{"id":"i5","texto":"El agua de la canilla sale más caliente"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La conexión saca la contaminación del suelo y la lleva a donde se puede tratar. Es de las obras con más impacto en la salud de un barrio."}},{"slug":"agua-3.s5.p13","orden":13,"grupo":"agua-3.s5.p13","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué conviene barrer la vereda en seco en lugar de baldearla hacia la calle?","opciones":[{"id":"o1","texto":"Lo que llega a la calle termina en el arroyo por el pluvial"},{"id":"o2","texto":"Porque el agua de baldear se va directo a la cloaca"},{"id":"o3","texto":"Porque así la vereda queda más brillante"},{"id":"o4","texto":"Porque el pluvial lleva todo a una planta de tratamiento"}]},"solucion":{"clave":["o1"],"explicacion":"Barrer en seco ahorra agua y evita mandar tierra, colillas y aceites al arroyo.","por_opcion":{"o3":"No es estética: es evitar que la suciedad llegue al arroyo sin tratar."}}}]},{"slug":"agua-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: del desagüe al río","bajada_es":"Contaminantes, tratamiento, oxígeno y cuencas, todo junto.","minutos":8,"pasos":[{"slug":"agua-3.s6.p1","orden":1,"grupo":"agua-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Del desagüe al río». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"agua-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el arroyo El Talar","bajada_es":"Datos de un arroyo, una fábrica y un barrio. Leé los números y decidí qué hacer.","minutos":10,"pasos":[{"slug":"agua-3.s7.p1","orden":1,"grupo":"agua-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["El arroyo El Talar cruza un barrio del conurbano. Río arriba hay campos; en el medio, una fábrica de alimentos; y más abajo, un barrio sin cloacas donde las casas usan pozos ciegos. Los vecinos notaron olor, espuma y peces muertos en verano.","Un grupo de la escuela técnica tomó muestras en cuatro puntos y midió oxígeno disuelto y DBO. Con sus datos vas a encontrar qué pasa y qué conviene hacer."],"datos":{"tipo":"tabla","titulo":"Mediciones del arroyo El Talar (enero)","columnas":["Punto","Oxígeno disuelto (mg/L)","DBO (mg/L)"],"filas":[["A · Antes de los campos","8,2","3"],["B · Después de los campos","7,1","6"],["C · Después de la fábrica","2,4","48"],["D · Después del barrio","1,6","60"]],"nota":"Datos del caso, inventados para el ejercicio."}},"solucion":{}},{"slug":"agua-3.s7.p2","orden":2,"grupo":"agua-3.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Entre qué puntos se produce el mayor salto de DBO?","opciones":[{"id":"o1","texto":"Entre B y C, después de la fábrica"},{"id":"o2","texto":"Entre A y B, después de los campos"},{"id":"o3","texto":"Entre C y D, después del barrio"},{"id":"o4","texto":"No hay diferencias importantes entre puntos"}],"contexto":"Arroyo El Talar: A 8,2 mg/L de oxígeno y DBO 3 · B 7,1 y 6 · C 2,4 y 48 · D 1,6 y 60."},"solucion":{"clave":["o1"],"explicacion":"La DBO pasa de 6 a 48: un aumento de 42 mg/L. La fábrica es la principal fuente de materia orgánica del tramo.","por_opcion":{"o3":"El barrio suma 12 mg/L; la fábrica, 42. El salto grande está antes."}}},{"slug":"agua-3.s7.p3","orden":3,"grupo":"agua-3.s7.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En cuántos mg/L baja el oxígeno disuelto entre el punto B y el punto C?","unidad":"mg/L","decimales":1,"contexto":"Arroyo El Talar: B 7,1 mg/L de oxígeno · C 2,4 mg/L."},"solucion":{"valor":4.7,"tolerancia":0.094,"explicacion":"7,1 − 2,4 = 4,7 mg/L. El oxígeno cae a un valor en el que muchas especies ya no pueden vivir."}},{"slug":"agua-3.s7.p4","orden":4,"grupo":"agua-3.s7.p4","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la explicación de los peces muertos en verano.","items":[{"id":"i1","texto":"La fábrica vuelca efluentes con mucha materia orgánica"},{"id":"i2","texto":"Sube la DBO del arroyo"},{"id":"i3","texto":"Las bacterias consumen el oxígeno disuelto"},{"id":"i4","texto":"Con el calor el agua guarda todavía menos oxígeno"},{"id":"i5","texto":"Los peces se asfixian"},{"id":"i6","texto":"Los campos le agregan oxígeno al agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Materia orgánica, consumo de oxígeno y calor: tres factores que se suman en verano. Los campos no agregan oxígeno; si acaso, agregan nutrientes."}},{"slug":"agua-3.s7.p5","orden":5,"grupo":"agua-3.s7.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué medida corresponde a cada fuente?","grupos":[{"id":"g1","nombre":"Para la fábrica"},{"id":"g2","nombre":"Para el barrio"},{"id":"g3","nombre":"Para los campos"}],"items":[{"id":"i1","texto":"Exigir una planta de tratamiento de efluentes"},{"id":"i2","texto":"Obras de red cloacal"},{"id":"i3","texto":"Franjas de vegetación junto al arroyo"},{"id":"i4","texto":"Controles periódicos de lo que vuelca"},{"id":"i5","texto":"Mantenimiento y vaciado de pozos ciegos"},{"id":"i6","texto":"Usar la dosis justa de fertilizante"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada fuente tiene su medida. Un plan serio actúa sobre las tres, empezando por la que más pesa."}},{"slug":"agua-3.s7.p6","orden":6,"grupo":"agua-3.s7.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las fuentes por cuánta DBO le agregan al arroyo, de más a menos.","items":[{"id":"i1","texto":"La fábrica de alimentos"},{"id":"i2","texto":"El barrio sin cloacas"},{"id":"i3","texto":"Los campos"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"Con los datos a la vista, la prioridad es clara. Sin medir, lo más probable era culpar al barrio, que es lo que más se ve.","valores":{"i1":"+42 mg/L","i2":"+12 mg/L","i3":"+3 mg/L"}}},{"slug":"agua-3.s7.p7","orden":7,"grupo":"agua-3.s7.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el barrio también contamina, la fábrica no es responsable del problema.","razones":[{"id":"r1","texto":"Porque cada fuente es responsable de lo que aporta, y la fábrica aporta más"},{"id":"r2","texto":"Porque el barrio es la única fuente"},{"id":"r3","texto":"Porque la DBO no tiene relación con los peces"}]},"solucion":{"valor":false,"explicacion":"Las dos fuentes suman, pero la fábrica agrega casi cuatro veces más DBO que el barrio. Que haya varias fuentes no borra la responsabilidad de cada una.","clave":["r1"]}},{"slug":"agua-3.s7.p8","orden":8,"grupo":"agua-3.s7.p8","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"El grupo de la escuela quiere actuar. ¿Qué pasos son razonables? Marcá todos.","opciones":[{"id":"o1","texto":"Presentar los datos a la autoridad ambiental con fechas y lugares"},{"id":"o2","texto":"Repetir las mediciones en otras estaciones del año"},{"id":"o3","texto":"Invitar a la fábrica y a los vecinos a una reunión con los datos"},{"id":"o4","texto":"Publicar que el agua del barrio es venenosa sin más mediciones"},{"id":"o5","texto":"Tirar cal al arroyo para \"neutralizar\" la contaminación"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Datos, repetición y diálogo con los responsables. Exagerar sin evidencia o improvisar \"soluciones\" químicas puede empeorar todo."}},{"slug":"agua-3.s7.p9","orden":9,"grupo":"agua-3.s7.p9","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La radio local cuenta el caso. Marcá los errores.","segmentos":[{"id":"s1","texto":"Estudiantes midieron oxígeno y DBO en cuatro puntos del arroyo."},{"id":"s2","texto":"El mayor aumento de la contaminación orgánica aparece después de la fábrica."},{"id":"s3","texto":"El oxígeno más bajo está antes de los campos."},{"id":"s4","texto":"Con más caudal el problema desaparece solo, así que no hace falta hacer nada."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Leer bien una tabla y no confiar en la dilución: las dos claves del caso.","por_opcion":{"s3":"Antes de los campos está el valor más alto (8,2 mg/L).","s4":"Diluir no elimina la fuente: el verano siguiente vuelve el problema."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"agua-4","rama":"agua","orden":4,"nivel":2,"titulo_es":"El agua invisible","bajada_es":"Cada alimento, cada remera y cada hoja de papel necesitaron agua para existir. Aprendé a medirla y a leerla sin caer en trampas.","objetivos_es":["Explicar qué es el agua virtual y la huella hídrica de un producto","Distinguir el agua verde, azul y gris, y por qué no pesan igual","Comparar la huella hídrica de alimentos por kilo y entender los límites de esa comparación","Estimar el agua detrás de la ropa y otros objetos, y cómo reducirla","Analizar el comercio de agua virtual entre países"],"repasa":["agua-2","tronco-2"],"requiere_tronco":2,"fuentes":["water-footprint-network","huella-hidrica","owid-impactos-alimentos","fao","un-water"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"agua-4.s1","orden":1,"tipo":"leccion","titulo_es":"El agua que no se ve","bajada_es":"Detrás de un vaso de leche o de una remera hay cientos o miles de litros de agua que nunca viste.","minutos":11,"pasos":[{"slug":"agua-4.s1.p1","orden":1,"grupo":"agua-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agua escondida en las cosas","cuerpo":["Para que un tomate llegue a tu mesa hizo falta agua: la lluvia y el riego que usó la planta para crecer, y el agua de lavarlo y procesarlo. Esa agua no está en el tomate, pero se usó para producirlo. Se llama agua virtual.","Sumando toda el agua usada a lo largo de la producción de algo se obtiene su huella hídrica. Se mide en litros por kilo, por litro o por unidad de producto."],"destacado":{"valor":"Agua virtual","texto":"el agua que se usó para producir algo, aunque no quede dentro del producto."}},"solucion":{}},{"slug":"agua-4.s1.p2","orden":2,"grupo":"agua-4.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es la huella hídrica de una remera de algodón?","opciones":[{"id":"o1","texto":"Toda el agua usada para producirla, del campo a la tienda"},{"id":"o2","texto":"El agua que absorbe la remera cuando se moja"},{"id":"o3","texto":"El agua que usa el lavarropas cada vez que se lava"},{"id":"o4","texto":"La cantidad de agua que contiene la tela seca"}]},"solucion":{"clave":["o1"],"explicacion":"Incluye el agua para cultivar el algodón, teñir y terminar la tela. La mayor parte está en el campo.","por_opcion":{"o3":"Ese es un uso posterior; la huella de producción es toda el agua usada para fabricarla."}}},{"slug":"agua-4.s1.p3","orden":3,"grupo":"agua-4.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto puede ser","cuerpo":["Los números sorprenden. Según promedios mundiales de la Water Footprint Network, producir una remera de algodón requiere unos 2.500 litros de agua; un kilo de carne vacuna, unos 15.000; un kilo de tomates, unos 200.","Son promedios globales: el mismo producto puede tener una huella muy distinta según dónde y cómo se produjo. Pero sirven para entender órdenes de magnitud."],"datos":{"tipo":"barras","titulo":"Huella hídrica por kilo de producto (promedio mundial)","unidad":"litros por kg","filas":[{"etiqueta":"Carne vacuna","valor":15400},{"etiqueta":"Chocolate","valor":17200},{"etiqueta":"Queso","valor":5000},{"etiqueta":"Pollo","valor":4300},{"etiqueta":"Arroz","valor":2500},{"etiqueta":"Pan de trigo","valor":1600},{"etiqueta":"Papa","valor":290},{"etiqueta":"Tomate","valor":210}],"nota":"Promedios mundiales aproximados, Water Footprint Network. Cambian mucho según el lugar y el sistema de producción."}},"solucion":{}},{"slug":"agua-4.s1.p4","orden":4,"grupo":"agua-4.s1.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según el gráfico, ordená por huella hídrica por kilo, de mayor a menor.","items":[{"id":"i1","texto":"Carne vacuna"},{"id":"i2","texto":"Pollo"},{"id":"i3","texto":"Arroz"},{"id":"i4","texto":"Papa"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Entre la carne vacuna y la papa hay más de 50 veces de diferencia por kilo. Es un orden de magnitud y medio.","valores":{"i1":"≈ 15.400 L/kg","i2":"≈ 4.300 L/kg","i3":"≈ 2.500 L/kg","i4":"≈ 290 L/kg"}}},{"slug":"agua-4.s1.p5","orden":5,"grupo":"agua-4.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según el gráfico, ¿cuántas veces más agua por kilo necesita la carne vacuna que el pollo? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.6,"tolerancia":0.1,"explicacion":"15.400 ÷ 4.300 ≈ 3,6. Por kilo, la carne vacuna necesita unas tres veces y media más agua que el pollo."}},{"slug":"agua-4.s1.p6","orden":6,"grupo":"agua-4.s1.p6","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El agua de un almuerzo","planteo":"Un almuerzo tiene 200 g de carne vacuna y 150 g de papas. ¿Cuánta agua virtual tiene? (15.400 L/kg y 290 L/kg)","pasos":["Carne: 0,2 kg × 15.400 L/kg = 3.080 litros.","Papas: 0,15 kg × 290 L/kg = 43,5 litros.","Total: 3.080 + 43,5 ≈ 3.124 litros."],"resultado":"Más de 3.000 litros, casi todos en la carne. Es más que el agua que usa una familia de cuatro en una semana en su casa."},"solucion":{}},{"slug":"agua-4.s1.p7","orden":7,"grupo":"agua-4.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de agua virtual tienen 300 gramos de carne vacuna? (Huella: 15.400 litros por kilo.)","unidad":"litros","decimales":0},"solucion":{"valor":4620,"tolerancia":92.4,"explicacion":"300 g son 0,3 kg. × 15.400 L/kg = 4.620 litros. Primero a kilos, después la multiplicación."}},{"slug":"agua-4.s1.p7.v2","orden":7,"grupo":"agua-4.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de agua virtual tienen 250 gramos de pollo? (Huella: 4.300 litros por kilo.)","unidad":"litros","decimales":0},"solucion":{"valor":1075,"tolerancia":21.5,"explicacion":"250 g son 0,25 kg. × 4.300 L/kg = 1.075 litros. Primero a kilos, después la multiplicación."}},{"slug":"agua-4.s1.p7.v3","orden":7,"grupo":"agua-4.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de agua virtual tienen 150 gramos de queso? (Huella: 5.000 litros por kilo.)","unidad":"litros","decimales":0},"solucion":{"valor":750,"tolerancia":15,"explicacion":"150 g son 0,15 kg. × 5.000 L/kg = 750 litros. Primero a kilos, después la multiplicación."}},{"slug":"agua-4.s1.p7.v4","orden":7,"grupo":"agua-4.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de agua virtual tienen 400 gramos de arroz? (Huella: 2.500 litros por kilo.)","unidad":"litros","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"400 g son 0,4 kg. × 2.500 L/kg = 1.000 litros. Primero a kilos, después la multiplicación."}},{"slug":"agua-4.s1.p8","orden":8,"grupo":"agua-4.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un kilo de carne vacuna contiene unos 15.000 litros de agua adentro.","razones":[{"id":"r1","texto":"Porque es agua usada para producirla, no agua que quede adentro"},{"id":"r2","texto":"Porque la carne pesa 15.000 kilos por litro"},{"id":"r3","texto":"Porque la vaca toma 15.000 litros por día"}]},"solucion":{"valor":false,"explicacion":"El kilo de carne tiene poca agua adentro. Los 15.000 litros son el agua usada para producirlo, sobre todo para cultivar el alimento del animal: es agua virtual.","clave":["r1"]}},{"slug":"agua-4.s1.p9","orden":9,"grupo":"agua-4.s1.p9","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada producto con su huella hídrica aproximada (promedio mundial).","izquierda":[{"id":"a1","texto":"Una remera de algodón"},{"id":"a2","texto":"Un kilo de carne vacuna"},{"id":"a3","texto":"Un kilo de tomates"},{"id":"a4","texto":"Una taza de café"}],"derecha":[{"id":"b1","texto":"≈ 2.500 litros"},{"id":"b2","texto":"≈ 15.400 litros"},{"id":"b3","texto":"≈ 210 litros"},{"id":"b4","texto":"≈ 130 litros"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Números para tener de referencia. No hace falta memorizarlos exactos: alcanza con los órdenes de magnitud."}},{"slug":"agua-4.s1.p10","orden":10,"grupo":"agua-4.s1.p10","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El agua usada para producir algo, aunque no quede dentro del producto, se llama agua {{0}}, y la suma a lo largo de toda la producción es su huella {{1}}.","banco":[{"id":"w1","texto":"virtual"},{"id":"w2","texto":"hídrica"},{"id":"w3","texto":"potable"},{"id":"w4","texto":"de carbono"},{"id":"w5","texto":"salada"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos conceptos distintos pero pegados: el agua virtual es la idea, la huella hídrica es la medida."}},{"slug":"agua-4.s1.p11","orden":11,"grupo":"agua-4.s1.p11","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá la huella hídrica de un kilo de chocolate (promedio mundial).","min":100,"max":50000,"paso":1,"unidad":"litros","escala":"log"},"solucion":{"valor":17200,"banda":"log","explicacion":"Unos 17.000 litros por kilo, en su mayoría para cultivar el cacao. Es de los productos con mayor huella por kilo."}},{"slug":"agua-4.s1.p12","orden":12,"grupo":"agua-4.s1.p12","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Cuáles de estos usos de agua forman parte de la huella hídrica de un pan?","grupos":[{"id":"g1","nombre":"Forma parte"},{"id":"g2","nombre":"No forma parte"}],"items":[{"id":"i1","texto":"La lluvia que usó el trigo para crecer"},{"id":"i2","texto":"El agua que tomás después de comer el pan"},{"id":"i3","texto":"El agua de riego del campo, si lo regaron"},{"id":"i4","texto":"El agua de lavar el plato donde lo comiste"},{"id":"i5","texto":"El agua de la masa y de limpiar la panadería"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"La huella de producción suma todo lo usado hasta que el producto está listo. Lo que pasa después, en tu casa, es otro consumo."}},{"slug":"agua-4.s1.p13","orden":13,"grupo":"agua-4.s1.p13","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena del agua virtual de una remera de algodón.","items":[{"id":"i1","texto":"Se riega el algodón en el campo"},{"id":"i2","texto":"Se cosecha, se limpia y se hila"},{"id":"i3","texto":"Se tiñe la tela con agua y químicos"},{"id":"i4","texto":"Se cose la remera"},{"id":"i5","texto":"La remera llega al negocio con toda esa agua en su huella"},{"id":"i6","texto":"La remera trae adentro toda el agua que se usó"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El agua virtual no está dentro del producto: es la que se usó en cada etapa de su vida."}}]},{"slug":"agua-4.s2","orden":2,"tipo":"leccion","titulo_es":"Verde, azul y gris","bajada_es":"No toda el agua de una huella es igual: la de lluvia, la de riego y la necesaria para diluir contaminación.","minutos":11,"pasos":[{"slug":"agua-4.s2.p1","orden":1,"grupo":"agua-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres colores de agua","cuerpo":["La huella hídrica se divide en tres partes. El agua verde es la lluvia que queda en el suelo y usan las plantas: no se saca de ningún río ni napa. El agua azul es la que se saca de ríos, lagos o acuíferos, por ejemplo para riego o para una fábrica.","El agua gris es la cantidad de agua limpia que haría falta para diluir la contaminación que genera la producción (fertilizantes, efluentes) hasta niveles aceptables. No es agua que se use, sino agua que se \"ensucia\" en términos de capacidad del ambiente."],"lista":["Verde: lluvia que usan los cultivos","Azul: agua sacada de ríos, lagos o napas","Gris: agua necesaria para diluir la contaminación"]},"solucion":{}},{"slug":"agua-4.s2.p2","orden":2,"grupo":"agua-4.s2.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿De qué color es cada uso de agua?","grupos":[{"id":"g1","nombre":"Verde"},{"id":"g2","nombre":"Azul"},{"id":"g3","nombre":"Gris"}],"items":[{"id":"i1","texto":"La lluvia que riega un campo de trigo"},{"id":"i2","texto":"El riego por canales de un viñedo en Mendoza"},{"id":"i3","texto":"El agua necesaria para diluir el fertilizante que escurre a un arroyo"},{"id":"i4","texto":"El agua del suelo que usa una pastura"},{"id":"i5","texto":"El agua que bombea una fábrica de una napa"},{"id":"i6","texto":"El agua para diluir los efluentes de una curtiembre"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"La pregunta clave: ¿viene de la lluvia en el suelo, se saca de un río o napa, o es la capacidad de dilución que se consume?"}},{"slug":"agua-4.s2.p3","orden":3,"grupo":"agua-4.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué el color importa","cuerpo":["No es lo mismo usar lluvia que de todos modos iba a caer en ese campo que sacar agua de un río en una zona seca. El agua azul compite con otros usos: tomar, regar otros cultivos, mantener vivo el río. Por eso, en zonas áridas, la huella azul es la que más preocupa.","Por ejemplo, la mayor parte de la huella de la carne de pastoreo es agua verde: la lluvia que hizo crecer el pasto. Una fruta regada en una zona seca puede tener una huella total menor pero una huella azul mucho más sensible."]},"solucion":{}},{"slug":"agua-4.s2.p4","orden":4,"grupo":"agua-4.s2.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una región seca donde el río es la principal fuente de agua, ¿qué parte de la huella hídrica de un cultivo preocupa más?","opciones":[{"id":"o1","texto":"El agua azul, porque sale del río que todos usan"},{"id":"o2","texto":"El agua verde, porque es la lluvia"},{"id":"o3","texto":"El agua gris, porque siempre es la más grande"},{"id":"o4","texto":"Ninguna, todas las aguas son iguales"}]},"solucion":{"clave":["o1"],"explicacion":"El agua azul compite directamente con el consumo humano y con el caudal que necesita el río. En zonas secas es la más crítica.","por_opcion":{"o3":"El agua gris importa por la contaminación, pero en una zona seca la extracción del río es lo más crítico."}}},{"slug":"agua-4.s2.p5","orden":5,"grupo":"agua-4.s2.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Dos productos con la misma huella hídrica total tienen siempre el mismo impacto sobre los ríos.","razones":[{"id":"r1","texto":"Porque importa cuánto es verde, azul o gris y dónde se usa"},{"id":"r2","texto":"Porque la huella total dice todo lo necesario"},{"id":"r3","texto":"Porque el agua verde sale de los ríos"}]},"solucion":{"valor":false,"explicacion":"Depende de la composición. Si uno es casi todo agua verde (lluvia) y el otro casi todo azul (riego de un río en zona seca), el segundo presiona mucho más sobre los ríos.","clave":["r1"]}},{"slug":"agua-4.s2.p6","orden":6,"grupo":"agua-4.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El agua gris, con cuidado","cuerpo":["El agua gris es un concepto, no un volumen que alguien usó. Traduce la contaminación a litros: \"haría falta tanta agua limpia para diluir esto\". Sirve para comparar, pero no quiere decir que diluir sea la solución.","Como viste en la unidad anterior, diluir no elimina contaminantes persistentes. Bajar el agua gris es contaminar menos: usar la dosis justa de fertilizante, tratar los efluentes."]},"solucion":{}},{"slug":"agua-4.s2.p7","orden":7,"grupo":"agua-4.s2.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cultivo tiene una huella de 1.000 litros por kilo: 800 verdes y 120 azules. ¿Cuántos litros son grises?","unidad":"litros por kg","decimales":0},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"La huella total es la suma de las tres: 1.000 − 800 − 120 = 80 litros grises por kilo."}},{"slug":"agua-4.s2.p7.v2","orden":7,"grupo":"agua-4.s2.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cultivo tiene una huella de 2.000 litros por kilo: 1500 verdes y 300 azules. ¿Cuántos litros son grises?","unidad":"litros por kg","decimales":0},"solucion":{"valor":200,"tolerancia":4,"explicacion":"La huella total es la suma de las tres: 2.000 − 1500 − 300 = 200 litros grises por kilo."}},{"slug":"agua-4.s2.p7.v3","orden":7,"grupo":"agua-4.s2.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un cultivo tiene una huella de 1.500 litros por kilo: 900 verdes y 450 azules. ¿Cuántos litros son grises?","unidad":"litros por kg","decimales":0},"solucion":{"valor":150,"tolerancia":3,"explicacion":"La huella total es la suma de las tres: 1.500 − 900 − 450 = 150 litros grises por kilo."}},{"slug":"agua-4.s2.p8","orden":8,"grupo":"agua-4.s2.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el 94 % de la huella de la carne vacuna (15.400 L/kg) es agua verde, ¿cuántos litros por kilo son verdes? Redondeá a entero.","unidad":"litros por kg","decimales":0},"solucion":{"valor":14476,"tolerancia":2,"explicacion":"94 % de 15.400 = 15.400 × 94 ÷ 100 ≈ 14.476 litros verdes por kilo."}},{"slug":"agua-4.s2.p8.v2","orden":8,"grupo":"agua-4.s2.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el 82 % de la huella de el pollo (4.300 L/kg) es agua verde, ¿cuántos litros por kilo son verdes? Redondeá a entero.","unidad":"litros por kg","decimales":0},"solucion":{"valor":3526,"tolerancia":2,"explicacion":"82 % de 4.300 = 4.300 × 82 ÷ 100 ≈ 3.526 litros verdes por kilo."}},{"slug":"agua-4.s2.p8.v3","orden":8,"grupo":"agua-4.s2.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el 68 % de la huella de el arroz (2.500 L/kg) es agua verde, ¿cuántos litros por kilo son verdes? Redondeá a entero.","unidad":"litros por kg","decimales":0},"solucion":{"valor":1700,"tolerancia":2,"explicacion":"68 % de 2.500 = 2.500 × 68 ÷ 100 ≈ 1.700 litros verdes por kilo."}},{"slug":"agua-4.s2.p9","orden":9,"grupo":"agua-4.s2.p9","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada color con una forma de reducirlo.","izquierda":[{"id":"a1","texto":"Agua azul"},{"id":"a2","texto":"Agua gris"},{"id":"a3","texto":"Agua verde"}],"derecha":[{"id":"b1","texto":"Riego por goteo en lugar de por inundación"},{"id":"b2","texto":"Usar la dosis justa de fertilizante"},{"id":"b3","texto":"Cultivos adaptados a la lluvia del lugar"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Cada color se reduce de forma distinta: eficiencia de riego, menos contaminación, o elegir qué producir dónde."}},{"slug":"agua-4.s2.p10","orden":10,"grupo":"agua-4.s2.p10","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"\"La carne vacuna necesita unos 15.000 litros de agua por kilo,"},{"id":"s2","texto":"y por eso cada kilo seca un río entero\""},{"id":"s3","texto":"según promedios de la Water Footprint Network."},{"id":"s4","texto":"Esa cifra es igual en todos los campos del mundo.\""}]},"solucion":{"clave":["s2","s4"],"explicacion":"La huella total es real, pero sin separar colores y sin aclarar que es un promedio, se usa para asustar en vez de explicar.","por_opcion":{"s2":"La mayor parte es agua verde (lluvia en pasturas), no agua sacada de ríos.","s4":"Es un promedio: varía mucho según el lugar y el sistema de producción."}}},{"slug":"agua-4.s2.p11","orden":11,"grupo":"agua-4.s2.p11","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El agua {{0}} es lluvia que usan los cultivos, la {{1}} se saca de ríos o napas, y la {{2}} mide la contaminación en litros.","banco":[{"id":"w1","texto":"verde"},{"id":"w2","texto":"azul"},{"id":"w3","texto":"gris"},{"id":"w4","texto":"potable"},{"id":"w5","texto":"salada"},{"id":"w6","texto":"caliente"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres colores, tres preguntas distintas sobre el mismo producto."}},{"slug":"agua-4.s2.p12","orden":12,"grupo":"agua-4.s2.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un viñedo en una zona muy seca riega todo con agua de un río que viene bajando año a año. ¿Qué parte de su huella conviene reducir primero?","opciones":[{"id":"o1","texto":"La azul, con riego más eficiente como el goteo"},{"id":"o2","texto":"La verde, cambiando la lluvia de lugar"},{"id":"o3","texto":"La gris, lavando más seguido las uvas"},{"id":"o4","texto":"Ninguna: el vino no tiene huella hídrica"}]},"solucion":{"clave":["o1"],"explicacion":"En una zona seca con un río en baja, la huella azul es la que presiona. Pasar a goteo puede reducirla mucho con la misma producción.","por_opcion":{"o3":"Lavar más no reduce el agua gris; y en este caso el problema urgente es la extracción del río."}}},{"slug":"agua-4.s2.p13","orden":13,"grupo":"agua-4.s2.p13","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones reducen la huella gris de un producto? Marcá todas.","opciones":[{"id":"o1","texto":"Usar menos fertilizantes y plaguicidas"},{"id":"o2","texto":"Tratar los efluentes de la fábrica"},{"id":"o3","texto":"Elegir tintes menos contaminantes"},{"id":"o4","texto":"Aplicar agroquímicos con buenas prácticas"},{"id":"o5","texto":"Regar más para diluir la contaminación"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La huella gris baja cuando entra menos contaminación al agua, no cuando se agrega más agua para diluirla."}}]},{"slug":"agua-4.s3","orden":3,"tipo":"leccion","titulo_es":"El agua en tu plato","bajada_es":"Comparar alimentos por su huella hídrica, y las trampas de comparar solo por kilo.","minutos":11,"pasos":[{"slug":"agua-4.s3.p1","orden":1,"grupo":"agua-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué los productos animales suman más","cuerpo":["Un animal come mucho más alimento del que termina siendo carne, leche o huevos: es la pérdida de energía en cada paso de la cadena que viste en el tronco. Y cada kilo de ese alimento (granos, forraje) necesitó agua para crecer.","Por eso, en promedio, los productos animales tienen más huella hídrica por kilo que los vegetales. Entre las carnes, la vacuna suele ser la más alta, seguida por la de cerdo y la de pollo."]},"solucion":{}},{"slug":"agua-4.s3.p2","orden":2,"grupo":"agua-4.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un kilo de carne vacuna necesita tanta agua.","items":[{"id":"i1","texto":"El animal come muchos kilos de pasto y granos por cada kilo de carne"},{"id":"i2","texto":"Esos pastos y granos necesitan agua para crecer"},{"id":"i3","texto":"Se suma también el agua que toma y la de limpieza"},{"id":"i4","texto":"Toda esa agua se reparte en los kilos de carne producidos"},{"id":"i5","texto":"La carne retiene el agua que tomó la vaca en toda su vida"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Es la regla del 10 % del tronco aplicada al agua: cada paso de la cadena multiplica el agua necesaria."}},{"slug":"agua-4.s3.p3","orden":3,"grupo":"agua-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La trampa del \"por kilo\"","cuerpo":["Comparar solo por kilo puede engañar, porque los alimentos no alimentan igual. Un kilo de lechuga tiene muy pocas calorías y proteínas; un kilo de lentejas, muchas. Por eso algunos análisis comparan también por gramo de proteína o por caloría.","Aun así, incluso comparando por proteína, las legumbres suelen necesitar bastante menos agua que la carne vacuna. Lo importante es saber qué pregunta se está respondiendo con cada comparación."]},"solucion":{}},{"slug":"agua-4.s3.p4","orden":4,"grupo":"agua-4.s3.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Alguien dice: \"La lechuga tiene menos huella por kilo que las lentejas, así que conviene comer lechuga en vez de lentejas para cuidar el agua\". ¿Qué falla?","opciones":[{"id":"o1","texto":"Que no nutren igual: las lentejas dan más proteína"},{"id":"o2","texto":"Que la lechuga no necesita agua para crecer"},{"id":"o3","texto":"Que las lentejas no tienen huella hídrica"},{"id":"o4","texto":"Que la huella hídrica solo se mide en carnes"}]},"solucion":{"clave":["o1"],"explicacion":"Comparar por kilo tiene sentido entre alimentos parecidos. Entre alimentos que nutren distinto, conviene comparar por proteína o por comida completa.","por_opcion":{"o3":"Todas las plantas tienen huella: el problema es comparar alimentos que cumplen funciones distintas."}}},{"slug":"agua-4.s3.p5","orden":5,"grupo":"agua-4.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué se puede hacer","cuerpo":["Algunas elecciones cambian mucho la huella hídrica de una dieta: comer más legumbres, verduras y cereales, y menos carne vacuna; no desperdiciar comida (la comida tirada lleva toda su agua a la basura); y elegir productos de estación y locales cuando eso reduce el riego en zonas secas.","No se trata de prohibir nada: un guiso con menos carne y más lentejas, o un día sin carne por semana, ya mueven el número."],"lista":["Más legumbres, verduras y cereales","Menos carne vacuna, sin prohibir","No tirar comida: tirás también su agua","Aprovechar los restos"]},"solucion":{}},{"slug":"agua-4.s3.p6","orden":6,"grupo":"agua-4.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un guiso reemplazás 150 g de carne vacuna (15.400 L/kg) por 150 g de lentejas (unos 5.900 L/kg), ¿cuántos litros de agua virtual ahorrás?","unidad":"litros","decimales":0},"solucion":{"valor":1425,"tolerancia":28.5,"explicacion":"Diferencia por kilo: 15.400 − 5.900 = 9.500 litros. Por 150 g: 0,15 kg × 9.500 = 1.425 litros."}},{"slug":"agua-4.s3.p6.v2","orden":6,"grupo":"agua-4.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un guiso reemplazás 200 g de carne vacuna (15.400 L/kg) por 200 g de lentejas (unos 5.900 L/kg), ¿cuántos litros de agua virtual ahorrás?","unidad":"litros","decimales":0},"solucion":{"valor":1900,"tolerancia":38,"explicacion":"Diferencia por kilo: 15.400 − 5.900 = 9.500 litros. Por 200 g: 0,20 kg × 9.500 = 1.900 litros."}},{"slug":"agua-4.s3.p6.v3","orden":6,"grupo":"agua-4.s3.p6","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en un guiso reemplazás 100 g de carne vacuna (15.400 L/kg) por 100 g de lentejas (unos 5.900 L/kg), ¿cuántos litros de agua virtual ahorrás?","unidad":"litros","decimales":0},"solucion":{"valor":950,"tolerancia":19,"explicacion":"Diferencia por kilo: 15.400 − 5.900 = 9.500 litros. Por 100 g: 0,10 kg × 9.500 = 950 litros."}},{"slug":"agua-4.s3.p7","orden":7,"grupo":"agua-4.s3.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Tirar comida a la basura desperdicia también el agua que se usó para producirla.","razones":[{"id":"r1","texto":"Porque el agua usada para producirla se pierde con ella"},{"id":"r2","texto":"Porque la comida tirada devuelve el agua al río"},{"id":"r3","texto":"Porque la basura no tiene nada que ver con el agua"}]},"solucion":{"valor":true,"explicacion":"Toda el agua virtual de un alimento se pierde si el alimento se tira. Por eso reducir el desperdicio es una de las formas más directas de bajar la huella hídrica de lo que comemos.","clave":["r1"]}},{"slug":"agua-4.s3.p8","orden":8,"grupo":"agua-4.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia tira 2 kg de pan por semana (1.600 L/kg). ¿Cuántos litros de agua virtual tiran por año (52 semanas)?","unidad":"litros","decimales":0},"solucion":{"valor":166400,"tolerancia":3328,"explicacion":"2 kg × 1.600 L/kg = 3.200 litros por semana. × 52 semanas = 166.400 litros por año: más que el agua de muchas casas en meses."}},{"slug":"agua-4.s3.p8.v2","orden":8,"grupo":"agua-4.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia tira 3 kg de pan por semana (1.600 L/kg). ¿Cuántos litros de agua virtual tiran por año (52 semanas)?","unidad":"litros","decimales":0},"solucion":{"valor":249600,"tolerancia":4992,"explicacion":"3 kg × 1.600 L/kg = 4.800 litros por semana. × 52 semanas = 249.600 litros por año: más que el agua de muchas casas en meses."}},{"slug":"agua-4.s3.p8.v3","orden":8,"grupo":"agua-4.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia tira 1,5 kg de pan por semana (1.600 L/kg). ¿Cuántos litros de agua virtual tiran por año (52 semanas)?","unidad":"litros","decimales":0},"solucion":{"valor":124800,"tolerancia":2496,"explicacion":"1,5 kg × 1.600 L/kg = 2.400 litros por semana. × 52 semanas = 124.800 litros por año: más que el agua de muchas casas en meses."}},{"slug":"agua-4.s3.p9","orden":9,"grupo":"agua-4.s3.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué cambios bajan la huella hídrica de una dieta? Marcá todos.","opciones":[{"id":"o1","texto":"Sumar legumbres en lugar de parte de la carne vacuna"},{"id":"o2","texto":"Planificar las compras para no tirar comida"},{"id":"o3","texto":"Aprovechar los restos en otras comidas"},{"id":"o4","texto":"Comprar más cantidad para tener \"por las dudas\""},{"id":"o5","texto":"Cambiar el agua de la canilla por agua embotellada"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La huella hídrica de la comida se decide en qué y cuánto se compra y se come, no en qué agua se toma."}},{"slug":"agua-4.s3.p10","orden":10,"grupo":"agua-4.s3.p10","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas comidas por su agua virtual aproximada, de más a menos.","items":[{"id":"i1","texto":"Bife de 300 g con papas"},{"id":"i2","texto":"Milanesa de pollo de 200 g con ensalada"},{"id":"i3","texto":"Guiso de lentejas con arroz"},{"id":"i4","texto":"Ensalada de tomate y papa"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Los valores son aproximados, pero el orden se mantiene: la carne vacuna domina la huella de cualquier plato que la lleve.","valores":{"i1":"≈ 4.700 litros","i2":"≈ 900 litros","i3":"≈ 700 litros","i4":"≈ 150 litros"}}},{"slug":"agua-4.s3.p11","orden":11,"grupo":"agua-4.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este consejo de una publicidad y marcá lo que no tiene sentido.","segmentos":[{"id":"s1","texto":"Para cuidar el agua, comé más legumbres y verduras."},{"id":"s2","texto":"Y tomá solo agua mineral en botella, que tiene huella cero."},{"id":"s3","texto":"No tires comida: con ella se va toda el agua que costó producirla."},{"id":"s4","texto":"Comparar alimentos por kilo siempre da la respuesta correcta."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los consejos buenos hablan de qué se come y cuánto se tira. Los malos, de \"huella cero\" y comparaciones sin contexto.","por_opcion":{"s2":"El agua embotellada tiene más huella que la de red: envase, transporte y energía.","s4":"Por kilo engaña cuando los alimentos nutren muy distinto."}}},{"slug":"agua-4.s3.p12","orden":12,"grupo":"agua-4.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Comparar alimentos solo por {{0}} puede engañar: conviene mirar también la {{1}} que aportan, y recordar que tirar comida tira su {{2}}.","banco":[{"id":"w1","texto":"kilo"},{"id":"w2","texto":"proteína"},{"id":"w3","texto":"agua"},{"id":"w4","texto":"color"},{"id":"w5","texto":"precio"},{"id":"w6","texto":"envase"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para leer cualquier tabla de huellas de alimentos."}},{"slug":"agua-4.s3.p13","orden":13,"grupo":"agua-4.s3.p13","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Tiene mucha o poca agua virtual por kilo (promedio mundial)?","grupos":[{"id":"g1","nombre":"Mucha"},{"id":"g2","nombre":"Poca"}],"items":[{"id":"i1","texto":"Carne vacuna"},{"id":"i2","texto":"Tomate"},{"id":"i3","texto":"Chocolate"},{"id":"i4","texto":"Papa"},{"id":"i5","texto":"Queso"},{"id":"i6","texto":"Lechuga"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los productos animales y los que vienen de cultivos de largo ciclo suelen tener las huellas más altas por kilo."}}]},{"slug":"agua-4.s4","orden":4,"tipo":"leccion","titulo_es":"El agua en tu ropa y tus cosas","bajada_es":"Algodón, jeans, papel y celulares: el agua detrás de los objetos, y cómo reducirla usándolos más.","minutos":12,"pasos":[{"slug":"agua-4.s4.p1","orden":1,"grupo":"agua-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ropa","cuerpo":["El algodón es un cultivo con mucha demanda de agua, y en muchas regiones del mundo se riega. Por eso las prendas de algodón tienen huellas altas: unos 2.500 litros una remera y varios miles un jean, según promedios. A eso se suma el agua de teñir y terminar las telas, y la contaminación que eso genera (agua gris).","Las fibras sintéticas usan menos agua para producirse pero vienen del petróleo y sueltan microplásticos. No hay una fibra perfecta: la mejor prenda suele ser la que ya existe y se usa mucho tiempo."]},"solucion":{}},{"slug":"agua-4.s4.p2","orden":2,"grupo":"agua-4.s4.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué opción reduce más la huella hídrica de tu ropa?","opciones":[{"id":"o1","texto":"Usar más tiempo la ropa que ya tenés"},{"id":"o2","texto":"Comprar ropa nueva de algodón orgánico cada temporada"},{"id":"o3","texto":"Comprar solo ropa sintética nueva"},{"id":"o4","texto":"Lavar la ropa más seguido para que dure"}]},"solucion":{"clave":["o1"],"explicacion":"La prenda con menor huella es la que no hay que fabricar. Usar más tiempo lo que ya se tiene reparte la huella en más usos.","por_opcion":{"o3":"Usa menos agua para fabricarse, pero suma microplásticos y petróleo, y sigue siendo ropa nueva."}}},{"slug":"agua-4.s4.p3","orden":3,"grupo":"agua-4.s4.p3","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Repartir la huella en usos","planteo":"Una remera de 2.500 litros se usa 30 veces y se tira. Otra igual se usa 150 veces.","pasos":["Primera: 2.500 ÷ 30 ≈ 83 litros por uso.","Segunda: 2.500 ÷ 150 ≈ 17 litros por uso."],"resultado":"La misma remera, usada cinco veces más, tiene cinco veces menos huella por uso. Cuidar la ropa y usarla más es de las acciones más efectivas."},"solucion":{}},{"slug":"agua-4.s4.p4","orden":4,"grupo":"agua-4.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una remera tiene una huella de 2.500 litros y se usa 50 veces, ¿cuántos litros de agua virtual le corresponden a cada uso?","unidad":"litros por uso","decimales":1},"solucion":{"valor":50,"tolerancia":1,"explicacion":"2.500 ÷ 50 = 50 litros por uso. Cuantas más veces se usa, menos agua carga cada uso."}},{"slug":"agua-4.s4.p4.v2","orden":4,"grupo":"agua-4.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un jean tiene una huella de 8.000 litros y se usa 100 veces, ¿cuántos litros de agua virtual le corresponden a cada uso?","unidad":"litros por uso","decimales":1},"solucion":{"valor":80,"tolerancia":1.6,"explicacion":"8.000 ÷ 100 = 80 litros por uso. Cuantas más veces se usa, menos agua carga cada uso."}},{"slug":"agua-4.s4.p4.v3","orden":4,"grupo":"agua-4.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una remera tiene una huella de 2.500 litros y se usa 200 veces, ¿cuántos litros de agua virtual le corresponden a cada uso?","unidad":"litros por uso","decimales":1},"solucion":{"valor":12.5,"tolerancia":0.25,"explicacion":"2.500 ÷ 200 = 12,5 litros por uso. Cuantas más veces se usa, menos agua carga cada uso."}},{"slug":"agua-4.s4.p4.v4","orden":4,"grupo":"agua-4.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un jean tiene una huella de 8.000 litros y se usa 250 veces, ¿cuántos litros de agua virtual le corresponden a cada uso?","unidad":"litros por uso","decimales":1},"solucion":{"valor":32,"tolerancia":0.64,"explicacion":"8.000 ÷ 250 = 32 litros por uso. Cuantas más veces se usa, menos agua carga cada uso."}},{"slug":"agua-4.s4.p5","orden":5,"grupo":"agua-4.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Segunda mano y reparación","cuerpo":["Comprar ropa de segunda mano, intercambiar con amigos o reparar lo que se rompe evita fabricar prendas nuevas. Cada prenda que se reusa \"ahorra\" casi toda la huella de una nueva.","Lo mismo pasa con otros objetos: libros usados, muebles reparados, un celular que dura dos años más. La fabricación suele ser la parte más grande de la huella de un objeto."]},"solucion":{}},{"slug":"agua-4.s4.p6","orden":6,"grupo":"agua-4.s4.p6","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones reducen el agua virtual de lo que usás? Marcá todas.","opciones":[{"id":"o1","texto":"Comprar un jean de segunda mano"},{"id":"o2","texto":"Coser un botón en lugar de tirar la camisa"},{"id":"o3","texto":"Intercambiar ropa con amigos"},{"id":"o4","texto":"Usar el celular un par de años más"},{"id":"o5","texto":"Comprar una remera \"ecológica\" nueva cada mes"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Todas las primeras evitan fabricar algo nuevo. La última es consumo nuevo con etiqueta verde."}},{"slug":"agua-4.s4.p7","orden":7,"grupo":"agua-4.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Papel, electrónica y más","cuerpo":["El papel necesita agua para cultivar los árboles y, sobre todo, para fabricar la pasta: el papel reciclado usa menos agua y energía que el papel virgen. Imprimir solo lo necesario y usar las dos caras ayuda.","Los aparatos electrónicos tienen huellas hídricas altas por la minería de sus metales y la fabricación de chips, que usa agua ultrapura. Otra vez: lo más efectivo es usarlos más tiempo."]},"solucion":{}},{"slug":"agua-4.s4.p8","orden":8,"grupo":"agua-4.s4.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción reduce la huella hídrica sobre todo al fabricar menos, o al usar menos agua en casa?","grupos":[{"id":"g1","nombre":"Fabricar menos"},{"id":"g2","nombre":"Usar menos agua en casa"}],"items":[{"id":"i1","texto":"Usar el celular dos años más"},{"id":"i2","texto":"Lavar la ropa con carga completa"},{"id":"i3","texto":"Comprar ropa de segunda mano"},{"id":"i4","texto":"Acortar la ducha"},{"id":"i5","texto":"Imprimir doble faz"},{"id":"i6","texto":"Regar al atardecer"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos columnas importan. La primera se ve menos, pero muchas veces pesa más."}},{"slug":"agua-4.s4.p9","orden":9,"grupo":"agua-4.s4.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el agua de fabricar ropa se usa lejos, en otro país, no tiene ningún efecto que me importe.","razones":[{"id":"r1","texto":"Porque afecta ríos y personas donde se produce"},{"id":"r2","texto":"Porque el agua de otros países no es agua"},{"id":"r3","texto":"Porque la ropa no necesita agua para fabricarse"}]},"solucion":{"valor":false,"explicacion":"El agua de algodón regado en regiones secas puede agotar ríos y lagos enteros, y la contaminación de las tintorerías afecta a las comunidades que viven ahí. Lo que compramos tiene efectos donde se produce.","clave":["r1"]}},{"slug":"agua-4.s4.p10","orden":10,"grupo":"agua-4.s4.p10","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas decisiones por el agua virtual que ahorran, de más a menos.","items":[{"id":"i1","texto":"No comprar un jean nuevo este año"},{"id":"i2","texto":"No comprar dos remeras nuevas"},{"id":"i3","texto":"Imprimir en doble faz 100 hojas"},{"id":"i4","texto":"Cerrar la canilla al cepillarse una semana"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Evitar una prenda nueva ahorra más agua que semanas de cuidados en casa. Por eso esta unidad mira el agua invisible.","valores":{"i1":"≈ 8.000 litros","i2":"≈ 5.000 litros","i3":"unos cientos de litros","i4":"≈ 220 litros"}}},{"slug":"agua-4.s4.p11","orden":11,"grupo":"agua-4.s4.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta etiqueta de una tienda y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Remera de algodón orgánico certificado."},{"id":"s2","texto":"Comprarla ahorra agua, así que cuantas más compres, más ayudás."},{"id":"s3","texto":"Lavala con agua fría y carga completa."},{"id":"s4","texto":"Al ser orgánica, no tiene huella hídrica."}]},"solucion":{"clave":["s2","s4"],"explicacion":"\"Orgánico\" puede mejorar cómo se produce, pero no hace que comprar más sea bueno ni que la huella desaparezca.","por_opcion":{"s2":"Cada remera nueva suma huella; comprar más nunca ahorra.","s4":"El algodón orgánico también necesita agua para crecer."}}},{"slug":"agua-4.s4.p12","orden":12,"grupo":"agua-4.s4.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La prenda con menor huella es la que ya {{0}}: usarla más veces reparte su huella en más {{1}}.","banco":[{"id":"w1","texto":"existe"},{"id":"w2","texto":"usos"},{"id":"w3","texto":"viaja"},{"id":"w4","texto":"colores"},{"id":"w5","texto":"talles"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de esta lección, y la base de la rama de Consumo."}},{"slug":"agua-4.s4.p13","orden":13,"grupo":"agua-4.s4.p13","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un jean de segunda mano ahorra agua.","items":[{"id":"i1","texto":"Comprás un jean usado en lugar de uno nuevo"},{"id":"i2","texto":"No hace falta fabricar un jean nuevo"},{"id":"i3","texto":"No se cultiva algodón ni se tiñe tela para él"},{"id":"i4","texto":"Se evitan miles de litros de agua y su contaminación"},{"id":"i5","texto":"El jean usado absorbe menos agua al lavarlo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El ahorro no está en el lavado sino en la fabricación que se evita. El señuelo mezcla un uso posterior con la huella de producción."}},{"slug":"agua-4.s4.p14","orden":14,"grupo":"agua-4.s4.p14","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que un jean tiene una huella hídrica de unos 10.000 litros. Si se usa 50 veces antes de descartarlo, ¿cuántos litros le corresponden a cada uso?","unidad":"litros por uso","decimales":0,"contexto":"Huella de 10.000 litros; 50 usos."},"solucion":{"valor":200,"tolerancia":4,"explicacion":"10.000 ÷ 50 = 200 litros por uso. Cuantas más veces se usa una prenda, menos agua le corresponde a cada puesta. Valores de ejemplo."}},{"slug":"agua-4.s4.p14.v2","orden":14,"grupo":"agua-4.s4.p14","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que un jean tiene una huella hídrica de unos 10.000 litros. Si se usa 100 veces antes de descartarlo, ¿cuántos litros le corresponden a cada uso?","unidad":"litros por uso","decimales":0,"contexto":"Huella de 10.000 litros; 100 usos."},"solucion":{"valor":100,"tolerancia":2,"explicacion":"10.000 ÷ 100 = 100 litros por uso. Cuantas más veces se usa una prenda, menos agua le corresponde a cada puesta. Valores de ejemplo."}},{"slug":"agua-4.s4.p14.v3","orden":14,"grupo":"agua-4.s4.p14","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Supongamos que un jean tiene una huella hídrica de unos 10.000 litros. Si se usa 250 veces antes de descartarlo, ¿cuántos litros le corresponden a cada uso?","unidad":"litros por uso","decimales":0,"contexto":"Huella de 10.000 litros; 250 usos."},"solucion":{"valor":40,"tolerancia":0.8,"explicacion":"10.000 ÷ 250 = 40 litros por uso. Cuantas más veces se usa una prenda, menos agua le corresponde a cada puesta. Valores de ejemplo."}}]},{"slug":"agua-4.s5","orden":5,"tipo":"leccion","titulo_es":"El agua que viaja por el mundo","bajada_es":"Cuando un país exporta soja o carne, exporta también agua. Qué significa y cuándo importa.","minutos":11,"pasos":[{"slug":"agua-4.s5.p1","orden":1,"grupo":"agua-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Comercio de agua virtual","cuerpo":["Cuando un país vende alimentos o productos a otro, con ellos viaja el agua que se usó para producirlos. A eso se lo llama comercio de agua virtual. Un país que exporta granos exporta, sin verlo, millones de litros de agua.","Argentina es un gran exportador de productos agrícolas y ganaderos: soja, maíz, trigo, carne. Por eso es, en términos netos, un exportador importante de agua virtual, en su mayoría agua verde de la lluvia de la región pampeana."]},"solucion":{}},{"slug":"agua-4.s5.p2","orden":2,"grupo":"agua-4.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Si un país exporta 1 millón de toneladas de trigo, ¿qué más exporta sin verlo?","opciones":[{"id":"o1","texto":"El agua que se usó para cultivarlo"},{"id":"o2","texto":"El agua de los barcos que lo transportan"},{"id":"o3","texto":"Solo el agua que queda dentro del grano"},{"id":"o4","texto":"Nada: el trigo no tiene relación con el agua"}]},"solucion":{"clave":["o1"],"explicacion":"Es agua virtual: la usada para producir el trigo queda en el país de origen, pero su \"beneficio\" viaja con el grano.","por_opcion":{"o3":"El grano tiene poca agua adentro; lo que se exporta es el agua usada para producirlo."}}},{"slug":"agua-4.s5.p3","orden":3,"grupo":"agua-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un kilo de trigo tiene una huella de unos 1.800 litros, ¿cuántos millones de litros de agua virtual hay en 1.000 toneladas de trigo?","unidad":"millones de litros","decimales":0},"solucion":{"valor":1800,"tolerancia":36,"explicacion":"1.000 toneladas son 1.000.000 kg. × 1.800 L = 1.800.000.000 litros = 1.800 millones de litros."}},{"slug":"agua-4.s5.p3.v2","orden":3,"grupo":"agua-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un kilo de trigo tiene una huella de unos 1.800 litros, ¿cuántos millones de litros de agua virtual hay en 500 toneladas de trigo?","unidad":"millones de litros","decimales":0},"solucion":{"valor":900,"tolerancia":18,"explicacion":"500 toneladas son 500.000 kg. × 1.800 L = 900.000.000 litros = 900 millones de litros."}},{"slug":"agua-4.s5.p3.v3","orden":3,"grupo":"agua-4.s5.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un kilo de trigo tiene una huella de unos 1.800 litros, ¿cuántos millones de litros de agua virtual hay en 2.000 toneladas de trigo?","unidad":"millones de litros","decimales":0},"solucion":{"valor":3600,"tolerancia":72,"explicacion":"2.000 toneladas son 2.000.000 kg. × 1.800 L = 3.600.000.000 litros = 3.600 millones de litros."}},{"slug":"agua-4.s5.p4","orden":4,"grupo":"agua-4.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un recurso para los países secos","cuerpo":["Para un país con muy poca agua, importar alimentos es una forma de \"importar agua\": en vez de usar sus ríos para cultivar trigo, lo compra afuera y usa su agua para otras cosas. Muchos países de Medio Oriente y del norte de África dependen de esto.","Para un país con mucha lluvia, exportar alimentos producidos con agua verde puede ser un uso razonable de su agua. Lo delicado es cuando se exporta agua azul de zonas secas, o cuando la producción contamina (agua gris) y deja el problema en el país exportador."]},"solucion":{}},{"slug":"agua-4.s5.p5","orden":5,"grupo":"agua-4.s5.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta situación es un uso razonable del agua o una señal de alerta?","grupos":[{"id":"g1","nombre":"Uso razonable"},{"id":"g2","nombre":"Señal de alerta"}],"items":[{"id":"i1","texto":"Exportar trigo cultivado con lluvia en una zona húmeda"},{"id":"i2","texto":"Exportar frutas regadas con un río que se está secando"},{"id":"i3","texto":"Un país árido que importa granos y ahorra sus ríos"},{"id":"i4","texto":"Una producción que contamina el arroyo local para exportar"},{"id":"i5","texto":"Vaciar un acuífero para cultivos de exportación"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"No es el comercio en sí lo que preocupa, sino de dónde sale el agua y qué deja atrás."}},{"slug":"agua-4.s5.p6","orden":6,"grupo":"agua-4.s5.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Exportar alimentos siempre es malo para el agua del país que exporta.","razones":[{"id":"r1","texto":"Porque depende de qué agua se usa, dónde y cuánto se contamina"},{"id":"r2","texto":"Porque el comercio de alimentos no usa agua"},{"id":"r3","texto":"Porque exportar siempre agota todos los ríos"}]},"solucion":{"valor":false,"explicacion":"Depende. Si se produce con agua verde en una zona húmeda y sin contaminar, puede ser un buen uso del agua. El problema es exportar agua azul de zonas secas o dejar contaminación.","clave":["r1"]}},{"slug":"agua-4.s5.p7","orden":7,"grupo":"agua-4.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que deja atrás","cuerpo":["Cuando se produce para exportar, la huella azul y la gris quedan en el país que produce: los ríos que se usan y los arroyos que se contaminan están ahí, no en el país que consume. Por eso algunas miradas hablan de \"externalizar\" el impacto: quien consume no lo ve.","Conocer el agua virtual ayuda a hacerse preguntas: ¿de dónde viene esto?, ¿qué agua usó?, ¿qué dejó atrás? Son preguntas de consumidor, pero también de política: cómo se regula el uso del agua en zonas productivas."]},"solucion":{}},{"slug":"agua-4.s5.p8","orden":8,"grupo":"agua-4.s5.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo el consumo en un país puede secar un río en otro.","items":[{"id":"i1","texto":"Un país lejano compra mucha fruta fuera de estación"},{"id":"i2","texto":"Otra región la produce regando con el agua de un río"},{"id":"i3","texto":"La demanda crece año a año"},{"id":"i4","texto":"Se saca más agua de la que el río repone"},{"id":"i5","texto":"El río baja y afecta a quienes viven ahí"},{"id":"i6","texto":"El país que compra recibe menos lluvia"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El impacto se queda donde se produce. El país que compra no pierde lluvia: pierde la otra región su río."}},{"slug":"agua-4.s5.p9","orden":9,"grupo":"agua-4.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Agua virtual"},{"id":"a2","texto":"Comercio de agua virtual"},{"id":"a3","texto":"Exportador neto de agua virtual"},{"id":"a4","texto":"Huella azul"}],"derecha":[{"id":"b1","texto":"Agua usada para producir algo, que no queda en el producto"},{"id":"b2","texto":"El agua que viaja dentro de lo que se exporta e importa"},{"id":"b3","texto":"País que exporta más agua virtual de la que importa"},{"id":"b4","texto":"Agua sacada de ríos, lagos o napas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos que conectan tu plato con la economía del mundo."}},{"slug":"agua-4.s5.p10","orden":10,"grupo":"agua-4.s5.p10","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas conviene hacerse sobre el agua de un producto importado? Marcá todas.","opciones":[{"id":"o1","texto":"¿En qué región se produjo y cuánta agua hay ahí?"},{"id":"o2","texto":"¿Se regó con agua de ríos o napas, o creció con lluvia?"},{"id":"o3","texto":"¿Contaminó el agua del lugar donde se produjo?"},{"id":"o4","texto":"¿De qué color es el envase?"},{"id":"o5","texto":"¿Tiene más agua adentro que otro producto?"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Dónde, qué agua y qué contaminación: las tres preguntas que separan un buen uso del agua de uno problemático."}},{"slug":"agua-4.s5.p11","orden":11,"grupo":"agua-4.s5.p11","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta opinión de un foro y marcá los errores.","segmentos":[{"id":"s1","texto":"Argentina exporta mucha agua virtual en granos y carne."},{"id":"s2","texto":"Por eso hay que prohibir todas las exportaciones de alimentos."},{"id":"s3","texto":"Lo que conviene vigilar es el riego en zonas secas y la contaminación."},{"id":"s4","texto":"El agua virtual que se exporta se saca de las canillas de las ciudades."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender el agua virtual es entender matices: ni todo es un problema, ni nada lo es.","por_opcion":{"s2":"La mayor parte es agua verde de lluvia; lo que importa es cómo y dónde se produce.","s4":"Viene sobre todo de la lluvia en los campos y del riego, no de las redes urbanas."}}},{"slug":"agua-4.s5.p12","orden":12,"grupo":"agua-4.s5.p12","tipo":"completar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un país con poca agua puede {{0}} alimentos para ahorrar sus ríos; uno con mucha lluvia puede {{1}} alimentos hechos con agua {{2}}.","banco":[{"id":"w1","texto":"importar"},{"id":"w2","texto":"exportar"},{"id":"w3","texto":"verde"},{"id":"w4","texto":"comprar agua embotellada"},{"id":"w5","texto":"secar"},{"id":"w6","texto":"azul"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El comercio de agua virtual puede ser una forma de repartir mejor el agua del mundo, o de trasladar problemas: depende de cómo se haga."}},{"slug":"agua-4.s5.p13","orden":13,"grupo":"agua-4.s5.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué a un país muy seco le puede convenir importar trigo en lugar de cultivarlo?","opciones":[{"id":"o1","texto":"Porque así no gasta su poca agua de riego en ese cultivo"},{"id":"o2","texto":"Porque el trigo importado no tiene huella hídrica"},{"id":"o3","texto":"Porque el trigo crece mejor en el desierto"},{"id":"o4","texto":"Porque importar alimentos siempre es más barato"}]},"solucion":{"clave":["o1"],"explicacion":"Importar alimentos es, en parte, importar el agua que se usó para producirlos.","por_opcion":{"o3":"Necesitaría mucho riego, justo lo que le falta."}}}]},{"slug":"agua-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: el agua invisible","bajada_es":"Agua virtual, colores de la huella, comida, ropa y comercio, mezclados.","minutos":8,"pasos":[{"slug":"agua-4.s6.p1","orden":1,"grupo":"agua-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «El agua invisible». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"agua-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el menú del comedor","bajada_es":"Un comedor escolar quiere bajar el agua invisible de su menú sin perder nutrición. Hacé las cuentas.","minutos":10,"pasos":[{"slug":"agua-4.s7.p1","orden":1,"grupo":"agua-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["El comedor de una escuela sirve 200 almuerzos por día, cinco días por semana. Hoy el menú tiene carne vacuna tres días (150 g por porción), pollo un día (150 g) y fideos con salsa un día. La cooperadora quiere reducir la huella hídrica del menú sin que baje la proteína, y también bajar el desperdicio: se tira cerca del 15 % de lo que se cocina.","Huellas de referencia (promedios mundiales por kilo): carne vacuna 15.400 L; pollo 4.300 L; lentejas 5.900 L; fideos 1.800 L."]},"solucion":{}},{"slug":"agua-4.s7.p2","orden":2,"grupo":"agua-4.s7.p2","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos litros de agua virtual tiene la carne vacuna de UN día de almuerzos (200 porciones de 150 g)?","unidad":"litros","decimales":0,"contexto":"Comedor escolar: 200 almuerzos por día. Carne vacuna 150 g por porción, 15.400 L/kg; pollo 4.300 L/kg; lentejas 5.900 L/kg."},"solucion":{"valor":462000,"tolerancia":9240,"explicacion":"200 × 0,15 kg = 30 kg de carne. × 15.400 L/kg = 462.000 litros en un solo día."}},{"slug":"agua-4.s7.p3","orden":3,"grupo":"agua-4.s7.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si uno de los tres días de carne vacuna se reemplaza por pollo (misma cantidad), ¿cuántos litros por semana se ahorran?","unidad":"litros","decimales":0,"contexto":"Comedor escolar: 30 kg de carne por día de carne. Carne vacuna 15.400 L/kg; pollo 4.300 L/kg."},"solucion":{"valor":333000,"tolerancia":6660,"explicacion":"Son 30 kg de carne por día. Diferencia por kilo: 15.400 − 4.300 = 11.100 litros. × 30 kg = 333.000 litros por semana."}},{"slug":"agua-4.s7.p4","orden":4,"grupo":"agua-4.s7.p4","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La cooperadora propone un guiso de lentejas con un poco de carne en lugar de uno de los días de bife. ¿Por qué es una buena idea para el agua y la nutrición?","opciones":[{"id":"o1","texto":"Las lentejas dan proteína con menos agua"},{"id":"o2","texto":"Las lentejas no necesitan nada de agua para crecer"},{"id":"o3","texto":"El guiso tiene más agua adentro que el bife"},{"id":"o4","texto":"Porque la carne no aporta proteína"}]},"solucion":{"clave":["o1"],"explicacion":"Legumbres y carne combinadas mantienen la proteína y bajan mucho el agua virtual por porción.","por_opcion":{"o3":"El agua que tiene adentro el plato no es lo que se mide: es el agua usada para producir los ingredientes."}}},{"slug":"agua-4.s7.p5","orden":5,"grupo":"agua-4.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el comedor tira el 15 % de los 30 kg de carne vacuna de un día, ¿cuántos litros de agua virtual van a la basura ese día?","unidad":"litros","decimales":0},"solucion":{"valor":69300,"tolerancia":1386,"explicacion":"15 % de 30 kg = 4.5 kg tirados. × 15.400 L/kg = 69.300 litros de agua virtual a la basura, solo en carne."}},{"slug":"agua-4.s7.p5.v2","orden":5,"grupo":"agua-4.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el comedor tira el 10 % de los 30 kg de carne vacuna de un día, ¿cuántos litros de agua virtual van a la basura ese día?","unidad":"litros","decimales":0},"solucion":{"valor":46200,"tolerancia":924,"explicacion":"10 % de 30 kg = 3 kg tirados. × 15.400 L/kg = 46.200 litros de agua virtual a la basura, solo en carne."}},{"slug":"agua-4.s7.p5.v3","orden":5,"grupo":"agua-4.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el comedor tira el 20 % de los 30 kg de carne vacuna de un día, ¿cuántos litros de agua virtual van a la basura ese día?","unidad":"litros","decimales":0},"solucion":{"valor":92400,"tolerancia":1848,"explicacion":"20 % de 30 kg = 6 kg tirados. × 15.400 L/kg = 92.400 litros de agua virtual a la basura, solo en carne."}},{"slug":"agua-4.s7.p6","orden":6,"grupo":"agua-4.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas bajan el desperdicio del comedor? Marcá todas.","opciones":[{"id":"o1","texto":"Preguntar a los chicos qué platos dejan y ajustar las porciones"},{"id":"o2","texto":"Servir primero porciones medianas y ofrecer repetir"},{"id":"o3","texto":"Planificar las compras según la asistencia real"},{"id":"o4","texto":"Cocinar un 30 % extra por las dudas"},{"id":"o5","texto":"Servir siempre la porción más grande posible"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Ajustar porciones y compras a lo que realmente se come es la medida más barata y efectiva."}},{"slug":"agua-4.s7.p7","orden":7,"grupo":"agua-4.s7.p7","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas por el agua virtual semanal que ahorran, de más a menos.","items":[{"id":"i1","texto":"Cambiar un día de carne vacuna por pollo"},{"id":"i2","texto":"Bajar el desperdicio de carne del 15 % al 5 % en los tres días"},{"id":"i3","texto":"Servir fideos en porciones más chicas un día"},{"id":"i4","texto":"Cerrar las canillas de la cocina al lavar"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cambiar una carne por otra y bajar el desperdicio mueven cientos de miles de litros. Las canillas suman, pero están órdenes de magnitud abajo.","valores":{"i1":"≈ 333.000 litros","i2":"≈ 139.000 litros","i3":"decenas de miles de litros","i4":"cientos de litros"}}},{"slug":"agua-4.s7.p8","orden":8,"grupo":"agua-4.s7.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el comedor reduce la carne vacuna, necesariamente baja la proteína del menú.","razones":[{"id":"r1","texto":"Porque otras fuentes como legumbres, huevos o pollo aportan proteína"},{"id":"r2","texto":"Porque solo la carne vacuna tiene proteína"},{"id":"r3","texto":"Porque la proteína no importa en un comedor escolar"}]},"solucion":{"valor":false,"explicacion":"Se puede mantener la proteína con pollo, huevos, legumbres o combinaciones como lentejas con arroz. La nutrición depende del menú completo, no de un solo ingrediente.","clave":["r1"]}},{"slug":"agua-4.s7.p9","orden":9,"grupo":"agua-4.s7.p9","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La cooperadora escribe una nota para las familias. Marcá los errores.","segmentos":[{"id":"s1","texto":"Vamos a cambiar un día de carne vacuna por pollo y otro por un guiso de lentejas con carne."},{"id":"s2","texto":"Así ahorramos unos 300.000 litros por semana de agua de las canillas de la escuela."},{"id":"s3","texto":"También vamos a ajustar porciones para tirar menos comida."},{"id":"s4","texto":"Las lentejas no tienen proteína, pero son más baratas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen mensaje es preciso: agua virtual no es agua de canilla, y las legumbres sí nutren.","por_opcion":{"s2":"Es agua virtual de la producción de los alimentos, no agua de las canillas.","s4":"Las lentejas son una buena fuente de proteína."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"agua-5","rama":"agua","orden":5,"nivel":3,"titulo_es":"Cuencas, humedales e inundaciones","bajada_es":"El agua a escala de territorio: cómo funciona una cuenca, por qué los humedales valen oro, por qué se inundan las ciudades y cómo se reparte el agua.","objetivos_es":["Describir una cuenca con su divisoria, sus afluentes y su desembocadura","Explicar qué servicios prestan los humedales y qué los amenaza","Analizar por qué se inundan las ciudades y comparar soluciones grises y verdes","Evaluar beneficios y costos de una represa, incluido el caudal ecológico","Razonar sobre conflictos por el agua entre usos y entre provincias"],"repasa":["agua-3","agua-1","tronco-1","tronco-3"],"requiere_tronco":3,"fuentes":["acumar","ramsar","incendios-delta-2020","unep","un-water","ipbes-global","ley-25675-ambiente"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"agua-5.s1","orden":1,"tipo":"leccion","titulo_es":"La cuenca como sistema","bajada_es":"Divisorias, afluentes y desembocaduras: leer un territorio como lo lee el agua.","minutos":11,"pasos":[{"slug":"agua-5.s1.p1","orden":1,"grupo":"agua-5.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo lo que drena al mismo lugar","cuerpo":["Una cuenca es todo el territorio cuya agua de lluvia termina escurriendo hacia un mismo río, lago o mar. Sus bordes son las divisorias de aguas: las líneas de altura desde donde el agua cae hacia un lado o hacia el otro.","Dentro de una cuenca hay un río principal y sus afluentes, que a su vez tienen sus propias cuencas más chicas (subcuencas). Todo lo que pasa aguas arriba —una ciudad, un campo, una fábrica— se hace sentir aguas abajo."],"lista":["Divisoria de aguas: el borde de la cuenca","Afluente: río que desemboca en otro más grande","Subcuenca: la cuenca de un afluente","Desembocadura: donde el río principal termina"]},"solucion":{}},{"slug":"agua-5.s1.p2","orden":2,"grupo":"agua-5.s1.p2","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte de una cuenca con su descripción.","izquierda":[{"id":"a1","texto":"Divisoria de aguas"},{"id":"a2","texto":"Afluente"},{"id":"a3","texto":"Desembocadura"},{"id":"a4","texto":"Subcuenca"}],"derecha":[{"id":"b1","texto":"Línea de altura que separa hacia dónde escurre la lluvia"},{"id":"b2","texto":"Río que vuelca sus aguas en otro más grande"},{"id":"b3","texto":"Lugar donde el río principal llega al mar, a un lago o a otro río"},{"id":"b4","texto":"Cuenca de un afluente, dentro de la cuenca mayor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Con estas cuatro piezas se puede leer cualquier mapa hidrográfico, de un arroyo del barrio a la cuenca del Plata."}},{"slug":"agua-5.s1.p3","orden":3,"grupo":"agua-5.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cuenca del Plata","cuerpo":["La cuenca del Plata es una de las más grandes del mundo: sus ríos principales —el Paraná, el Paraguay y el Uruguay— drenan partes de cinco países (Argentina, Brasil, Paraguay, Bolivia y Uruguay) y terminan en el Río de la Plata.","Por eso lo que pasa en una selva de Brasil o en un campo de Paraguay puede cambiar el caudal y la calidad del agua que llega a Rosario o a Buenos Aires. Una cuenca compartida exige acuerdos entre países."],"destacado":{"valor":"5 países","texto":"comparten la cuenca del Plata: lo que pasa río arriba llega río abajo."}},"solucion":{}},{"slug":"agua-5.s1.p4","orden":4,"grupo":"agua-5.s1.p4","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ríos forman parte de la cuenca del Plata? Marcá todos.","opciones":[{"id":"o1","texto":"Paraná"},{"id":"o2","texto":"Paraguay"},{"id":"o3","texto":"Uruguay"},{"id":"o4","texto":"Colorado"},{"id":"o5","texto":"Santa Cruz"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El Colorado y el Santa Cruz son ríos patagónicos y cordilleranos que desembocan directo en el Atlántico, con sus propias cuencas."}},{"slug":"agua-5.s1.p5","orden":5,"grupo":"agua-5.s1.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el viaje de una gota que cae en el sur de Brasil y termina en Buenos Aires.","items":[{"id":"i1","texto":"Cae como lluvia sobre un campo del sur de Brasil"},{"id":"i2","texto":"Escurre hacia un afluente del Paraná"},{"id":"i3","texto":"El Paraná la lleva hacia el sur"},{"id":"i4","texto":"El Paraná forma el Delta"},{"id":"i5","texto":"Llega al Río de la Plata"},{"id":"i6","texto":"Cruza la cordillera de los Andes"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La gota nunca cruza los Andes: todo su recorrido está del lado atlántico. Es un viaje de miles de kilómetros en la misma cuenca."}},{"slug":"agua-5.s1.p6","orden":6,"grupo":"agua-5.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Arriba y abajo","cuerpo":["En una cuenca, las acciones aguas arriba tienen efectos aguas abajo. Si se deforesta una ladera, llega más sedimento al río y el agua corre más rápido; si una ciudad no trata sus cloacas, los pueblos de abajo reciben esa contaminación; si se represa un río, cambia el caudal para todos los que están después.","Por eso la cuenca, y no el municipio o la provincia, es la unidad natural para gestionar el agua, como viste en el caso Riachuelo."]},"solucion":{}},{"slug":"agua-5.s1.p7","orden":7,"grupo":"agua-5.s1.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Estos efectos se sienten sobre todo aguas arriba o aguas abajo de su causa?","grupos":[{"id":"g1","nombre":"Aguas abajo de la causa"},{"id":"g2","nombre":"En el mismo lugar o aguas arriba"}],"items":[{"id":"i1","texto":"Más sedimento por una deforestación en la ladera"},{"id":"i2","texto":"El lago que se forma detrás de una represa"},{"id":"i3","texto":"Contaminación de una ciudad sin tratamiento"},{"id":"i4","texto":"Un pozo que baja la napa alrededor de sí"},{"id":"i5","texto":"Menos caudal por una represa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"El agua corre en una sola dirección: por eso el \"aguas abajo\" hereda lo que se hace arriba. Pero algunos efectos, como el embalse, se forman del lado de arriba."}},{"slug":"agua-5.s1.p8","orden":8,"grupo":"agua-5.s1.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una ciudad río arriba vuelca sus cloacas sin tratar. ¿Quién sufre más el problema?","opciones":[{"id":"o1","texto":"Los pueblos y ecosistemas de río abajo"},{"id":"o2","texto":"Solo la propia ciudad que las vuelca"},{"id":"o3","texto":"Nadie, porque el río diluye todo en pocos metros"},{"id":"o4","texto":"Los pueblos de río arriba, más cerca de la naciente"}]},"solucion":{"clave":["o1"],"explicacion":"La contaminación viaja con el agua. Quien la genera muchas veces no la sufre, y ese desajuste es la raíz de muchos conflictos por el agua.","por_opcion":{"o3":"La autodepuración tiene límites: los efectos viajan kilómetros río abajo."}}},{"slug":"agua-5.s1.p9","orden":9,"grupo":"agua-5.s1.p9","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los límites de una cuenca coinciden con los límites de las provincias.","razones":[{"id":"r1","texto":"Porque las cuencas siguen el relieve, no la política"},{"id":"r2","texto":"Porque cada provincia tiene su propio río exclusivo"},{"id":"r3","texto":"Porque las cuencas se definen por ley"}]},"solucion":{"valor":false,"explicacion":"Las cuencas siguen el relieve, no los mapas políticos. La mayoría de las cuencas grandes cruzan varias provincias y a veces varios países.","clave":["r1"]}},{"slug":"agua-5.s1.p10","orden":10,"grupo":"agua-5.s1.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una cuenca tiene 3.100.000 km² y 920.000 km² están en Argentina, ¿qué porcentaje de la cuenca está en el país? Redondeá a entero.","unidad":"%","decimales":0},"solucion":{"valor":30,"tolerancia":1,"explicacion":"920.000 ÷ 3.100.000 × 100 ≈ 30 %. El resto está en otros países: por eso hacen falta acuerdos internacionales."}},{"slug":"agua-5.s1.p10.v2","orden":10,"grupo":"agua-5.s1.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una cuenca tiene 1.000.000 km² y 300.000 km² están en Argentina, ¿qué porcentaje de la cuenca está en el país? Redondeá a entero.","unidad":"%","decimales":0},"solucion":{"valor":30,"tolerancia":1,"explicacion":"300.000 ÷ 1.000.000 × 100 ≈ 30 %. El resto está en otros países: por eso hacen falta acuerdos internacionales."}},{"slug":"agua-5.s1.p10.v3","orden":10,"grupo":"agua-5.s1.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si una cuenca tiene 2.100.000 km² y 600.000 km² están en Argentina, ¿qué porcentaje de la cuenca está en el país? Redondeá a entero.","unidad":"%","decimales":0},"solucion":{"valor":29,"tolerancia":1,"explicacion":"600.000 ÷ 2.100.000 × 100 ≈ 29 %. El resto está en otros países: por eso hacen falta acuerdos internacionales."}},{"slug":"agua-5.s1.p11","orden":11,"grupo":"agua-5.s1.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción de un mapa y marcá los errores.","segmentos":[{"id":"s1","texto":"La divisoria de aguas separa hacia dónde escurre la lluvia."},{"id":"s2","texto":"Un afluente es un río que nace del mar."},{"id":"s3","texto":"La cuenca del Plata termina en el Río de la Plata."},{"id":"s4","texto":"Lo que pasa río abajo afecta sobre todo a quienes viven río arriba."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El agua fluye de arriba hacia abajo, y con ella viajan los efectos.","por_opcion":{"s2":"Un afluente vuelca sus aguas en otro río; no nace del mar.","s4":"Es al revés: lo de arriba afecta a los de abajo."}}},{"slug":"agua-5.s1.p12","orden":12,"grupo":"agua-5.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una {{0}} es todo el territorio que {{1}} hacia el mismo río; sus bordes son las {{2}} de aguas.","banco":[{"id":"w1","texto":"cuenca"},{"id":"w2","texto":"drena"},{"id":"w3","texto":"divisorias"},{"id":"w4","texto":"provincia"},{"id":"w5","texto":"evapora"},{"id":"w6","texto":"costas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Leer el territorio por cuencas es leerlo como lo lee el agua."}},{"slug":"agua-5.s1.p13","orden":13,"grupo":"agua-5.s1.p13","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido del agua en una cuenca, desde lo más alto hasta el final.","items":[{"id":"i1","texto":"Un arroyo de montaña cerca de la divisoria"},{"id":"i2","texto":"Un río afluente"},{"id":"i3","texto":"El río principal"},{"id":"i4","texto":"El estuario, donde se mezcla con el mar"},{"id":"i5","texto":"El mar"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Todo lo que pasa aguas arriba viaja por ese mismo camino hasta el final."}}]},{"slug":"agua-5.s2","orden":2,"tipo":"leccion","titulo_es":"Humedales: esponjas vivas","bajada_es":"Qué hacen los humedales por nosotros, por qué se pierden y qué pasa cuando se queman o se rellenan.","minutos":12,"pasos":[{"slug":"agua-5.s2.p1","orden":1,"grupo":"agua-5.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es un humedal","cuerpo":["Un humedal es un ambiente donde el agua cubre el suelo o lo mantiene saturado durante al menos una parte del año: bañados, esteros, lagunas, turberas, mallines, deltas y costas con marismas. En Argentina hay humedales enormes, como los Esteros del Iberá o el Delta del Paraná, y otros chiquitos en cada pueblo.","Por mucho tiempo se los vio como \"tierras improductivas\" para drenar o rellenar. Hoy se sabe que están entre los ecosistemas más valiosos del planeta."]},"solucion":{}},{"slug":"agua-5.s2.p2","orden":2,"grupo":"agua-5.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que hacen","cuerpo":["Los humedales funcionan como esponjas: absorben el agua en las crecidas y la liberan de a poco en las secas, lo que reduce inundaciones y sequías. Filtran el agua: sus plantas y su suelo retienen sedimentos y nutrientes. Recargan acuíferos. Guardan carbono, sobre todo las turberas.","Además son hogar de una enorme diversidad de vida —aves, peces, anfibios, carpinchos, ciervos de los pantanos— y sostienen actividades como la pesca y el turismo."],"lista":["Amortiguan inundaciones y sequías","Filtran y limpian el agua","Recargan acuíferos","Guardan carbono","Albergan mucha biodiversidad"]},"solucion":{}},{"slug":"agua-5.s2.p3","orden":3,"grupo":"agua-5.s2.p3","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué servicios presta un humedal sano? Marcá todos.","opciones":[{"id":"o1","texto":"Absorber agua en las crecidas"},{"id":"o2","texto":"Retener sedimentos y nutrientes"},{"id":"o3","texto":"Dar hábitat a aves, peces y anfibios"},{"id":"o4","texto":"Guardar carbono en el suelo"},{"id":"o5","texto":"Producir agua salada para la costa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un humedal hace muchas cosas a la vez, y gratis. Reemplazar cualquiera de esas funciones con obras cuesta muchísimo."}},{"slug":"agua-5.s2.p4","orden":4,"grupo":"agua-5.s2.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un humedal reduce una inundación río abajo.","items":[{"id":"i1","texto":"Una lluvia fuerte hace crecer el río"},{"id":"i2","texto":"El agua se expande sobre el humedal"},{"id":"i3","texto":"El humedal la retiene como una esponja"},{"id":"i4","texto":"La devuelve de a poco en los días siguientes"},{"id":"i5","texto":"El pico de la crecida río abajo es más bajo"},{"id":"i6","texto":"El humedal evapora toda el agua en una hora"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El humedal no hace desaparecer el agua: la reparte en el tiempo. Eso baja el pico de la crecida, que es lo que inunda."}},{"slug":"agua-5.s2.p5","orden":5,"grupo":"agua-5.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que los amenaza","cuerpo":["Se estima que buena parte de los humedales del mundo se perdieron en los últimos siglos. Las causas principales: drenarlos para agricultura, rellenarlos para construir, contaminarlos y quemarlos.","En el Delta del Paraná hubo grandes incendios en 2020 y en años siguientes, en un contexto de bajante extrema del río, que afectaron cientos de miles de hectáreas y llenaron de humo a ciudades como Rosario. Muchos se asociaron a quemas para manejo de pasturas que se descontrolaron."]},"solucion":{}},{"slug":"agua-5.s2.p6","orden":6,"grupo":"agua-5.s2.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta actividad amenaza al humedal o lo protege?","grupos":[{"id":"g1","nombre":"Lo amenaza"},{"id":"g2","nombre":"Lo protege"}],"items":[{"id":"i1","texto":"Rellenarlo para construir un barrio"},{"id":"i2","texto":"Declararlo área protegida con control real"},{"id":"i3","texto":"Drenarlo con canales para sembrar"},{"id":"i4","texto":"Restaurar la vegetación nativa de las orillas"},{"id":"i5","texto":"Quemar pastizales en época seca"},{"id":"i6","texto":"Limitar los terraplenes que cortan el paso del agua"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las amenazas suelen cambiar cómo se mueve el agua; las protecciones la dejan moverse."}},{"slug":"agua-5.s2.p7","orden":7,"grupo":"agua-5.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ramsar","cuerpo":["La Convención de Ramsar, firmada en 1971 en Irán, es un tratado internacional para la conservación y el uso racional de los humedales. Los países designan \"sitios Ramsar\", humedales de importancia internacional.","Argentina tiene más de veinte sitios Ramsar, entre ellos la Laguna de Pozuelos, la Laguna Mar Chiquita en Córdoba y los Esteros del Iberá. En el Congreso se discutieron varias veces proyectos de ley de presupuestos mínimos para humedales."]},"solucion":{}},{"slug":"agua-5.s2.p8","orden":8,"grupo":"agua-5.s2.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es un sitio Ramsar?","opciones":[{"id":"o1","texto":"Un humedal de importancia internacional designado por un país"},{"id":"o2","texto":"Una represa que regula el caudal de un río"},{"id":"o3","texto":"Un parque nacional con cualquier tipo de ambiente"},{"id":"o4","texto":"Una planta de tratamiento de agua en un humedal"}]},"solucion":{"clave":["o1"],"explicacion":"Ramsar reconoce el valor internacional de un humedal y compromete al país a usarlo de forma racional.","por_opcion":{"o3":"Ramsar es específico de humedales, aunque un sitio puede estar dentro de un parque."}}},{"slug":"agua-5.s2.p9","orden":9,"grupo":"agua-5.s2.p9","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un humedal sin agua durante parte del año deja de ser un humedal y se puede rellenar sin problemas.","razones":[{"id":"r1","texto":"Porque inundarse y secarse de forma periódica es parte de cómo funciona"},{"id":"r2","texto":"Porque los humedales tienen agua todo el año siempre"},{"id":"r3","texto":"Porque rellenar un humedal le agrega capacidad de absorber agua"}]},"solucion":{"valor":false,"explicacion":"Muchos humedales se secan en parte según la estación o los años: esa variación es parte de su funcionamiento. Rellenarlo en la época seca destruye su capacidad de absorber la próxima crecida.","clave":["r1"]}},{"slug":"agua-5.s2.p10","orden":10,"grupo":"agua-5.s2.p10","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos humedales argentinos por superficie aproximada, de mayor a menor.","items":[{"id":"i1","texto":"Delta del Paraná"},{"id":"i2","texto":"Esteros del Iberá"},{"id":"i3","texto":"Laguna Mar Chiquita (Córdoba)"},{"id":"i4","texto":"Reserva Ecológica Costanera Sur"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Valores aproximados. Del Delta a una reserva urbana hay cuatro órdenes de magnitud, pero todos cumplen funciones.","valores":{"i1":"≈ 1,75 millones de hectáreas","i2":"≈ 1,3 millones de hectáreas","i3":"≈ 600.000 hectáreas en crecidas","i4":"≈ 350 hectáreas"}}},{"slug":"agua-5.s2.p11","orden":11,"grupo":"agua-5.s2.p11","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este cartel de un loteo y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Barrio náutico con vista al río."},{"id":"s2","texto":"Construido sobre terrenos \"improductivos\" rellenados con tierra."},{"id":"s3","texto":"Con lagunas artificiales para el paisaje."},{"id":"s4","texto":"Sin ningún riesgo de inundación para los barrios vecinos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El agua que el relleno deja sin lugar no desaparece: se va a los terrenos de al lado.","por_opcion":{"s2":"Los humedales no son improductivos: prestan servicios que se pierden al rellenarlos.","s4":"Rellenar un humedal le quita a la zona su capacidad de absorber crecidas: el agua va a otro lado."}}},{"slug":"agua-5.s2.p12","orden":12,"grupo":"agua-5.s2.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada humedal con su tipo.","izquierda":[{"id":"a1","texto":"Esteros del Iberá"},{"id":"a2","texto":"Delta del Paraná"},{"id":"a3","texto":"Mallín patagónico"},{"id":"a4","texto":"Bahía de Samborombón"}],"derecha":[{"id":"b1","texto":"Esteros y lagunas de agua dulce"},{"id":"b2","texto":"Islas y bañados de un delta de río"},{"id":"b3","texto":"Pradera húmeda de montaña"},{"id":"b4","texto":"Humedal costero con marismas"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Hay humedales de muchas formas. Todos tienen en común el agua que satura el suelo al menos parte del año."}},{"slug":"agua-5.s2.p13","orden":13,"grupo":"agua-5.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los humedales funcionan como {{0}}: guardan agua en las {{1}} y la liberan en las {{2}}.","banco":[{"id":"w1","texto":"esponjas"},{"id":"w2","texto":"crecidas"},{"id":"w3","texto":"secas"},{"id":"w4","texto":"piedras"},{"id":"w5","texto":"heladas"},{"id":"w6","texto":"noches"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Esa capacidad de repartir el agua en el tiempo es su servicio más valioso frente a inundaciones y sequías."}},{"slug":"agua-5.s2.p14","orden":14,"grupo":"agua-5.s2.p14","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los incendios en humedales como los del Delta son tan dañinos?","opciones":[{"id":"o1","texto":"Queman vegetación y liberan el carbono guardado en el suelo"},{"id":"o2","texto":"Porque el agua del humedal se vuelve salada"},{"id":"o3","texto":"Porque apagan para siempre las crecidas del río"},{"id":"o4","texto":"Porque los humedales no vuelven a tener agua nunca más"}]},"solucion":{"clave":["o1"],"explicacion":"Un humedal quemado pierde fauna, vegetación y carbono, y tarda años en recuperarse.","por_opcion":{"o3":"Las crecidas siguen; lo que se pierde es el ecosistema y su carbono."}}}]},{"slug":"agua-5.s3","orden":3,"tipo":"leccion","titulo_es":"Por qué se inundan las ciudades","bajada_es":"Cemento, arroyos entubados y lluvias más intensas: las causas, y la diferencia entre obras grises y soluciones verdes.","minutos":12,"pasos":[{"slug":"agua-5.s3.p1","orden":1,"grupo":"agua-5.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La ciudad impermeable","cuerpo":["En un campo o un bosque, gran parte de la lluvia se infiltra en el suelo o la retienen las plantas. En una ciudad, calles, veredas y techos son impermeables: casi toda el agua escurre por la superficie, y lo hace rápido.","El resultado es que, ante la misma lluvia, llega mucha más agua y en menos tiempo a los desagües y arroyos. Si superan su capacidad, el agua se acumula en las calles."]},"solucion":{}},{"slug":"agua-5.s3.p2","orden":2,"grupo":"agua-5.s3.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de una inundación urbana.","items":[{"id":"i1","texto":"Una tormenta fuerte cae sobre la ciudad"},{"id":"i2","texto":"El suelo impermeable no deja infiltrar el agua"},{"id":"i3","texto":"Toda el agua escurre rápido hacia los desagües"},{"id":"i4","texto":"Los desagües y arroyos se saturan"},{"id":"i5","texto":"El agua se acumula en las calles y las casas"},{"id":"i6","texto":"Los árboles de la vereda producen más lluvia"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es la misma cadena del arroyo del barrio del tronco, a escala de ciudad."}},{"slug":"agua-5.s3.p3","orden":3,"grupo":"agua-5.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los arroyos escondidos","cuerpo":["Muchas ciudades crecieron sobre arroyos que después se entubaron: se metieron en conductos bajo las calles. En la Ciudad de Buenos Aires, arroyos como el Maldonado, el Vega o el Medrano corren entubados debajo de avenidas. Cuando llueve mucho, el agua \"recuerda\" su valle y se junta sobre esas zonas bajas.","Para el Maldonado se construyeron grandes túneles aliviadores, inaugurados en 2012, que llevan el exceso de agua al Río de la Plata. Son un ejemplo de obra gris: infraestructura de cemento para mover el agua."]},"solucion":{}},{"slug":"agua-5.s3.p4","orden":4,"grupo":"agua-5.s3.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las calles que están sobre un arroyo entubado se inundan más?","opciones":[{"id":"o1","texto":"Porque están en el valle natural adonde el agua escurre"},{"id":"o2","texto":"Porque el caño del arroyo pierde agua potable"},{"id":"o3","texto":"Porque ahí llueve más que en el resto de la ciudad"},{"id":"o4","texto":"Porque el asfalto de esas calles es de peor calidad"}]},"solucion":{"clave":["o1"],"explicacion":"El arroyo está bajo tierra, pero el relieve sigue ahí: el agua de lluvia baja hacia su valle como siempre lo hizo.","por_opcion":{"o3":"La lluvia es la misma: lo que cambia es que el agua escurre hacia el valle del arroyo."}}},{"slug":"agua-5.s3.p5","orden":5,"grupo":"agua-5.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Soluciones verdes","cuerpo":["Además de las obras grises (túneles, conductos, bombas), existen soluciones basadas en la naturaleza: plazas y parques que se pueden inundar un rato sin daño (reservorios), veredas y estacionamientos permeables, cordones verdes y jardines de lluvia que infiltran el agua, techos verdes que la retienen, y arbolado que intercepta parte de la lluvia.","Estas soluciones no reemplazan del todo a las grises en tormentas extremas, pero reducen y retrasan el agua que llega a los desagües, y además dan sombra, verde y biodiversidad."],"lista":["Plazas reservorio que se inundan sin daño","Pavimentos permeables","Jardines de lluvia en veredas","Techos verdes","Más árboles y suelo absorbente"]},"solucion":{}},{"slug":"agua-5.s3.p6","orden":6,"grupo":"agua-5.s3.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una solución gris o una solución verde?","grupos":[{"id":"g1","nombre":"Gris (infraestructura de cemento)"},{"id":"g2","nombre":"Verde (basada en la naturaleza)"}],"items":[{"id":"i1","texto":"Túnel aliviador bajo la avenida"},{"id":"i2","texto":"Plaza que funciona como reservorio"},{"id":"i3","texto":"Estación de bombeo"},{"id":"i4","texto":"Jardín de lluvia en la vereda"},{"id":"i5","texto":"Ensanchar los conductos pluviales"},{"id":"i6","texto":"Techo verde en un edificio"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo ideal es combinarlas: las verdes reducen el agua que llega, las grises la manejan cuando igual sobra."}},{"slug":"agua-5.s3.p7","orden":7,"grupo":"agua-5.s3.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué beneficios extra tienen las soluciones verdes, además de manejar la lluvia? Marcá todos.","opciones":[{"id":"o1","texto":"Dan sombra y bajan la temperatura"},{"id":"o2","texto":"Suman hábitat para aves e insectos"},{"id":"o3","texto":"Mejoran el paisaje y el uso del espacio público"},{"id":"o4","texto":"Eliminan por completo el riesgo de cualquier inundación"},{"id":"o5","texto":"No necesitan ningún mantenimiento"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Son soluciones con muchos beneficios a la vez. Pero no hacen magia: en eventos extremos también hacen falta las obras grises, y todas necesitan mantenimiento."}},{"slug":"agua-5.s3.p8","orden":8,"grupo":"agua-5.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una plaza reservorio de 2.000 m² puede retener temporalmente una lámina de agua. Si una tormenta deja 40 mm, ¿cuántos litros caen sobre la plaza?","unidad":"litros","decimales":0},"solucion":{"valor":80000,"tolerancia":1600,"explicacion":"Cada milímetro sobre un metro cuadrado es un litro: 2.000 × 40 = 80.000 litros que no llegan de golpe a los desagües si la plaza los retiene."}},{"slug":"agua-5.s3.p8.v2","orden":8,"grupo":"agua-5.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una plaza reservorio de 5.000 m² puede retener temporalmente una lámina de agua. Si una tormenta deja 30 mm, ¿cuántos litros caen sobre la plaza?","unidad":"litros","decimales":0},"solucion":{"valor":150000,"tolerancia":3000,"explicacion":"Cada milímetro sobre un metro cuadrado es un litro: 5.000 × 30 = 150.000 litros que no llegan de golpe a los desagües si la plaza los retiene."}},{"slug":"agua-5.s3.p8.v3","orden":8,"grupo":"agua-5.s3.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una plaza reservorio de 1.200 m² puede retener temporalmente una lámina de agua. Si una tormenta deja 60 mm, ¿cuántos litros caen sobre la plaza?","unidad":"litros","decimales":0},"solucion":{"valor":72000,"tolerancia":1440,"explicacion":"Cada milímetro sobre un metro cuadrado es un litro: 1.200 × 60 = 72.000 litros que no llegan de golpe a los desagües si la plaza los retiene."}},{"slug":"agua-5.s3.p9","orden":9,"grupo":"agua-5.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lluvias más intensas","cuerpo":["El cambio climático hace más frecuentes las lluvias muy intensas en muchas regiones, porque un aire más caliente puede cargar más vapor de agua. Eso quiere decir que infraestructura diseñada para las tormentas del pasado puede quedar corta.","Por eso las ciudades planifican con escenarios futuros, protegen sus zonas absorbentes y evitan construir en las áreas que el agua necesita."]},"solucion":{}},{"slug":"agua-5.s3.p10","orden":10,"grupo":"agua-5.s3.p10","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una ciudad construyó túneles aliviadores, ya no necesita cuidar sus espacios verdes para manejar la lluvia.","razones":[{"id":"r1","texto":"Porque seguir impermeabilizando satura cualquier obra"},{"id":"r2","texto":"Porque los túneles tienen capacidad infinita"},{"id":"r3","texto":"Porque los espacios verdes aumentan las inundaciones"}]},"solucion":{"valor":false,"explicacion":"Los túneles tienen una capacidad máxima. Si la ciudad sigue impermeabilizando, cada vez llega más agua más rápido y la obra queda chica antes de tiempo. Las soluciones verdes alivian a las grises.","clave":["r1"]}},{"slug":"agua-5.s3.p11","orden":11,"grupo":"agua-5.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta propuesta de un candidato y marcá lo que no se sostiene.","segmentos":[{"id":"s1","texto":"Vamos a mantener limpios los sumideros antes de la temporada de lluvias."},{"id":"s2","texto":"Vamos a pavimentar todas las plazas para que el agua corra más rápido al río."},{"id":"s3","texto":"Vamos a sumar jardines de lluvia en las avenidas."},{"id":"s4","texto":"Con eso las inundaciones van a desaparecer para siempre."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Hacer correr el agua más rápido es trasladar el problema. Y ninguna obra promete riesgo cero con honestidad.","por_opcion":{"s2":"Quitar suelo absorbente aumenta el agua que llega de golpe a los desagües.","s4":"Ninguna solución elimina el riesgo; se reduce y se maneja."}}},{"slug":"agua-5.s3.p12","orden":12,"grupo":"agua-5.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las soluciones {{0}} mueven el agua con cemento; las {{1}} la infiltran o la retienen; lo mejor es {{2}}.","banco":[{"id":"w1","texto":"grises"},{"id":"w2","texto":"verdes"},{"id":"w3","texto":"combinarlas"},{"id":"w4","texto":"rojas"},{"id":"w5","texto":"eliminarlas"},{"id":"w6","texto":"secas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Grises y verdes no compiten: se complementan."}},{"slug":"agua-5.s3.p13","orden":13,"grupo":"agua-5.s3.p13","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas superficies por cuánta lluvia infiltran, de más a menos.","items":[{"id":"i1","texto":"Un bosque con suelo cubierto de hojas"},{"id":"i2","texto":"Una plaza con pasto"},{"id":"i3","texto":"Un estacionamiento de pavimento permeable"},{"id":"i4","texto":"Una avenida asfaltada"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto menos infiltra una superficie, más agua escurre hacia los desagües. La ciudad, casi toda asfalto y techos, está en la última fila.","valores":{"i1":"infiltra la mayor parte","i2":"infiltra bastante","i3":"infiltra algo","i4":"casi nada"}}},{"slug":"agua-5.s3.p14","orden":14,"grupo":"agua-5.s3.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada solución con cómo maneja la lluvia.","izquierda":[{"id":"a1","texto":"Techo verde"},{"id":"a2","texto":"Plaza inundable"},{"id":"a3","texto":"Pavimento permeable"},{"id":"a4","texto":"Túnel aliviador"}],"derecha":[{"id":"b1","texto":"Retiene parte de la lluvia sobre el techo"},{"id":"b2","texto":"Guarda agua por unas horas en las tormentas"},{"id":"b3","texto":"Deja que el agua infiltre en el suelo"},{"id":"b4","texto":"Lleva el agua rápido hacia el río"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Las verdes retienen e infiltran; las grises conducen. Combinadas, protegen mejor."}}]},{"slug":"agua-5.s4","orden":4,"tipo":"leccion","titulo_es":"Represas y caudal ecológico","bajada_es":"Energía, riego y control de crecidas, a cambio de ríos cortados. Cómo se evalúa una represa.","minutos":11,"pasos":[{"slug":"agua-5.s4.p1","orden":1,"grupo":"agua-5.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué dan las represas","cuerpo":["Una represa corta un río y forma un embalse. Sirve para generar electricidad (hidroeléctricas), guardar agua para riego y consumo, y regular las crecidas. En Argentina hay grandes represas sobre el Paraná, el Uruguay, el Limay y muchos otros ríos, y la energía hidroeléctrica es una parte importante de la electricidad del país.","Son infraestructuras muy útiles, y también tienen costos ambientales y sociales. Evaluarlas es sopesar las dos cosas."]},"solucion":{}},{"slug":"agua-5.s4.p2","orden":2,"grupo":"agua-5.s4.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un beneficio o un costo de una represa?","grupos":[{"id":"g1","nombre":"Beneficio"},{"id":"g2","nombre":"Costo"}],"items":[{"id":"i1","texto":"Genera electricidad sin quemar combustibles"},{"id":"i2","texto":"Inunda tierras, bosques y a veces pueblos"},{"id":"i3","texto":"Guarda agua para riego en épocas secas"},{"id":"i4","texto":"Corta el paso de peces que migran"},{"id":"i5","texto":"Reduce los picos de algunas crecidas"},{"id":"i6","texto":"Retiene sedimentos que el río llevaba al delta"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las dos columnas son reales. Una buena evaluación las pone a la vista antes de decidir, no después."}},{"slug":"agua-5.s4.p3","orden":3,"grupo":"agua-5.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un río cortado","cuerpo":["Muchos peces de río, como el sábalo o el dorado en la cuenca del Plata, migran río arriba para reproducirse. Una represa sin pasos para peces puede cortar ese ciclo. Además, el embalse retiene sedimentos: aguas abajo, el río llega \"con hambre\" de sedimento y puede erosionar sus orillas y el delta.","También cambia el ritmo del agua: un río que antes tenía crecidas y bajantes naturales pasa a tener un caudal regulado por las necesidades de la usina o del riego."]},"solucion":{}},{"slug":"agua-5.s4.p4","orden":4,"grupo":"agua-5.s4.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una represa puede afectar a un delta río abajo.","items":[{"id":"i1","texto":"El embalse frena el agua"},{"id":"i2","texto":"Los sedimentos se depositan en el fondo del embalse"},{"id":"i3","texto":"El río sale de la represa con poco sedimento"},{"id":"i4","texto":"Llega menos sedimento al delta"},{"id":"i5","texto":"El delta deja de crecer y puede erosionarse"},{"id":"i6","texto":"La represa agrega arena nueva al río"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los deltas se construyen con el sedimento que traen los ríos. Si el sedimento queda atrapado arriba, el delta pierde su material de construcción."}},{"slug":"agua-5.s4.p5","orden":5,"grupo":"agua-5.s4.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caudal ecológico","cuerpo":["El caudal ecológico es la cantidad de agua, y el ritmo de variación, que un río necesita para mantener vivo su ecosistema y los usos que dependen de él. No alcanza con \"que corra algo de agua\": también importan las crecidas estacionales que disparan la reproducción de peces o inundan los humedales.","Cuando se reparte el agua de un río entre riego, energía y ciudades, el caudal ecológico es la parte que se le reserva al río mismo."],"destacado":{"valor":"Caudal ecológico","texto":"el agua y el ritmo que un río necesita para seguir vivo."}},"solucion":{}},{"slug":"agua-5.s4.p6","orden":6,"grupo":"agua-5.s4.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es el caudal ecológico de un río?","opciones":[{"id":"o1","texto":"El agua y el ritmo mínimos para que el río siga vivo"},{"id":"o2","texto":"La cantidad máxima de agua que se puede sacar sin permiso"},{"id":"o3","texto":"El agua que sobra después del riego y la energía"},{"id":"o4","texto":"El caudal de un río que no tiene ninguna represa"}]},"solucion":{"clave":["o1"],"explicacion":"Se reserva para el río antes de repartir. Si se calcula \"con lo que sobra\", en años secos no sobra nada.","por_opcion":{"o3":"Es al revés: se reserva antes de repartir el resto, no lo que sobra."}}},{"slug":"agua-5.s4.p7","orden":7,"grupo":"agua-5.s4.p7","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para cuidar un río alcanza con que nunca se seque del todo, aunque el caudal sea siempre el mismo.","razones":[{"id":"r1","texto":"Porque también importan las crecidas y bajantes naturales"},{"id":"r2","texto":"Porque los ríos no necesitan agua"},{"id":"r3","texto":"Porque las crecidas siempre son dañinas"}]},"solucion":{"valor":false,"explicacion":"Muchos ecosistemas dependen de la variación: las crecidas inundan humedales y disparan la reproducción de peces. Un caudal mínimo constante sin crecidas puede empobrecer el río.","clave":["r1"]}},{"slug":"agua-5.s4.p8","orden":8,"grupo":"agua-5.s4.p8","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Una provincia evalúa una represa. Ordená estas preguntas por importancia para decidir si conviene, empezando por la más de fondo.","items":[{"id":"i1","texto":"¿Hay otra forma de lograr lo mismo con menos daño?"},{"id":"i2","texto":"¿Qué ecosistemas y comunidades se inundan o se afectan?"},{"id":"i3","texto":"¿Cuánta energía o agua va a aportar?"},{"id":"i4","texto":"¿Qué color va a tener la represa?"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una evaluación seria arranca por las alternativas y los costos, no solo por los beneficios. Y hay preguntas que no importan.","valores":{"i1":"alternativas","i2":"costos","i3":"beneficios","i4":"irrelevante"}}},{"slug":"agua-5.s4.p9","orden":9,"grupo":"agua-5.s4.p9","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema de una represa con una medida que lo reduce.","izquierda":[{"id":"a1","texto":"Peces migratorios cortados"},{"id":"a2","texto":"Sedimento retenido"},{"id":"a3","texto":"Río sin crecidas"},{"id":"a4","texto":"Comunidades desplazadas"}],"derecha":[{"id":"b1","texto":"Escaleras o ascensores para peces"},{"id":"b2","texto":"Descargas de fondo que liberan sedimento"},{"id":"b3","texto":"Liberar crecidas controladas en ciertas épocas"},{"id":"b4","texto":"Consulta previa y reubicación digna"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Muchos costos se pueden reducir, aunque no eliminar. Hay que diseñarlos desde el principio."}},{"slug":"agua-5.s4.p10","orden":10,"grupo":"agua-5.s4.p10","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería incluir una evaluación de impacto ambiental seria de una represa? Marcá todo.","opciones":[{"id":"o1","texto":"Estudios de los peces y humedales afectados"},{"id":"o2","texto":"Consulta a las comunidades de la zona"},{"id":"o3","texto":"Análisis de alternativas"},{"id":"o4","texto":"Plan de caudal ecológico"},{"id":"o5","texto":"Solo el costo de construcción"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La Ley General del Ambiente exige evaluar el impacto de obras que puedan degradar el ambiente, y la participación ciudadana es parte de eso."}},{"slug":"agua-5.s4.p11","orden":11,"grupo":"agua-5.s4.p11","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe de una empresa y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"La represa generará electricidad sin emisiones de combustión."},{"id":"s2","texto":"No afectará a ningún pez porque los peces se adaptan a los lagos."},{"id":"s3","texto":"El embalse inundará 20.000 hectáreas de monte."},{"id":"s4","texto":"El caudal ecológico será lo que sobre después de producir energía."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los dos errores son clásicos: suponer que la naturaleza \"se adapta\" y tratar al río como el último de la fila.","por_opcion":{"s2":"Muchas especies migratorias necesitan el río libre para reproducirse.","s4":"El caudal ecológico se reserva primero, no con lo que sobra."}}},{"slug":"agua-5.s4.p12","orden":12,"grupo":"agua-5.s4.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una represa da energía y guarda agua, pero retiene {{0}}, corta el paso de {{1}} y cambia el {{2}} del río.","banco":[{"id":"w1","texto":"sedimentos"},{"id":"w2","texto":"peces"},{"id":"w3","texto":"caudal"},{"id":"w4","texto":"nubes"},{"id":"w5","texto":"barcos"},{"id":"w6","texto":"color"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres costos típicos que hay que poner en la balanza."}},{"slug":"agua-5.s4.p13","orden":13,"grupo":"agua-5.s4.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una regla simple fija el caudal ecológico como un porcentaje del caudal medio. Si un río tiene un caudal medio de 500 m³/s y la regla exige dejar pasar el 20 %, ¿cuántos m³/s tiene que soltar la represa como mínimo?","unidad":"m³/s","decimales":0,"contexto":"Caudal medio de 500 m³/s; 20 % como mínimo."},"solucion":{"valor":100,"tolerancia":2,"explicacion":"500 × 20 % = 100 m³/s. Es un mínimo: los ecosistemas también necesitan que el caudal varíe, con crecidas y bajantes."}},{"slug":"agua-5.s4.p13.v2","orden":13,"grupo":"agua-5.s4.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una regla simple fija el caudal ecológico como un porcentaje del caudal medio. Si un río tiene un caudal medio de 1.200 m³/s y la regla exige dejar pasar el 20 %, ¿cuántos m³/s tiene que soltar la represa como mínimo?","unidad":"m³/s","decimales":0,"contexto":"Caudal medio de 1200 m³/s; 20 % como mínimo."},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"1.200 × 20 % = 240 m³/s. Es un mínimo: los ecosistemas también necesitan que el caudal varíe, con crecidas y bajantes."}},{"slug":"agua-5.s4.p13.v3","orden":13,"grupo":"agua-5.s4.p13","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una regla simple fija el caudal ecológico como un porcentaje del caudal medio. Si un río tiene un caudal medio de 80 m³/s y la regla exige dejar pasar el 30 %, ¿cuántos m³/s tiene que soltar la represa como mínimo?","unidad":"m³/s","decimales":0,"contexto":"Caudal medio de 80 m³/s; 30 % como mínimo."},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"80 × 30 % = 24 m³/s. Es un mínimo: los ecosistemas también necesitan que el caudal varíe, con crecidas y bajantes."}}]},{"slug":"agua-5.s5","orden":5,"tipo":"leccion","titulo_es":"Repartir el agua","bajada_es":"Ciudades, campos, industrias y ríos: cómo se decide quién usa el agua cuando no alcanza para todos.","minutos":12,"pasos":[{"slug":"agua-5.s5.p1","orden":1,"grupo":"agua-5.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Usos que compiten","cuerpo":["El agua de una cuenca la usan muchos a la vez: el consumo humano, el riego, la ganadería, la industria, la energía, el turismo y el propio río. En años de abundancia alcanza para todos; en años secos, aparecen los conflictos.","A nivel mundial, la agricultura es el mayor usuario de agua dulce extraída: alrededor del 70 %, según Naciones Unidas. En zonas de riego como Cuyo, esa proporción puede ser aún mayor."],"destacado":{"valor":"≈ 70 %","texto":"del agua dulce extraída en el mundo se usa en la agricultura, según Naciones Unidas."}},"solucion":{}},{"slug":"agua-5.s5.p2","orden":2,"grupo":"agua-5.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"A nivel mundial, ¿qué actividad extrae más agua dulce?","opciones":[{"id":"o1","texto":"La agricultura, sobre todo el riego"},{"id":"o2","texto":"El consumo de agua en las casas"},{"id":"o3","texto":"La industria de bebidas"},{"id":"o4","texto":"Las piletas de natación de los clubes"}]},"solucion":{"clave":["o1"],"explicacion":"Por eso las mejoras en riego (goteo, horarios, cultivos adecuados) mueven mucho más agua que cualquier ahorro doméstico en la escala de una cuenca.","por_opcion":{"o3":"La industria usa mucha agua, pero la agricultura la supera ampliamente a nivel mundial."}}},{"slug":"agua-5.s5.p3","orden":3,"grupo":"agua-5.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prioridades","cuerpo":["En la mayoría de las legislaciones, el consumo humano tiene prioridad sobre los demás usos: primero el agua para que la gente viva. Después se ordenan los otros según cada provincia, que en Argentina es la que tiene el dominio originario de sus recursos naturales, incluida el agua.","Cuando un río cruza varias provincias, las decisiones de una afectan a las otras, y hacen falta acuerdos. Si no los hay, a veces el conflicto llega a la Justicia."]},"solucion":{}},{"slug":"agua-5.s5.p4","orden":4,"grupo":"agua-5.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso del río Atuel","cuerpo":["El río Atuel nace en Mendoza y, históricamente, llegaba a La Pampa. Durante décadas, el uso del agua para riego y energía en Mendoza dejó el tramo pampeano seco la mayor parte del tiempo, afectando humedales y comunidades del oeste de La Pampa.","La Pampa llevó el conflicto a la Corte Suprema, que en 2017 ordenó a las provincias acordar un caudal mínimo para que el río vuelva a llegar a La Pampa, con participación del Estado nacional. Es un caso de estudio sobre ríos compartidos y caudal ecológico."]},"solucion":{}},{"slug":"agua-5.s5.p5","orden":5,"grupo":"agua-5.s5.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los hechos del conflicto por el Atuel.","items":[{"id":"i1","texto":"El río llega de Mendoza a La Pampa"},{"id":"i2","texto":"Mendoza intensifica el uso para riego y energía"},{"id":"i3","texto":"El tramo pampeano queda seco la mayor parte del tiempo"},{"id":"i4","texto":"La Pampa acude a la Corte Suprema"},{"id":"i5","texto":"La Corte ordena acordar un caudal mínimo"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un conflicto de cuenca clásico: uso aguas arriba, daño aguas abajo, y la Justicia pidiendo un acuerdo."}},{"slug":"agua-5.s5.p6","orden":6,"grupo":"agua-5.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"En un río compartido, la provincia de aguas arriba puede usar toda el agua que quiera porque el río nace en su territorio.","razones":[{"id":"r1","texto":"Porque un río compartido obliga a considerar a quienes están aguas abajo"},{"id":"r2","texto":"Porque el agua es de quien la ve primero"},{"id":"r3","texto":"Porque los ríos no cruzan provincias"}]},"solucion":{"valor":false,"explicacion":"Un río interprovincial es un recurso compartido: el uso aguas arriba no puede dejar sin agua a quienes están aguas abajo. Por eso la Corte ordenó acordar un caudal para el Atuel.","clave":["r1"]}},{"slug":"agua-5.s5.p7","orden":7,"grupo":"agua-5.s5.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué medida ayuda a repartir mejor el agua de una cuenca en un año seco?","grupos":[{"id":"g1","nombre":"Ayuda a repartir mejor"},{"id":"g2","nombre":"Empeora el reparto"}],"items":[{"id":"i1","texto":"Pasar riego por inundación a riego por goteo"},{"id":"i2","texto":"Que cada usuario perfore más pozos sin control"},{"id":"i3","texto":"Reparar pérdidas en los canales"},{"id":"i4","texto":"Ocultar cuánta agua se saca"},{"id":"i5","texto":"Acordar entre usuarios turnos y prioridades"},{"id":"i6","texto":"Ignorar el caudal ecológico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Eficiencia, transparencia y acuerdos: las tres patas de una buena gestión del agua en escasez."}},{"slug":"agua-5.s5.p8","orden":8,"grupo":"agua-5.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Participar en la gestión","cuerpo":["Muchas cuencas tienen comités u organismos donde participan gobiernos, usuarios y a veces la sociedad civil. Las leyes argentinas prevén instancias de participación, como audiencias públicas antes de grandes obras, y el acceso a la información ambiental.","Saber quién decide sobre el agua de tu región, y cómo se puede participar, es tan importante como cuidarla en casa. Lo vas a profundizar en la rama de Comunidad."]},"solucion":{}},{"slug":"agua-5.s5.p9","orden":9,"grupo":"agua-5.s5.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué acciones permiten participar en decisiones sobre el agua? Marcá todas.","opciones":[{"id":"o1","texto":"Pedir información pública sobre cuánta agua se extrae"},{"id":"o2","texto":"Participar de una audiencia pública antes de una obra"},{"id":"o3","texto":"Sumarse a una organización de la cuenca"},{"id":"o4","texto":"Esperar a que el río se seque para opinar"},{"id":"o5","texto":"Opinar sin haber leído ningún dato"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Información, participación formal y organización colectiva: tres caminos concretos."}},{"slug":"agua-5.s5.p10","orden":10,"grupo":"agua-5.s5.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuenca se extraen 100 millones de m³ por año, de los cuales 70 son para riego. Si el riego se vuelve un 20 % más eficiente, ¿cuántos millones de m³ quedan libres para otros usos o para el río?","unidad":"millones de m³","decimales":1},"solucion":{"valor":14,"tolerancia":0.28,"explicacion":"20 % de 70 = 70 × 20 ÷ 100 = 14 millones de m³. Por el tamaño del riego, una mejora modesta libera muchísima agua."}},{"slug":"agua-5.s5.p10.v2","orden":10,"grupo":"agua-5.s5.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuenca se extraen 80 millones de m³ por año, de los cuales 60 son para riego. Si el riego se vuelve un 25 % más eficiente, ¿cuántos millones de m³ quedan libres para otros usos o para el río?","unidad":"millones de m³","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"25 % de 60 = 60 × 25 ÷ 100 = 15 millones de m³. Por el tamaño del riego, una mejora modesta libera muchísima agua."}},{"slug":"agua-5.s5.p10.v3","orden":10,"grupo":"agua-5.s5.p10","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una cuenca se extraen 150 millones de m³ por año, de los cuales 105 son para riego. Si el riego se vuelve un 30 % más eficiente, ¿cuántos millones de m³ quedan libres para otros usos o para el río?","unidad":"millones de m³","decimales":1},"solucion":{"valor":31.5,"tolerancia":0.63,"explicacion":"30 % de 105 = 105 × 30 ÷ 100 = 31,5 millones de m³. Por el tamaño del riego, una mejora modesta libera muchísima agua."}},{"slug":"agua-5.s5.p11","orden":11,"grupo":"agua-5.s5.p11","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario en un debate y marcá los errores.","segmentos":[{"id":"s1","texto":"En la mayoría de las leyes, el consumo humano tiene prioridad."},{"id":"s2","texto":"Como el riego usa tanta agua, ahorrar en casa no sirve para nada."},{"id":"s3","texto":"La Corte Suprema ordenó acordar un caudal mínimo para el Atuel."},{"id":"s4","texto":"Un río que nace en una provincia es propiedad exclusiva de esa provincia, aunque siga hacia otra."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Escalas que se complementan y ríos que se comparten: las dos ideas que ordenan cualquier debate sobre el agua.","por_opcion":{"s2":"En casa se ahorra agua potable, que cuesta tratar y distribuir; además, es parte de la cultura de cuidado. Las dos escalas importan.","s4":"Un río interprovincial es un recurso compartido."}}},{"slug":"agua-5.s5.p12","orden":12,"grupo":"agua-5.s5.p12","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada usuario del agua con una forma de usarla mejor.","izquierda":[{"id":"a1","texto":"Agricultura"},{"id":"a2","texto":"Ciudades"},{"id":"a3","texto":"Industria"},{"id":"a4","texto":"El propio río"}],"derecha":[{"id":"b1","texto":"Riego por goteo y cultivos adaptados"},{"id":"b2","texto":"Reducir pérdidas en la red"},{"id":"b3","texto":"Reciclar el agua dentro de la planta"},{"id":"b4","texto":"Garantizar su caudal ecológico"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada usuario tiene su palanca de eficiencia. El río también es un \"usuario\" con derechos en la cuenca."}},{"slug":"agua-5.s5.p13","orden":13,"grupo":"agua-5.s5.p13","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una sequía convierte un reparto tranquilo en un conflicto.","items":[{"id":"i1","texto":"Llueve mucho menos que lo normal en la cuenca"},{"id":"i2","texto":"El caudal del río baja"},{"id":"i3","texto":"El agua ya no alcanza para todos los usos de siempre"},{"id":"i4","texto":"Cada usuario presiona por su parte"},{"id":"i5","texto":"Sin reglas claras, aparece el conflicto"},{"id":"i6","texto":"La sequía hace que el río lleve más agua"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso las reglas de reparto se acuerdan en años normales, antes de que llegue la sequía."}},{"slug":"agua-5.s5.p14","orden":14,"grupo":"agua-5.s5.p14","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Este uso consume el agua o la devuelve casi toda al río?","grupos":[{"id":"g1","nombre":"La consume"},{"id":"g2","nombre":"La devuelve casi toda"}],"items":[{"id":"i1","texto":"El riego que evaporan los cultivos"},{"id":"i2","texto":"Una central hidroeléctrica"},{"id":"i3","texto":"El agua que se envasa y se lleva a otra región"},{"id":"i4","texto":"El agua de refrigeración que se devuelve al río"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Para repartir el agua importa cuánto se extrae y también cuánto vuelve al río después de usarse."}}]},{"slug":"agua-5.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: cuencas, humedales e inundaciones","bajada_es":"Cuencas, humedales, ciudades, represas y reparto del agua, mezclados.","minutos":8,"pasos":[{"slug":"agua-5.s6.p1","orden":1,"grupo":"agua-5.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Cuencas, humedales e inundaciones». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"agua-5.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el loteo en el bañado","bajada_es":"Un municipio tiene que decidir sobre un barrio nuevo en un humedal. Evaluá con datos.","minutos":10,"pasos":[{"slug":"agua-5.s7.p1","orden":1,"grupo":"agua-5.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["Un municipio del delta bonaerense recibe un pedido para construir un barrio de 300 casas sobre un bañado de 150 hectáreas que se inunda en las crecidas del río. El proyecto prevé rellenar el terreno 2 metros y hacer una laguna decorativa. Río abajo hay un pueblo que en la última crecida tuvo agua en las calles.","La empresa dice que el barrio \"no afectará a nadie\". Una organización vecinal pide que se evalúe el impacto. Te toca analizar."]},"solucion":{}},{"slug":"agua-5.s7.p2","orden":2,"grupo":"agua-5.s7.p2","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué función del bañado se pierde más directamente si se lo rellena?","opciones":[{"id":"o1","texto":"Absorber y retener agua en las crecidas"},{"id":"o2","texto":"Producir lluvia para la región"},{"id":"o3","texto":"Aportar agua potable a las canillas del pueblo"},{"id":"o4","texto":"Bajar la temperatura del río en invierno"}],"contexto":"Bañado de 150 ha que se inunda en las crecidas; se propone rellenarlo 2 m para 300 casas; río abajo hay un pueblo que ya se inundó."},"solucion":{"clave":["o1"],"explicacion":"Un relleno de 2 metros elimina el volumen donde el agua de la crecida se guardaba. Esa agua va a ir a otro lado.","por_opcion":{"o3":"Puede recargar acuíferos, pero lo más directo y medible es la pérdida de la capacidad de absorber crecidas."}}},{"slug":"agua-5.s7.p3","orden":3,"grupo":"agua-5.s7.p3","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si en una crecida el bañado guarda una lámina de agua de 0,5 m sobre sus 150 hectáreas, ¿cuántos millones de litros guarda? (1 ha = 10.000 m²)","unidad":"millones de litros","decimales":0,"contexto":"Bañado de 150 hectáreas; en una crecida guarda una lámina de 0,5 m de agua."},"solucion":{"valor":750,"tolerancia":15,"explicacion":"150 ha = 1.500.000 m². × 0,5 m = 750.000 m³. Como cada m³ son 1.000 litros, son 750.000.000 litros: 750 millones de litros que el relleno mandaría a otro lado."}},{"slug":"agua-5.s7.p4","orden":4,"grupo":"agua-5.s7.p4","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de efectos del relleno sobre el pueblo de río abajo.","items":[{"id":"i1","texto":"Se rellena el bañado 2 metros"},{"id":"i2","texto":"El agua de la crecida pierde su lugar"},{"id":"i3","texto":"Escurre hacia los terrenos vecinos y río abajo"},{"id":"i4","texto":"El pico de la crecida en el pueblo es más alto"},{"id":"i5","texto":"El pueblo se inunda más y más seguido"},{"id":"i6","texto":"La laguna decorativa absorbe toda la crecida"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una laguna decorativa es chica comparada con el volumen del bañado, y suele estar llena. No compensa lo perdido."}},{"slug":"agua-5.s7.p5","orden":5,"grupo":"agua-5.s7.p5","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá los argumentos que aparecen en el debate.","grupos":[{"id":"g1","nombre":"Basado en evidencia"},{"id":"g2","nombre":"Sin evidencia o engañoso"}],"items":[{"id":"i1","texto":"El bañado guardó cientos de millones de litros en la última crecida"},{"id":"i2","texto":"\"El barrio no afectará a nadie\""},{"id":"i3","texto":"El pueblo de río abajo ya se inundó con el bañado intacto"},{"id":"i4","texto":"\"El humedal es un terreno improductivo\""},{"id":"i5","texto":"La zona figura como inundable en los mapas de riesgo"},{"id":"i6","texto":"\"La laguna decorativa resuelve el problema\""}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"En un debate ambiental, pedir datos y separar evidencia de slogans es la tarea principal."}},{"slug":"agua-5.s7.p6","orden":6,"grupo":"agua-5.s7.p6","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué debería pedir el municipio antes de decidir? Marcá todo lo razonable.","opciones":[{"id":"o1","texto":"Un estudio hidrológico del efecto del relleno río abajo"},{"id":"o2","texto":"Una evaluación de impacto ambiental con audiencia pública"},{"id":"o3","texto":"Alternativas de ubicación fuera del humedal"},{"id":"o4","texto":"La promesa verbal de la empresa de que no habrá problemas"},{"id":"o5","texto":"Aprobar primero y estudiar después"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Estudios, participación y alternativas antes de decidir. Evaluar después de aprobar no es evaluar."}},{"slug":"agua-5.s7.p7","orden":7,"grupo":"agua-5.s7.p7","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las opciones del municipio según cuánto protegen al pueblo de río abajo, de más a menos.","items":[{"id":"i1","texto":"Rechazar el relleno y proteger el bañado"},{"id":"i2","texto":"Aprobar un barrio chico en la parte alta, sin relleno del bañado"},{"id":"i3","texto":"Aprobar con relleno parcial y obras de compensación"},{"id":"i4","texto":"Aprobar el proyecto tal como está"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Hay opciones intermedias, y todas se pueden discutir. Lo importante es saber qué se pierde con cada una.","valores":{"i1":"mantiene toda su capacidad","i2":"mantiene casi toda","i3":"pierde parte, compensa algo","i4":"pierde toda la capacidad"}}},{"slug":"agua-5.s7.p8","orden":8,"grupo":"agua-5.s7.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el bañado está seco la mayor parte del año, rellenarlo no cambia nada en las crecidas.","razones":[{"id":"r1","texto":"Porque su función se activa en las crecidas, aunque el resto del año esté seco"},{"id":"r2","texto":"Porque un bañado seco no puede volver a inundarse"},{"id":"r3","texto":"Porque las crecidas no llegan a los bañados"}]},"solucion":{"valor":false,"explicacion":"Su valor está justamente en los momentos de crecida: ahí guarda cientos de millones de litros. Estar seco el resto del año es parte de su ciclo, no una prueba de que sobra.","clave":["r1"]}},{"slug":"agua-5.s7.p9","orden":9,"grupo":"agua-5.s7.p9","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El diario local publica un resumen. Marcá los errores.","segmentos":[{"id":"s1","texto":"El bañado de 150 hectáreas guardó cientos de millones de litros en la última crecida."},{"id":"s2","texto":"El relleno solo afectaría al terreno del barrio, sin efectos afuera."},{"id":"s3","texto":"Los vecinos pidieron una evaluación de impacto con audiencia pública."},{"id":"s4","texto":"La laguna decorativa guardará más agua que el bañado original."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El agua no desaparece por decreto: si se le quita el lugar, lo busca en otro lado.","por_opcion":{"s2":"El agua que pierde su lugar escurre hacia los vecinos y río abajo.","s4":"Una laguna chica y llena no reemplaza el volumen de un bañado de 150 hectáreas."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"agua-6","rama":"agua","orden":6,"nivel":3,"titulo_es":"Agua y futuro","bajada_es":"Napas que bajan, arsénico, glaciares que retroceden, sequías y nuevas fuentes: los desafíos del agua que vienen y cómo prepararse.","objetivos_es":["Explicar cómo se recargan y se sobreexplotan los acuíferos","Reconocer los riesgos del arsénico y los nitratos en el agua subterránea","Describir el valor de los glaciares y qué protege la Ley 26.639","Distinguir tipos de sequía y cómo el cambio climático cambia los extremos","Comparar nuevas fuentes de agua según su costo, energía e impacto"],"repasa":["agua-5","agua-1","tronco-1","tronco-2"],"requiere_tronco":3,"fuentes":["acuifero-puelche","nitratos-puelche","oms-agua-potable","ley-26639-glaciares","inventario-glaciares","ipcc-ar6","un-water","unep"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"agua-6.s1","orden":1,"tipo":"leccion","titulo_es":"Las napas bajo presión","bajada_es":"Recarga, extracción y el agua que tarda siglos en volver: cómo se agota un acuífero sin que nadie lo vea.","minutos":11,"pasos":[{"slug":"agua-6.s1.p1","orden":1,"grupo":"agua-6.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una cuenta bajo tierra","cuerpo":["Un acuífero se recarga con la lluvia que se infiltra y con el agua de ríos y lagunas que se filtra hacia abajo. Se descarga por manantiales, por los ríos que alimenta y por los pozos que lo bombean.","Si durante años se bombea más de lo que se recarga, el nivel de la napa baja. Como no se ve, el problema suele notarse tarde: cuando los pozos se secan, hay que perforar más hondo o el agua empieza a salir de peor calidad."]},"solucion":{}},{"slug":"agua-6.s1.p2","orden":2,"grupo":"agua-6.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué recarga un acuífero?","opciones":[{"id":"o1","texto":"La lluvia que se infiltra en el suelo"},{"id":"o2","texto":"El agua que se bombea desde los pozos"},{"id":"o3","texto":"El vapor de agua del aire que baja por las noches"},{"id":"o4","texto":"La sal que trae el mar hacia la costa"}]},"solucion":{"clave":["o1"],"explicacion":"La infiltración es la entrada principal. Por eso impermeabilizar el suelo, además de inundar, recarga menos las napas.","por_opcion":{"o3":"La humedad del aire no recarga acuíferos de forma relevante: la recarga es por infiltración."}}},{"slug":"agua-6.s1.p3","orden":3,"grupo":"agua-6.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El cono alrededor del pozo","cuerpo":["Cuando un pozo bombea mucho, alrededor de él la napa baja formando una especie de embudo: el cono de depresión. Si hay muchos pozos juntos, los conos se suman y la napa baja en toda la zona.","Cerca de la costa, bajar la napa dulce puede dejar entrar agua salada del mar por debajo: la intrusión salina. Una vez que el acuífero se saliniza, recuperarlo lleva muchísimo tiempo."]},"solucion":{}},{"slug":"agua-6.s1.p4","orden":4,"grupo":"agua-6.s1.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de la intrusión salina en una ciudad costera.","items":[{"id":"i1","texto":"La ciudad bombea cada vez más agua de la napa"},{"id":"i2","texto":"El nivel del agua dulce baja"},{"id":"i3","texto":"El agua salada del mar avanza por debajo"},{"id":"i4","texto":"Los pozos cercanos a la costa empiezan a dar agua salobre"},{"id":"i5","texto":"La lluvia sala el acuífero"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La presión del agua dulce frena al mar. Si esa presión baja, el mar avanza."}},{"slug":"agua-6.s1.p5","orden":5,"grupo":"agua-6.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Agua vieja","cuerpo":["No todas las aguas se renuevan al mismo ritmo. El agua de un río se renueva en días o semanas; la de un lago, en años; la de un acuífero poco profundo, en años o décadas; y la de un acuífero profundo puede tener siglos o miles de años.","Sacar agua de un acuífero muy profundo es, en la práctica, usar un recurso que no se repone en escala humana: se parece más al petróleo que a la lluvia."]},"solucion":{}},{"slug":"agua-6.s1.p6","orden":6,"grupo":"agua-6.s1.p6","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos depósitos por cuánto tarda en renovarse su agua, de más rápido a más lento.","items":[{"id":"i1","texto":"Un río"},{"id":"i2","texto":"Un lago grande"},{"id":"i3","texto":"Un acuífero poco profundo"},{"id":"i4","texto":"Un acuífero profundo"}],"extremos":["Más rápido","Más lento"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto más lento se renueva, más cuidado hay que tener: lo que se saca de más no vuelve pronto.","valores":{"i1":"días a semanas","i2":"años","i3":"años a décadas","i4":"siglos o milenios"}}},{"slug":"agua-6.s1.p7","orden":7,"grupo":"agua-6.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un acuífero recibe 40 millones de m³ por año de recarga y se le extraen 55. ¿Cuántos millones de m³ pierde por año?","unidad":"millones de m³ por año","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"Entra 40, sale 55: pierde 55 − 40 = 15 millones de m³ por año. Es la cuenta de uso contra reposición del tronco, bajo tierra."}},{"slug":"agua-6.s1.p7.v2","orden":7,"grupo":"agua-6.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un acuífero recibe 25 millones de m³ por año de recarga y se le extraen 35. ¿Cuántos millones de m³ pierde por año?","unidad":"millones de m³ por año","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"Entra 25, sale 35: pierde 35 − 25 = 10 millones de m³ por año. Es la cuenta de uso contra reposición del tronco, bajo tierra."}},{"slug":"agua-6.s1.p7.v3","orden":7,"grupo":"agua-6.s1.p7","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un acuífero recibe 60 millones de m³ por año de recarga y se le extraen 90. ¿Cuántos millones de m³ pierde por año?","unidad":"millones de m³ por año","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"Entra 60, sale 90: pierde 90 − 60 = 30 millones de m³ por año. Es la cuenta de uso contra reposición del tronco, bajo tierra."}},{"slug":"agua-6.s1.p8","orden":8,"grupo":"agua-6.s1.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como el agua subterránea no se ve, bombearla no afecta a ríos ni humedales.","razones":[{"id":"r1","texto":"Porque muchos ríos y humedales se alimentan de la napa"},{"id":"r2","texto":"Porque el agua subterránea no está conectada con nada"},{"id":"r3","texto":"Porque bombear una napa agrega agua a los ríos"}]},"solucion":{"valor":false,"explicacion":"Muchos ríos y humedales se alimentan de la napa. Si la napa baja, esos ríos pueden perder caudal y los humedales secarse, aunque nadie les haya sacado agua directamente.","clave":["r1"]}},{"slug":"agua-6.s1.p9","orden":9,"grupo":"agua-6.s1.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción aumenta la recarga del acuífero o aumenta su extracción?","grupos":[{"id":"g1","nombre":"Aumenta la recarga"},{"id":"g2","nombre":"Aumenta la extracción"}],"items":[{"id":"i1","texto":"Conservar humedales y suelo permeable"},{"id":"i2","texto":"Perforar más pozos para riego"},{"id":"i3","texto":"Jardines de lluvia y veredas absorbentes"},{"id":"i4","texto":"Una ciudad que crece sin red de agua superficial"},{"id":"i5","texto":"Recarga artificial con agua de lluvia filtrada"},{"id":"i6","texto":"Industrias que bombean sin medir"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La gestión de un acuífero trabaja las dos columnas: sumar recarga y controlar la extracción."}},{"slug":"agua-6.s1.p10","orden":10,"grupo":"agua-6.s1.p10","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema de un acuífero con su causa.","izquierda":[{"id":"a1","texto":"Pozos que se secan"},{"id":"a2","texto":"Agua salobre cerca de la costa"},{"id":"a3","texto":"Humedal que se seca sin obras cercanas"},{"id":"a4","texto":"Nitratos en el agua de los pozos"}],"derecha":[{"id":"b1","texto":"Extracción mayor que la recarga"},{"id":"b2","texto":"Intrusión salina por bombeo excesivo"},{"id":"b3","texto":"Descenso de la napa que lo alimentaba"},{"id":"b4","texto":"Fertilizantes y pozos ciegos que se infiltran"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada síntoma señala una causa. El último es de calidad, no de cantidad: lo verás en la próxima sesión."}},{"slug":"agua-6.s1.p11","orden":11,"grupo":"agua-6.s1.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace falta para gestionar bien un acuífero? Marcá todo lo necesario.","opciones":[{"id":"o1","texto":"Medir el nivel de la napa en pozos de control"},{"id":"o2","texto":"Registrar cuántos pozos hay y cuánto extraen"},{"id":"o3","texto":"Proteger las zonas donde se recarga"},{"id":"o4","texto":"Perforar más hondo cada vez que un pozo se seca"},{"id":"o5","texto":"Suponer que la lluvia siempre alcanza"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Sin medir no se puede gestionar. Perforar más hondo es solo patear el problema hacia adelante."}},{"slug":"agua-6.s1.p12","orden":12,"grupo":"agua-6.s1.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Si durante años se bombea más de lo que se {{0}}, la napa {{1}}; cerca de la costa, puede entrar agua {{2}}.","banco":[{"id":"w1","texto":"recarga"},{"id":"w2","texto":"baja"},{"id":"w3","texto":"salada"},{"id":"w4","texto":"evapora"},{"id":"w5","texto":"sube"},{"id":"w6","texto":"dulce"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Recarga contra extracción, y el mar esperando del otro lado."}},{"slug":"agua-6.s1.p13","orden":13,"grupo":"agua-6.s1.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario de un productor y marcá los errores.","segmentos":[{"id":"s1","texto":"Mi pozo baja un metro por año desde hace diez años."},{"id":"s2","texto":"No hay problema: el acuífero es infinito porque llueve todos los años."},{"id":"s3","texto":"Voy a instalar un medidor para saber cuánto saco."},{"id":"s4","texto":"Si se seca, perforo más hondo y listo, el agua de abajo es igual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una napa que baja todos los años es una señal de sobreexplotación, no de mala suerte.","por_opcion":{"s2":"La lluvia recarga, pero si se saca más de lo que entra, el nivel baja.","s4":"El agua profunda suele renovarse mucho más lento y puede tener otra calidad."}}}]},{"slug":"agua-6.s2","orden":2,"tipo":"leccion","titulo_es":"Arsénico y nitratos","bajada_es":"Dos contaminantes del agua subterránea, uno natural y otro humano, y cómo se enfrentan.","minutos":11,"pasos":[{"slug":"agua-6.s2.p1","orden":1,"grupo":"agua-6.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Arsénico: un problema natural","cuerpo":["En gran parte de la llanura chaco-pampeana, el agua subterránea tiene arsénico de origen natural, que viene de las cenizas volcánicas y los sedimentos del suelo. No se ve, no tiene olor ni gusto.","Tomar durante muchos años agua con arsénico por encima de los límites puede causar una enfermedad llamada HACRE (hidroarsenicismo crónico regional endémico), con lesiones en la piel y mayor riesgo de algunos cánceres. La Organización Mundial de la Salud recomienda un valor guía de 10 microgramos por litro."],"destacado":{"valor":"10 µg/L","texto":"es el valor guía de arsénico en agua de bebida que recomienda la OMS."}},"solucion":{}},{"slug":"agua-6.s2.p2","orden":2,"grupo":"agua-6.s2.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿De dónde viene el arsénico del agua subterránea de la llanura chaco-pampeana?","opciones":[{"id":"o1","texto":"De cenizas volcánicas y sedimentos naturales del suelo"},{"id":"o2","texto":"De los fertilizantes que se usan en los campos"},{"id":"o3","texto":"De los caños de plomo de las casas viejas"},{"id":"o4","texto":"De la sal que traen los ríos desde el mar"}]},"solucion":{"clave":["o1"],"explicacion":"Es un problema natural, no una contaminación humana. Por eso la solución no es \"dejar de contaminar\" sino tratar el agua.","por_opcion":{"o3":"Los caños viejos pueden aportar plomo, pero el arsénico de la región es de origen natural."}}},{"slug":"agua-6.s2.p3","orden":3,"grupo":"agua-6.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cómo se enfrenta","cuerpo":["El arsénico no se va hirviendo el agua: al contrario, hervirla concentra lo que queda. Se saca con tratamientos específicos, como la ósmosis inversa o procesos de coagulación y filtración con materiales que lo retienen.","Muchas localidades tienen plantas de abatimiento de arsénico. Donde no hay red, se usan equipos domiciliarios o comunitarios, y se recomienda usar agua tratada al menos para tomar y cocinar."]},"solucion":{}},{"slug":"agua-6.s2.p4","orden":4,"grupo":"agua-6.s2.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Hervir el agua elimina el arsénico.","razones":[{"id":"r1","texto":"Porque el arsénico no se evapora y queda más concentrado"},{"id":"r2","texto":"Porque el arsénico se evapora a 100 °C"},{"id":"r3","texto":"Porque el arsénico solo está en el hielo"}]},"solucion":{"valor":false,"explicacion":"Hervir elimina microbios, pero no el arsénico. Al evaporarse parte del agua, el arsénico que queda incluso se concentra. Hacen falta tratamientos específicos.","clave":["r1"]}},{"slug":"agua-6.s2.p5","orden":5,"grupo":"agua-6.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pozo tiene 50 µg/L de arsénico. ¿Cuántas veces supera el valor guía de la OMS (10 µg/L)?","unidad":"veces","decimales":1},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"50 ÷ 10 = 5 veces el valor guía. Esa agua necesita tratamiento para tomar y cocinar."}},{"slug":"agua-6.s2.p5.v2","orden":5,"grupo":"agua-6.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pozo tiene 30 µg/L de arsénico. ¿Cuántas veces supera el valor guía de la OMS (10 µg/L)?","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"30 ÷ 10 = 3 veces el valor guía. Esa agua necesita tratamiento para tomar y cocinar."}},{"slug":"agua-6.s2.p5.v3","orden":5,"grupo":"agua-6.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pozo tiene 120 µg/L de arsénico. ¿Cuántas veces supera el valor guía de la OMS (10 µg/L)?","unidad":"veces","decimales":1},"solucion":{"valor":12,"tolerancia":0.24,"explicacion":"120 ÷ 10 = 12 veces el valor guía. Esa agua necesita tratamiento para tomar y cocinar."}},{"slug":"agua-6.s2.p6","orden":6,"grupo":"agua-6.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Nitratos: un problema humano","cuerpo":["Los nitratos llegan a las napas desde los fertilizantes nitrogenados de los campos, los pozos ciegos y los corrales. En zonas del conurbano bonaerense y en áreas agrícolas intensivas, el acuífero Puelche y otros tienen sectores con nitratos altos.","La OMS recomienda que el agua de bebida no supere 50 miligramos de nitrato por litro. Los más sensibles son los bebés: el exceso puede afectar el transporte de oxígeno en la sangre. Por eso el agua para preparar mamaderas tiene que ser segura."],"destacado":{"valor":"50 mg/L","texto":"de nitrato es el valor guía de la OMS para el agua de bebida."}},"solucion":{}},{"slug":"agua-6.s2.p7","orden":7,"grupo":"agua-6.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿El origen de este contaminante es natural o humano?","grupos":[{"id":"g1","nombre":"Origen natural"},{"id":"g2","nombre":"Origen humano"}],"items":[{"id":"i1","texto":"Arsénico en la llanura chaco-pampeana"},{"id":"i2","texto":"Nitratos de fertilizantes"},{"id":"i3","texto":"Flúor en exceso en algunas napas"},{"id":"i4","texto":"Nitratos de pozos ciegos"},{"id":"i5","texto":"Restos de agroquímicos en la napa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"La diferencia importa: lo humano se puede prevenir en el origen; lo natural hay que tratarlo."}},{"slug":"agua-6.s2.p8","orden":8,"grupo":"agua-6.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el camino de los nitratos hasta la mamadera de un bebé.","items":[{"id":"i1","texto":"Se aplica más fertilizante del que el cultivo usa"},{"id":"i2","texto":"El sobrante se disuelve con la lluvia"},{"id":"i3","texto":"Se infiltra hasta la napa"},{"id":"i4","texto":"Un pozo familiar bombea esa agua"},{"id":"i5","texto":"Se usa para preparar la mamadera"},{"id":"i6","texto":"El fertilizante se evapora y llueve en otra provincia"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Por eso ajustar la dosis de fertilizante protege el agua de muchas familias que ni siquiera viven cerca del campo."}},{"slug":"agua-6.s2.p9","orden":9,"grupo":"agua-6.s2.p9","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada contaminante con quién es más sensible y qué conviene hacer.","izquierda":[{"id":"a1","texto":"Nitratos altos"},{"id":"a2","texto":"Arsénico alto"},{"id":"a3","texto":"Microbios"}],"derecha":[{"id":"b1","texto":"Bebés: usar agua segura para las mamaderas"},{"id":"b2","texto":"Toda la familia: agua tratada para tomar y cocinar"},{"id":"b3","texto":"Toda la familia: desinfectar o hervir"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Cada contaminante tiene su grupo más vulnerable y su tratamiento. Hervir sirve solo para uno de los tres."}},{"slug":"agua-6.s2.p10","orden":10,"grupo":"agua-6.s2.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué medidas reducen los nitratos que llegan a las napas? Marcá todas.","opciones":[{"id":"o1","texto":"Aplicar la dosis de fertilizante que el cultivo necesita"},{"id":"o2","texto":"Conectar las casas a la red cloacal"},{"id":"o3","texto":"Alejar los corrales y pozos ciegos de los pozos de agua"},{"id":"o4","texto":"Hervir el agua de los pozos"},{"id":"o5","texto":"Perforar el pozo más cerca del pozo ciego"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Prevenir en el origen: dosis justa, cloacas y distancias. Hervir no saca nitratos."}},{"slug":"agua-6.s2.p11","orden":11,"grupo":"agua-6.s2.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una casa rural el análisis del pozo da 80 mg/L de nitrato y nace un bebé. ¿Qué es lo más importante?","opciones":[{"id":"o1","texto":"Usar agua segura, de red o tratada, para las mamaderas"},{"id":"o2","texto":"Hervir más tiempo el agua del pozo"},{"id":"o3","texto":"Esperar a que el bebé crezca para cambiar el agua"},{"id":"o4","texto":"Agregarle cloro al agua del pozo"}]},"solucion":{"clave":["o1"],"explicacion":"El cloro y el hervor no sacan nitratos. Para el bebé, agua segura desde el primer día.","por_opcion":{"o3":"Los bebés son justamente los más sensibles: el cambio tiene que ser ya."}}},{"slug":"agua-6.s2.p12","orden":12,"grupo":"agua-6.s2.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pozo tiene 80 mg/L de nitrato. ¿En qué porcentaje supera el valor guía de la OMS (50 mg/L)?","unidad":"%","decimales":0},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"Excede 80 − 50 = 30 mg/L sobre 50: 30 ÷ 50 × 100 = 60 %. Porcentaje de exceso respecto del límite."}},{"slug":"agua-6.s2.p12.v2","orden":12,"grupo":"agua-6.s2.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pozo tiene 65 mg/L de nitrato. ¿En qué porcentaje supera el valor guía de la OMS (50 mg/L)?","unidad":"%","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"Excede 65 − 50 = 15 mg/L sobre 50: 15 ÷ 50 × 100 = 30 %. Porcentaje de exceso respecto del límite."}},{"slug":"agua-6.s2.p12.v3","orden":12,"grupo":"agua-6.s2.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un pozo tiene 120 mg/L de nitrato. ¿En qué porcentaje supera el valor guía de la OMS (50 mg/L)?","unidad":"%","decimales":0},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"Excede 120 − 50 = 70 mg/L sobre 50: 70 ÷ 50 × 100 = 140 %. Porcentaje de exceso respecto del límite."}},{"slug":"agua-6.s2.p13","orden":13,"grupo":"agua-6.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos de un folleto y marcá los equivocados.","segmentos":[{"id":"s1","texto":"El arsénico del agua de la región es de origen natural."},{"id":"s2","texto":"Si el agua es transparente y rica, seguro no tiene arsénico."},{"id":"s3","texto":"Para las mamaderas, usá agua segura."},{"id":"s4","texto":"Hervir el agua del pozo elimina el arsénico y los nitratos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo invisible solo se ve con un análisis, y hervir no es una solución universal.","por_opcion":{"s2":"El arsénico no tiene color, olor ni gusto: solo se detecta con un análisis.","s4":"Hervir no elimina ninguno de los dos, y concentra el arsénico."}}},{"slug":"agua-6.s2.p14","orden":14,"grupo":"agua-6.s2.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El {{0}} de la llanura es natural; los {{1}} vienen de fertilizantes y pozos ciegos; y {{2}} no elimina ninguno de los dos.","banco":[{"id":"w1","texto":"arsénico"},{"id":"w2","texto":"nitratos"},{"id":"w3","texto":"hervir"},{"id":"w4","texto":"cloro"},{"id":"w5","texto":"oxígeno"},{"id":"w6","texto":"filtrar con tela"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Dos contaminantes distintos, un error común compartido."}}]},{"slug":"agua-6.s3","orden":3,"tipo":"leccion","titulo_es":"Glaciares: reservas en retroceso","bajada_es":"El agua congelada de la cordillera, por qué retrocede y qué protege la ley de glaciares.","minutos":11,"pasos":[{"slug":"agua-6.s3.p1","orden":1,"grupo":"agua-6.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es un glaciar","cuerpo":["Un glaciar es una masa de hielo que se forma cuando la nieve se acumula año tras año, se compacta y fluye lentamente cuesta abajo. Además de los glaciares visibles, en la alta montaña hay ambiente periglacial: suelos congelados y glaciares de escombros, cubiertos de piedras, que también guardan hielo.","El Inventario Nacional de Glaciares de Argentina identificó más de 16.000 cuerpos de hielo a lo largo de la cordillera. En las provincias andinas secas, en los veranos y en los años de poca nieve, el deshielo de glaciares y del ambiente periglacial aporta una parte importante del agua de los ríos."],"destacado":{"valor":"+16.000","texto":"cuerpos de hielo identificó el Inventario Nacional de Glaciares en la cordillera argentina."}},"solucion":{}},{"slug":"agua-6.s3.p2","orden":2,"grupo":"agua-6.s3.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuándo es más importante el aporte de los glaciares a los ríos de cordillera?","opciones":[{"id":"o1","texto":"En veranos secos y en años de poca nieve"},{"id":"o2","texto":"En los inviernos con mucha nieve"},{"id":"o3","texto":"Cuando llueve mucho en la llanura"},{"id":"o4","texto":"Nunca, porque el hielo no se derrite"}]},"solucion":{"clave":["o1"],"explicacion":"Los glaciares funcionan como una reserva que se libera cuando más falta: en los veranos y en las sequías.","por_opcion":{"o3":"La lluvia en la llanura no depende de los glaciares: el aporte glaciar pesa cuando falta nieve en la montaña."}}},{"slug":"agua-6.s3.p3","orden":3,"grupo":"agua-6.s3.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es parte del ambiente glaciar o periglacial, o no?","grupos":[{"id":"g1","nombre":"Glaciar o periglacial"},{"id":"g2","nombre":"No lo es"}],"items":[{"id":"i1","texto":"Un glaciar de escombros cubierto de piedras"},{"id":"i2","texto":"La nieve de una sola temporada que se derrite en primavera"},{"id":"i3","texto":"Suelo congelado permanentemente en alta montaña"},{"id":"i4","texto":"Un lago de montaña sin hielo"},{"id":"i5","texto":"Un glaciar descubierto en un valle"},{"id":"i6","texto":"La helada de una mañana de invierno"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Lo que define al ambiente glaciar y periglacial es el hielo que dura años. La nieve estacional es otra cosa, aunque también aporta agua."}},{"slug":"agua-6.s3.p4","orden":4,"grupo":"agua-6.s3.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué retroceden","cuerpo":["Con el calentamiento global, la gran mayoría de los glaciares del mundo pierde masa: se derrite más hielo del que se acumula como nieve. En los Andes, muchos glaciares retrocedieron de forma notable en las últimas décadas.","Al principio, un glaciar que se derrite más rápido puede dar más agua a los ríos; pero cuando se achica lo suficiente, ese aporte empieza a bajar. Es una reserva que se está gastando."]},"solucion":{}},{"slug":"agua-6.s3.p5","orden":5,"grupo":"agua-6.s3.p5","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de lo que pasa con un río cuando su glaciar se achica.","items":[{"id":"i1","texto":"El clima se calienta en la cordillera"},{"id":"i2","texto":"El glaciar se derrite más de lo que acumula"},{"id":"i3","texto":"Por un tiempo, el río recibe más agua de deshielo"},{"id":"i4","texto":"El glaciar se achica"},{"id":"i5","texto":"El aporte al río en los veranos secos baja"},{"id":"i6","texto":"El glaciar crece con el calor"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es un efecto con retraso: primero parece que hay más agua, y después falta. Los retrasos del tronco otra vez."}},{"slug":"agua-6.s3.p6","orden":6,"grupo":"agua-6.s3.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un glaciar se derrite más rápido, los ríos van a tener más agua para siempre.","razones":[{"id":"r1","texto":"Porque es una reserva que se agota: después el aporte baja"},{"id":"r2","texto":"Porque los glaciares se regeneran solos en un verano"},{"id":"r3","texto":"Porque el deshielo no llega a los ríos"}]},"solucion":{"valor":false,"explicacion":"Hay más agua mientras el glaciar se está gastando, pero cuando se achica lo suficiente, el aporte baja. Es como gastar ahorros: un tiempo se tiene más, después menos.","clave":["r1"]}},{"slug":"agua-6.s3.p7","orden":7,"grupo":"agua-6.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La Ley de Glaciares","cuerpo":["En 2010 se sancionó la Ley 26.639, de presupuestos mínimos para la preservación de los glaciares y del ambiente periglacial. Los declara bienes de carácter público, reservas estratégicas de agua, y prohíbe en ellos actividades que puedan afectarlos, como la minería y la exploración petrolera, la construcción de obras que no sean científicas o de rescate y la liberación de contaminantes.","La ley creó también el Inventario Nacional de Glaciares, que realiza el IANIGLA (un instituto del CONICET), para saber dónde están y cómo cambian."]},"solucion":{}},{"slug":"agua-6.s3.p8","orden":8,"grupo":"agua-6.s3.p8","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué establece la Ley 26.639? Marcá lo que corresponde.","opciones":[{"id":"o1","texto":"Protege glaciares y ambiente periglacial como reservas de agua"},{"id":"o2","texto":"Prohíbe en ellos actividades como la minería"},{"id":"o3","texto":"Crea el Inventario Nacional de Glaciares"},{"id":"o4","texto":"Permite construir cualquier obra sobre los glaciares"},{"id":"o5","texto":"Protege solo los glaciares que se ven desde las rutas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La ley protege también el hielo que no se ve, como los glaciares de escombros, porque también es reserva de agua."}},{"slug":"agua-6.s3.p9","orden":9,"grupo":"agua-6.s3.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su descripción.","izquierda":[{"id":"a1","texto":"Glaciar de escombros"},{"id":"a2","texto":"Ambiente periglacial"},{"id":"a3","texto":"Inventario Nacional de Glaciares"},{"id":"a4","texto":"Reserva estratégica de agua"}],"derecha":[{"id":"b1","texto":"Hielo cubierto por piedras y detritos"},{"id":"b2","texto":"Suelos de alta montaña con hielo"},{"id":"b3","texto":"El registro de dónde están y cómo cambian"},{"id":"b4","texto":"Cómo los define la ley"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro conceptos que aparecen en cualquier debate sobre glaciares en Argentina."}},{"slug":"agua-6.s3.p10","orden":10,"grupo":"agua-6.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un glaciar tenía 120 hectáreas y hoy tiene 84. ¿Qué porcentaje de su superficie perdió?","unidad":"%","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"Perdió 120 − 84 = 36 ha de 120: 36 ÷ 120 × 100 = 30 %. Se divide por el tamaño original."}},{"slug":"agua-6.s3.p10.v2","orden":10,"grupo":"agua-6.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un glaciar tenía 80 hectáreas y hoy tiene 60. ¿Qué porcentaje de su superficie perdió?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"Perdió 80 − 60 = 20 ha de 80: 20 ÷ 80 × 100 = 25 %. Se divide por el tamaño original."}},{"slug":"agua-6.s3.p10.v3","orden":10,"grupo":"agua-6.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un glaciar tenía 200 hectáreas y hoy tiene 150. ¿Qué porcentaje de su superficie perdió?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"Perdió 200 − 150 = 50 ha de 200: 50 ÷ 200 × 100 = 25 %. Se divide por el tamaño original."}},{"slug":"agua-6.s3.p11","orden":11,"grupo":"agua-6.s3.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la ley protege también los glaciares de escombros, que parecen solo piedras?","opciones":[{"id":"o1","texto":"Porque bajo las piedras guardan hielo que aporta agua"},{"id":"o2","texto":"Porque las piedras son valiosas para la construcción"},{"id":"o3","texto":"Porque la ley protege todas las piedras de la cordillera"},{"id":"o4","texto":"Porque son lugares turísticos muy visitados"}]},"solucion":{"clave":["o1"],"explicacion":"En zonas muy secas, el hielo cubierto puede ser una reserva de agua tan importante como los glaciares descubiertos.","por_opcion":{"o3":"No protege cualquier piedra: protege el hielo, aunque esté cubierto."}}},{"slug":"agua-6.s3.p12","orden":12,"grupo":"agua-6.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Argentina tiene miles de glaciares a lo largo de la cordillera."},{"id":"s2","texto":"Como el hielo se derrite, es buena noticia: habrá más agua para siempre."},{"id":"s3","texto":"La Ley 26.639 prohíbe actividades como la minería sobre los glaciares."},{"id":"s4","texto":"El ambiente periglacial no tiene hielo, así que no importa."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El deshielo acelerado es una reserva que se gasta, y el hielo escondido también cuenta.","por_opcion":{"s2":"Más deshielo ahora significa menos reserva para después.","s4":"El ambiente periglacial tiene suelos congelados y glaciares de escombros con hielo."}}},{"slug":"agua-6.s3.p13","orden":13,"grupo":"agua-6.s3.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La Ley {{0}} protege los glaciares y el ambiente {{1}} como reservas estratégicas de {{2}}.","banco":[{"id":"w1","texto":"26.639"},{"id":"w2","texto":"periglacial"},{"id":"w3","texto":"agua"},{"id":"w4","texto":"25.675"},{"id":"w5","texto":"marino"},{"id":"w6","texto":"minerales"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Número, alcance y propósito de la ley, en una línea."}}]},{"slug":"agua-6.s4","orden":4,"tipo":"leccion","titulo_es":"Sequías y extremos","bajada_es":"Cuando falta la lluvia: tipos de sequía, la bajante del Paraná, la sequía de 2022-2023 y cómo prepararse.","minutos":12,"pasos":[{"slug":"agua-6.s4.p1","orden":1,"grupo":"agua-6.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No hay una sola sequía","cuerpo":["Se habla de sequía meteorológica cuando llueve bastante menos que lo normal durante un período. Si esa falta de lluvia seca el suelo y afecta a los cultivos, es sequía agrícola. Si baja el caudal de los ríos, los embalses y las napas, es sequía hidrológica. Y cuando afecta la economía y la vida de la gente, se habla de sequía socioeconómica.","Cada una llega con un retraso distinto: la lluvia falta primero, el suelo se seca después, y los ríos y las napas bajan más tarde."]},"solucion":{}},{"slug":"agua-6.s4.p2","orden":2,"grupo":"agua-6.s4.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo suele avanzar una sequía.","items":[{"id":"i1","texto":"Llueve menos de lo normal durante meses"},{"id":"i2","texto":"El suelo se seca y los cultivos sufren"},{"id":"i3","texto":"Bajan los ríos, los embalses y las napas"},{"id":"i4","texto":"Se afectan la economía y el abastecimiento"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Meteorológica, agrícola, hidrológica y socioeconómica: una cadena con retrasos."}},{"slug":"agua-6.s4.p3","orden":3,"grupo":"agua-6.s4.p3","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada tipo de sequía con su señal.","izquierda":[{"id":"a1","texto":"Meteorológica"},{"id":"a2","texto":"Agrícola"},{"id":"a3","texto":"Hidrológica"},{"id":"a4","texto":"Socioeconómica"}],"derecha":[{"id":"b1","texto":"Llueve mucho menos que el promedio"},{"id":"b2","texto":"El suelo no tiene humedad para los cultivos"},{"id":"b3","texto":"Los ríos y embalses bajan de nivel"},{"id":"b4","texto":"Faltan agua o cosechas y se afecta el trabajo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Distinguirlas ayuda a saber qué medir y qué hacer en cada etapa."}},{"slug":"agua-6.s4.p4","orden":4,"grupo":"agua-6.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La bajante del Paraná","cuerpo":["Entre 2019 y 2022 el río Paraná tuvo una bajante extraordinaria, con niveles que en 2021 fueron los más bajos en unos 77 años en Rosario. Se debió sobre todo a la falta de lluvias en su cuenca alta, en Brasil y Paraguay.","La bajante afectó la navegación de barcos, las tomas de agua de ciudades que tuvieron que adaptarlas, la pesca y los humedales del Delta, que se secaron y se volvieron más vulnerables a los incendios."]},"solucion":{}},{"slug":"agua-6.s4.p5","orden":5,"grupo":"agua-6.s4.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué efectos tuvo la bajante del Paraná? Marcá todos.","opciones":[{"id":"o1","texto":"Dificultades para la navegación de barcos"},{"id":"o2","texto":"Problemas en las tomas de agua de algunas ciudades"},{"id":"o3","texto":"Humedales del Delta más secos y vulnerables al fuego"},{"id":"o4","texto":"Más agua para el riego en la cuenca"},{"id":"o5","texto":"Inundaciones en Rosario"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Una sola causa —falta de lluvia río arriba— con efectos en transporte, abastecimiento, pesca y ecosistemas."}},{"slug":"agua-6.s4.p6","orden":6,"grupo":"agua-6.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La sequía de 2022-2023","cuerpo":["Entre 2022 y 2023, la región pampeana atravesó una de las sequías más graves de las últimas décadas, asociada a varios años seguidos del fenómeno La Niña, que suele traer menos lluvias a la región. Las cosechas de soja, maíz y trigo cayeron fuertemente y el impacto económico fue enorme.","Los científicos advierten que, con el cambio climático, en muchas regiones se esperan extremos más intensos: sequías más fuertes y también lluvias más torrenciales. Prepararse para los dos es parte de la gestión del agua."]},"solucion":{}},{"slug":"agua-6.s4.p7","orden":7,"grupo":"agua-6.s4.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una sequía en el campo llega a la economía de una ciudad.","items":[{"id":"i1","texto":"Llueve mucho menos durante meses"},{"id":"i2","texto":"Los cultivos rinden mucho menos"},{"id":"i3","texto":"Caen la cosecha y las exportaciones"},{"id":"i4","texto":"Baja la actividad de los pueblos y ciudades que dependen del campo"},{"id":"i5","texto":"Sube el caudal de los ríos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El agua que falta en el suelo termina faltando en la economía. Es la sequía socioeconómica."}},{"slug":"agua-6.s4.p8","orden":8,"grupo":"agua-6.s4.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El cambio climático solo trae sequías, nunca lluvias más intensas.","razones":[{"id":"r1","texto":"Porque se esperan extremos en los dos sentidos"},{"id":"r2","texto":"Porque el cambio climático no afecta las lluvias"},{"id":"r3","texto":"Porque solo cambia la temperatura del mar"}]},"solucion":{"valor":false,"explicacion":"En muchas regiones se esperan extremos en los dos sentidos: sequías más fuertes y lluvias más intensas, porque un aire más caliente carga más vapor de agua.","clave":["r1"]}},{"slug":"agua-6.s4.p9","orden":9,"grupo":"agua-6.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prepararse","cuerpo":["La gestión de sequías funciona mejor antes que durante: medir y pronosticar, tener reservas y planes de contingencia, reducir pérdidas en las redes para que cada litro rinda, diversificar las fuentes de agua y acordar reglas de reparto en años normales.","En el campo, prácticas como la siembra directa con cobertura, la rotación de cultivos y el cuidado de la materia orgánica del suelo ayudan a que el suelo retenga más agua."],"lista":["Pronóstico y alertas tempranas","Reservas y planes de contingencia","Menos pérdidas en redes","Fuentes diversas","Suelos que retienen agua"]},"solucion":{}},{"slug":"agua-6.s4.p10","orden":10,"grupo":"agua-6.s4.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta medida se toma antes de la sequía o durante la sequía?","grupos":[{"id":"g1","nombre":"Antes (preparación)"},{"id":"g2","nombre":"Durante (respuesta)"}],"items":[{"id":"i1","texto":"Reparar pérdidas de la red de agua"},{"id":"i2","texto":"Restringir el riego de jardines"},{"id":"i3","texto":"Acordar reglas de reparto entre usuarios"},{"id":"i4","texto":"Distribuir agua en camiones a zonas sin servicio"},{"id":"i5","texto":"Cuidar la materia orgánica del suelo"},{"id":"i6","texto":"Campañas para reducir el consumo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Las medidas de preparación son más baratas y efectivas. Las de respuesta hacen falta, pero llegan cuando el problema ya está."}},{"slug":"agua-6.s4.p11","orden":11,"grupo":"agua-6.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 900 millones de litros en su embalse y consume 30 millones por día, sin lluvia. ¿Para cuántos días le alcanza?","unidad":"días","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"900 ÷ 30 = 30 días de reserva, sin contar la evaporación ni las pérdidas. Por eso se miden los días de reserva en las sequías."}},{"slug":"agua-6.s4.p11.v2","orden":11,"grupo":"agua-6.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 600 millones de litros en su embalse y consume 25 millones por día, sin lluvia. ¿Para cuántos días le alcanza?","unidad":"días","decimales":0},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"600 ÷ 25 = 24 días de reserva, sin contar la evaporación ni las pérdidas. Por eso se miden los días de reserva en las sequías."}},{"slug":"agua-6.s4.p11.v3","orden":11,"grupo":"agua-6.s4.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 1.500 millones de litros en su embalse y consume 50 millones por día, sin lluvia. ¿Para cuántos días le alcanza?","unidad":"días","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"1.500 ÷ 50 = 30 días de reserva, sin contar la evaporación ni las pérdidas. Por eso se miden los días de reserva en las sequías."}},{"slug":"agua-6.s4.p12","orden":12,"grupo":"agua-6.s4.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad (reserva de 900 millones de litros, consumo de 30 millones por día) baja su consumo un 20 %, ¿cuántos días le alcanza ahora? Redondeá a un decimal.","unidad":"días","decimales":1},"solucion":{"valor":37.5,"tolerancia":0.2,"explicacion":"Nuevo consumo: 30 × 0,8 = 24 millones por día. 900 ÷ 24 ≈ 37,5 días: ahorrar compra tiempo."}},{"slug":"agua-6.s4.p12.v2","orden":12,"grupo":"agua-6.s4.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad (reserva de 600 millones de litros, consumo de 25 millones por día) baja su consumo un 20 %, ¿cuántos días le alcanza ahora? Redondeá a un decimal.","unidad":"días","decimales":1},"solucion":{"valor":30,"tolerancia":0.2,"explicacion":"Nuevo consumo: 25 × 0,8 = 20 millones por día. 600 ÷ 20 ≈ 30 días: ahorrar compra tiempo."}},{"slug":"agua-6.s4.p12.v3","orden":12,"grupo":"agua-6.s4.p12","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad (reserva de 1.500 millones de litros, consumo de 50 millones por día) baja su consumo un 30 %, ¿cuántos días le alcanza ahora? Redondeá a un decimal.","unidad":"días","decimales":1},"solucion":{"valor":42.9,"tolerancia":0.2,"explicacion":"Nuevo consumo: 50 × 0,7 = 35 millones por día. 1.500 ÷ 35 ≈ 42,9 días: ahorrar compra tiempo."}},{"slug":"agua-6.s4.p13","orden":13,"grupo":"agua-6.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario de un funcionario y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"La sequía de este año es muy fuerte."},{"id":"s2","texto":"Como las sequías son naturales, no hay nada que prepararse."},{"id":"s3","texto":"Vamos a arreglar las pérdidas de la red para que rinda cada litro."},{"id":"s4","texto":"Las pérdidas las arreglamos cuando vuelva a llover, que ahora no urge."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Preparar antes y actuar durante: esperar a que llueva es la peor estrategia.","por_opcion":{"s2":"Que sean naturales no quita que se puedan anticipar y mitigar.","s4":"Justamente en la sequía cada litro perdido cuenta más."}}},{"slug":"agua-6.s4.p14","orden":14,"grupo":"agua-6.s4.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En una sequía, primero falta la {{0}}, después se seca el {{1}} y más tarde bajan los {{2}} y las napas.","banco":[{"id":"w1","texto":"lluvia"},{"id":"w2","texto":"suelo"},{"id":"w3","texto":"ríos"},{"id":"w4","texto":"sol"},{"id":"w5","texto":"aire"},{"id":"w6","texto":"nubes"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La secuencia con retrasos que explica por qué una sequía se nota en etapas."}}]},{"slug":"agua-6.s5","orden":5,"tipo":"leccion","titulo_es":"Nuevas fuentes y viejas soluciones","bajada_es":"Reutilizar, desalinizar, juntar lluvia y dejar de perder: qué opciones hay para que el agua alcance, y cuánto cuestan.","minutos":12,"pasos":[{"slug":"agua-6.s5.p1","orden":1,"grupo":"agua-6.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Primero, no perder","cuerpo":["Antes de buscar agua nueva, conviene no perder la que ya se tiene. En muchas ciudades del mundo, una parte importante del agua potable se pierde en roturas y conexiones de la red antes de llegar a las casas. Reducir esas pérdidas es, muchas veces, la \"fuente nueva\" más barata.","Lo mismo pasa en el riego: pasar de riego por inundación a goteo puede liberar enormes volúmenes de agua sin quitarle a nadie."]},"solucion":{}},{"slug":"agua-6.s5.p2","orden":2,"grupo":"agua-6.s5.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una ciudad pierde el 30 % del agua potable en la red. ¿Cuál es la primera medida que conviene evaluar?","opciones":[{"id":"o1","texto":"Reparar la red para reducir esas pérdidas"},{"id":"o2","texto":"Construir una planta desalinizadora nueva"},{"id":"o3","texto":"Buscar un río nuevo a 200 kilómetros"},{"id":"o4","texto":"Pedirle a la gente que tome menos agua"}]},"solucion":{"clave":["o1"],"explicacion":"Cada litro que se pierde ya fue tratado y bombeado. Recuperarlo suele ser más barato que producir uno nuevo.","por_opcion":{"o3":"Puede hacer falta a futuro, pero perder un tercio del agua tratada es lo primero que hay que resolver."}}},{"slug":"agua-6.s5.p3","orden":3,"grupo":"agua-6.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reutilizar el agua tratada","cuerpo":["El agua cloacal, después de un buen tratamiento, se puede reutilizar para riego de parques, cultivos, usos industriales o limpieza de calles. En algunos países con mucha escasez, incluso se trata hasta niveles potables.","En casa, el agua gris de la ducha o el lavarropas, con cuidados, se puede usar para el inodoro o para regar. Reutilizar reduce tanto la extracción como lo que se vuelca a los ríos."]},"solucion":{}},{"slug":"agua-6.s5.p4","orden":4,"grupo":"agua-6.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Desalinizar","cuerpo":["La desalinización saca la sal del agua de mar o de napas salobres, sobre todo con ósmosis inversa: el agua se empuja a presión a través de membranas que retienen la sal. Es una fuente casi ilimitada en zonas costeras, y varios países áridos dependen de ella.","Tiene costos: necesita mucha energía (y si esa energía viene de combustibles fósiles, suma emisiones), y deja como residuo una salmuera muy concentrada que hay que devolver al mar con cuidado para no dañar la vida marina."]},"solucion":{}},{"slug":"agua-6.s5.p5","orden":5,"grupo":"agua-6.s5.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una ventaja o una desventaja de la desalinización?","grupos":[{"id":"g1","nombre":"Ventaja"},{"id":"g2","nombre":"Desventaja"}],"items":[{"id":"i1","texto":"Fuente casi ilimitada en zonas costeras"},{"id":"i2","texto":"Necesita mucha energía"},{"id":"i3","texto":"No depende de las lluvias"},{"id":"i4","texto":"Deja una salmuera muy concentrada"},{"id":"i5","texto":"Es más cara que otras fuentes"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"La desalinización es una herramienta valiosa en ciertos lugares, no una solución mágica para todos."}},{"slug":"agua-6.s5.p6","orden":6,"grupo":"agua-6.s5.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas fuentes de agua por cuánta energía suelen necesitar por litro, de más a menos.","items":[{"id":"i1","texto":"Desalinizar agua de mar"},{"id":"i2","texto":"Tratar agua cloacal para reutilizarla"},{"id":"i3","texto":"Potabilizar agua de un río cercano"},{"id":"i4","texto":"Reducir las pérdidas de la red"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El orden típico, aunque cada caso cambia. El litro más barato en energía es el que no se pierde.","valores":{"i1":"mucha energía","i2":"energía media","i3":"poca energía","i4":"casi ninguna por litro recuperado"}}},{"slug":"agua-6.s5.p7","orden":7,"grupo":"agua-6.s5.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la desalinización puede sumar emisiones.","items":[{"id":"i1","texto":"La planta necesita mucha energía para empujar el agua por las membranas"},{"id":"i2","texto":"La energía se genera quemando gas"},{"id":"i3","texto":"Quemar gas emite CO₂"},{"id":"i4","texto":"Cada litro desalinizado tiene una huella de carbono"},{"id":"i5","texto":"Las membranas liberan CO₂ del agua de mar"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Agua y energía están conectadas: por eso algunas desalinizadoras nuevas se alimentan con energía solar o eólica."}},{"slug":"agua-6.s5.p8","orden":8,"grupo":"agua-6.s5.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Soluciones antiguas y naturales","cuerpo":["Algunas de las mejores respuestas son antiguas: juntar agua de lluvia en tanques y aljibes, recargar acuíferos dejando que la lluvia se infiltre en zonas preparadas, y proteger los humedales y bosques de las nacientes, que regulan el agua gratis.","Estas soluciones, combinadas con eficiencia y con tecnología donde hace falta, forman una cartera de opciones. Ninguna sola alcanza; juntas, muchas veces sí."]},"solucion":{}},{"slug":"agua-6.s5.p9","orden":9,"grupo":"agua-6.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada solución con su tipo.","izquierda":[{"id":"a1","texto":"Reparar pérdidas de la red"},{"id":"a2","texto":"Planta desalinizadora"},{"id":"a3","texto":"Proteger el humedal de la naciente"},{"id":"a4","texto":"Tanque para juntar lluvia"}],"derecha":[{"id":"b1","texto":"Eficiencia"},{"id":"b2","texto":"Fuente nueva tecnológica"},{"id":"b3","texto":"Solución basada en la naturaleza"},{"id":"b4","texto":"Fuente descentralizada"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Una buena estrategia combina tipos distintos, para no depender de una sola fuente."}},{"slug":"agua-6.s5.p10","orden":10,"grupo":"agua-6.s5.p10","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene incluir en la estrategia de agua de una ciudad costera que sufre sequías? Marcá todo lo razonable.","opciones":[{"id":"o1","texto":"Reducir las pérdidas de la red"},{"id":"o2","texto":"Reutilizar agua tratada para riego de parques"},{"id":"o3","texto":"Evaluar una desalinizadora alimentada con renovables"},{"id":"o4","texto":"Proteger las zonas de recarga del acuífero"},{"id":"o5","texto":"Dejar que cada casa perfore su propio pozo sin control"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Una cartera: eficiencia, reutilización, nueva fuente si hace falta y protección natural. Perforar sin control agrava la intrusión salina."}},{"slug":"agua-6.s5.p11","orden":11,"grupo":"agua-6.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad produce 100 millones de litros por día y pierde el 30 % en la red. Si baja las pérdidas al 15 %, ¿cuántos millones de litros por día más llegan a las casas?","unidad":"millones de litros por día","decimales":0},"solucion":{"valor":15,"tolerancia":0.5,"explicacion":"Antes llegaba el 70 %: 70. Después, el 85 %: 85. Diferencia: 15 millones de litros por día, sin producir un litro más."}},{"slug":"agua-6.s5.p11.v2","orden":11,"grupo":"agua-6.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad produce 80 millones de litros por día y pierde el 25 % en la red. Si baja las pérdidas al 10 %, ¿cuántos millones de litros por día más llegan a las casas?","unidad":"millones de litros por día","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"Antes llegaba el 75 %: 60. Después, el 90 %: 72. Diferencia: 12 millones de litros por día, sin producir un litro más."}},{"slug":"agua-6.s5.p11.v3","orden":11,"grupo":"agua-6.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad produce 150 millones de litros por día y pierde el 40 % en la red. Si baja las pérdidas al 20 %, ¿cuántos millones de litros por día más llegan a las casas?","unidad":"millones de litros por día","decimales":0},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"Antes llegaba el 60 %: 90. Después, el 80 %: 120. Diferencia: 30 millones de litros por día, sin producir un litro más."}},{"slug":"agua-6.s5.p12","orden":12,"grupo":"agua-6.s5.p12","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La desalinización resuelve la escasez de agua en cualquier lugar del país.","razones":[{"id":"r1","texto":"Porque depende de la costa, la energía y el manejo de la salmuera"},{"id":"r2","texto":"Porque el agua de mar ya es potable"},{"id":"r3","texto":"Porque desalinizar no usa energía"}]},"solucion":{"valor":false,"explicacion":"Sirve en zonas costeras (o con napas salobres), necesita mucha energía y deja salmuera. En el interior lejos del mar, llevar agua desalinizada sería carísimo. Es una opción más, no la solución universal.","clave":["r1"]}},{"slug":"agua-6.s5.p13","orden":13,"grupo":"agua-6.s5.p13","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este plan de agua de un municipio y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"Vamos a reducir las pérdidas de la red del 35 % al 20 %."},{"id":"s2","texto":"Y a construir una desalinizadora, aunque estamos a 600 km del mar."},{"id":"s3","texto":"Reutilizaremos el agua tratada para regar las plazas."},{"id":"s4","texto":"La salmuera de la desalinizadora no tiene ningún impacto."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Cada fuente tiene su lugar y su costo. Un buen plan lo reconoce.","por_opcion":{"s2":"Lejos del mar, desalinizar y transportar sería carísimo.","s4":"La salmuera concentrada puede dañar la vida marina si se vuelca sin cuidado."}}},{"slug":"agua-6.s5.p14","orden":14,"grupo":"agua-6.s5.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Antes de buscar agua nueva conviene no {{0}} la que ya hay; la desalinización necesita mucha {{1}}; y reutilizar el agua {{2}} reduce la extracción.","banco":[{"id":"w1","texto":"perder"},{"id":"w2","texto":"energía"},{"id":"w3","texto":"tratada"},{"id":"w4","texto":"beber"},{"id":"w5","texto":"lluvia"},{"id":"w6","texto":"salada"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para cualquier discusión sobre \"nuevas fuentes\"."}}]},{"slug":"agua-6.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: agua y futuro","bajada_es":"Napas, contaminantes, glaciares, sequías y nuevas fuentes, mezclados.","minutos":8,"pasos":[{"slug":"agua-6.s6.p1","orden":1,"grupo":"agua-6.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Agua y futuro». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"agua-6.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la ciudad sin lluvia","bajada_es":"Una ciudad de la costa atlántica entra en su tercer verano seco. Con los números, armá el plan.","minutos":10,"pasos":[{"slug":"agua-6.s7.p1","orden":1,"grupo":"agua-6.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El caso","cuerpo":["Una ciudad costera de 200.000 habitantes toma el agua de un acuífero. Viene de dos veranos secos y el tercero pinta igual. En verano la población se duplica por el turismo. La red pierde el 30 % del agua que produce. En los pozos más cercanos al mar, el agua empezó a salir salobre.","El municipio tiene que armar un plan. Estos son algunos datos: la ciudad produce 80 millones de litros por día en verano; el acuífero puede aportar de forma sostenible unos 60."]},"solucion":{}},{"slug":"agua-6.s7.p2","orden":2,"grupo":"agua-6.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos millones de litros por día se pierden en la red en verano?","unidad":"millones de litros por día","decimales":0,"contexto":"Ciudad costera: produce 80 millones de L/día en verano, pierde el 30 % en la red, el acuífero aporta de forma sostenible 60 millones de L/día. Pozos costeros salobres."},"solucion":{"valor":24,"tolerancia":0.5,"explicacion":"30 % de 80 = 24 millones de litros por día. Es casi lo que la ciudad saca de más respecto de lo sostenible."}},{"slug":"agua-6.s7.p3","orden":3,"grupo":"agua-6.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué señal indica que el acuífero ya está sobreexplotado?","opciones":[{"id":"o1","texto":"Los pozos cercanos al mar dan agua salobre"},{"id":"o2","texto":"En verano hay más turistas en la playa"},{"id":"o3","texto":"La factura de agua es más cara que el año pasado"},{"id":"o4","texto":"Llueve poco en invierno en la ciudad"}],"contexto":"Ciudad costera que toma agua de un acuífero; los pozos cercanos al mar empezaron a dar agua salobre."},"solucion":{"clave":["o1"],"explicacion":"La intrusión salina muestra que la napa dulce bajó tanto que el mar avanza. Es la alarma más clara.","por_opcion":{"o3":"El precio puede cambiar por muchas razones; la intrusión salina es una señal física directa."}}},{"slug":"agua-6.s7.p4","orden":4,"grupo":"agua-6.s7.p4","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la ciudad baja sus pérdidas del 30 % al 15 % y quiere que llegue a las casas la misma agua que hoy (56 millones de litros por día), ¿cuántos millones de litros por día necesita producir? Redondeá a un decimal.","unidad":"millones de litros por día","decimales":1},"solucion":{"valor":65.9,"tolerancia":0.2,"explicacion":"Hoy llega el 70 % de 80 = 56. Con 15 % de pérdidas llega el 85 %: hace falta producir 56 ÷ 0,85 ≈ 65,9 millones: menos que los 80 actuales y más cerca de los 60 sostenibles."}},{"slug":"agua-6.s7.p4.v2","orden":4,"grupo":"agua-6.s7.p4","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la ciudad baja sus pérdidas del 30 % al 10 % y quiere que llegue a las casas la misma agua que hoy (56 millones de litros por día), ¿cuántos millones de litros por día necesita producir? Redondeá a un decimal.","unidad":"millones de litros por día","decimales":1},"solucion":{"valor":62.2,"tolerancia":0.2,"explicacion":"Hoy llega el 70 % de 80 = 56. Con 10 % de pérdidas llega el 90 %: hace falta producir 56 ÷ 0,9 ≈ 62,2 millones: menos que los 80 actuales y más cerca de los 60 sostenibles."}},{"slug":"agua-6.s7.p4.v3","orden":4,"grupo":"agua-6.s7.p4","tipo":"numero","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si la ciudad baja sus pérdidas del 30 % al 20 % y quiere que llegue a las casas la misma agua que hoy (56 millones de litros por día), ¿cuántos millones de litros por día necesita producir? Redondeá a un decimal.","unidad":"millones de litros por día","decimales":1},"solucion":{"valor":70,"tolerancia":0.2,"explicacion":"Hoy llega el 70 % de 80 = 56. Con 20 % de pérdidas llega el 80 %: hace falta producir 56 ÷ 0,8 ≈ 70 millones: menos que los 80 actuales y más cerca de los 60 sostenibles."}},{"slug":"agua-6.s7.p5","orden":5,"grupo":"agua-6.s7.p5","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las medidas del plan por prioridad razonable, empezando por la primera.","items":[{"id":"i1","texto":"Reparar la red para bajar pérdidas"},{"id":"i2","texto":"Reducir el bombeo en los pozos costeros salobres"},{"id":"i3","texto":"Reutilizar agua tratada para regar plazas y canchas"},{"id":"i4","texto":"Evaluar una desalinizadora con energía renovable"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Primero lo que es rápido y barato y frena el daño; después lo que reduce demanda; y al final las fuentes nuevas grandes.","valores":{"i1":"rápida, barata y alivia el acuífero","i2":"frena la intrusión","i3":"baja la demanda de agua potable","i4":"fuente nueva, cara y lenta de construir"}}},{"slug":"agua-6.s7.p6","orden":6,"grupo":"agua-6.s7.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las propuestas que aparecen en el concejo.","grupos":[{"id":"g1","nombre":"Ayudan al acuífero"},{"id":"g2","nombre":"Lo empeoran"}],"items":[{"id":"i1","texto":"Tarifa que premia el bajo consumo en verano"},{"id":"i2","texto":"Habilitar perforaciones libres en toda la costa"},{"id":"i3","texto":"Prohibir el riego de jardines al mediodía"},{"id":"i4","texto":"Llenar piletas con agua de red en plena sequía"},{"id":"i5","texto":"Controlar los pozos privados sin registro"},{"id":"i6","texto":"Postergar la reparación de la red hasta el invierno"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Todo lo que aumenta la extracción cerca de la costa empuja la intrusión salina."}},{"slug":"agua-6.s7.p7","orden":7,"grupo":"agua-6.s7.p7","tipo":"cadena","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué frenar el bombeo costero protege a toda la ciudad.","items":[{"id":"i1","texto":"Se reduce el bombeo en los pozos cercanos al mar"},{"id":"i2","texto":"La napa dulce recupera nivel en esa zona"},{"id":"i3","texto":"La presión del agua dulce frena al mar"},{"id":"i4","texto":"La intrusión salina deja de avanzar tierra adentro"},{"id":"i5","texto":"Los pozos del resto de la ciudad siguen dando agua dulce"},{"id":"i6","texto":"El mar retrocede porque bajó la marea"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Proteger el borde del acuífero es proteger a los pozos de adentro."}},{"slug":"agua-6.s7.p8","orden":8,"grupo":"agua-6.s7.p8","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como la ciudad es costera, la mejor solución es construir ya una desalinizadora y seguir bombeando igual.","razones":[{"id":"r1","texto":"Porque tarda años y mientras tanto la intrusión sigue avanzando"},{"id":"r2","texto":"Porque la desalinización no funciona con agua de mar"},{"id":"r3","texto":"Porque el acuífero se recupera solo aunque se siga bombeando"}]},"solucion":{"valor":false,"explicacion":"Una desalinizadora tarda años, cuesta mucho y necesita energía. Mientras tanto, seguir bombeando igual profundiza la intrusión salina. Primero hay que frenar el daño y reducir pérdidas.","clave":["r1"]}},{"slug":"agua-6.s7.p9","orden":9,"grupo":"agua-6.s7.p9","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un medio publica el plan. Marcá los errores.","segmentos":[{"id":"s1","texto":"La red pierde 24 millones de litros por día en verano."},{"id":"s2","texto":"Los pozos salobres son un problema de los turistas, no del acuífero."},{"id":"s3","texto":"El plan empieza por reparar la red y reducir el bombeo costero."},{"id":"s4","texto":"Con la desalinizadora ya no hará falta cuidar nunca más el agua."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Diagnóstico correcto y prioridades en orden: así se arma un plan de agua que aguante sequías.","por_opcion":{"s2":"El agua salobre es intrusión salina por sobreexplotación del acuífero.","s4":"Toda fuente tiene costos y límites: cuidar el agua sigue siendo necesario."}}}]}]}$ac$::jsonb);
